import React from 'react';
import { X } from 'lucide-react';
import { extractYouTubeVideoId } from '../../utils/linkUtils';

interface LinkPreviewProps {
  url: string;
  onRemove: () => void;
}

export function LinkPreview({ url, onRemove }: LinkPreviewProps) {
  const videoId = extractYouTubeVideoId(url);
  
  if (!videoId) {
    return null;
  }
  
  const thumbnailUrl = `https://img.youtube.com/vi/${videoId}/hqdefault.jpg`;
  const videoTitle = "YouTube Video"; // In a real app, you'd fetch the actual title

  return (
    <div className="border rounded-lg overflow-hidden bg-white shadow-sm mt-2">
      {/* Preview Container */}
      <div className="flex flex-col">
        {/* Thumbnail */}
        <div className="relative">
          <img 
            src={thumbnailUrl} 
            alt="Video thumbnail" 
            className="w-full h-auto object-cover"
          />
          
          {/* YouTube Play Button Overlay */}
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-12 h-12 bg-red-600 rounded-full flex items-center justify-center">
              <div className="w-0 h-0 border-t-[8px] border-t-transparent border-l-[16px] border-l-white border-b-[8px] border-b-transparent ml-1"></div>
            </div>
          </div>
          
          {/* Remove Button */}
          <button 
            onClick={onRemove}
            className="absolute top-2 right-2 w-8 h-8 bg-black/60 rounded-full flex items-center justify-center text-white hover:bg-black/80 transition-colors"
            aria-label="Remove video"
          >
            <X size={16} />
          </button>
        </div>
      </div>
    </div>
  );
}