import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export type DeliveryMode = 'continuous' | 'throttled';

export interface DeliveryOptions {
  mode: DeliveryMode;
  batchSize: number;
  waitMinutes: number;
  randomizeWait: boolean;
  // flag indicating the user explicitly changed delivery settings
  isCustom?: boolean;
}

const DEFAULT_OPTIONS: DeliveryOptions = {
  mode: 'continuous',
  batchSize: 1,
  waitMinutes: 5,
  randomizeWait: true,
  isCustom: false,
};

interface DeliveryOptionsStore {
  options: DeliveryOptions;
  setMode: (mode: DeliveryMode) => void;
  setBatchSize: (size: number) => void;
  setWaitMinutes: (minutes: number) => void;
  setRandomizeWait: (randomize: boolean) => void;
  resetToDefaults: () => void;
  calculateEstimatedTime: (targetCount: number) => { min: number; max: number };
}

export const useDeliveryOptions = create<DeliveryOptionsStore>()(
  persist(
    (set, get) => ({
      options: DEFAULT_OPTIONS,
      
      setMode: (mode: DeliveryMode) => {
            set((state) => ({
              options: { ...state.options, mode, isCustom: true }
            }));
      },
      
      setBatchSize: (size: number) => {
        const clamped = Math.max(1, Math.min(20, size));
        set((state) => ({
          options: { ...state.options, batchSize: clamped, isCustom: true }
        }));
      },
      
      setWaitMinutes: (minutes: number) => {
        const clamped = Math.max(1, Math.min(120, minutes));
        set((state) => ({
          options: { ...state.options, waitMinutes: clamped, isCustom: true }
        }));
      },
      
      setRandomizeWait: (randomize: boolean) => {
        set((state) => ({
          options: { ...state.options, randomizeWait: randomize, isCustom: true }
        }));
      },
      
      resetToDefaults: () => {
        set({ options: DEFAULT_OPTIONS });
      },
      
      calculateEstimatedTime: (targetCount: number) => {
        const { options } = get();
        if (options.mode === 'continuous' || targetCount <= 1) {
          return { min: 0, max: 0 };
        }

        const cycles = Math.ceil(targetCount / options.batchSize);
        const baseTime = (cycles - 1) * options.waitMinutes;

        if (options.randomizeWait) {
          const min = Math.round(baseTime * 0.7);
          const max = Math.round(baseTime * 1.5);
          return { min, max };
        }

        return { min: baseTime, max: baseTime };
      },
    }),
    {
      name: 'delivery-options',
    }
  )
);
