import React, { useState, useRef, useEffect } from 'react';
import { X, Plus, GripVertical, Save, ChevronDown, Info, ExternalLink, Shuffle, Trash2, Edit } from 'lucide-react';
import { buildSpintax } from './lib/spintax';
import { trackEvent } from './utils/analytics';
import { getTemplates, saveTemplate, SpintaxTemplate, templateExists, deleteTemplate } from './utils/spintaxTemplates';
import { validateAllOptions } from '../../../utils/spintaxValidation';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '../../../components/ui/dropdown-menu';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '../../../components/ui/dialog';
import { Input } from '../../../components/ui/input';
import { Button } from '../../../components/ui/button';
import { useToast } from './hooks/use-toast';

interface SpintaxDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  onInsertSpintax: (spintaxText: string) => void;
  selectedText?: string;
}

export function SpintaxDrawer({
  isOpen,
  onClose,
  onInsertSpintax,
  selectedText,
}: SpintaxDrawerProps) {
  const [options, setOptions] = useState<string[]>([selectedText || '', '']);
  const [errors, setErrors] = useState<Map<number, string>>(new Map());
  const [showManualHint, setShowManualHint] = useState(false);
  const [templates, setTemplates] = useState<SpintaxTemplate[]>([]);
  const [saveDialogOpen, setSaveDialogOpen] = useState(false);
  const [templateName, setTemplateName] = useState('');
  const [overwriteWarning, setOverwriteWarning] = useState(false);
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);
  const { toast } = useToast();

  // Load templates on mount
  useEffect(() => {
    if (isOpen) {
      setTemplates(getTemplates());
      // Reset to initial state with selected text - only when drawer opens
      const initialOptions = selectedText ? [selectedText, ''] : ['', ''];
      setOptions(initialOptions);
      setErrors(new Map());
    }
  }, [isOpen]);

  // Focus first input when opened
  useEffect(() => {
    if (isOpen) {
      setTimeout(() => {
        inputRefs.current[0]?.focus();
      }, 100);
    }
  }, [isOpen]);

  const addOption = () => {
    if (options.length < 8) {
      setOptions([...options, '']);
      setTimeout(() => {
        inputRefs.current[options.length]?.focus();
      }, 0);
    } else {
      toast({
        title: 'Maximum reached',
        description: 'You can add up to 8 options',
        variant: 'destructive',
      });
    }
  };

  const removeOption = (index: number) => {
    if (options.length > 2) {
      const newOptions = options.filter((_, i) => i !== index);
      setOptions(newOptions);
      // Clear error for this index
      const newErrors = new Map(errors);
      newErrors.delete(index);
      setErrors(newErrors);
    }
  };

  const updateOption = (index: number, value: string) => {
    const newOptions = [...options];
    newOptions[index] = value;
    setOptions(newOptions);
    
    // Clear error for this field
    if (errors.has(index)) {
      const newErrors = new Map(errors);
      newErrors.delete(index);
      setErrors(newErrors);
    }
  };

  const handleInsert = () => {
    // Trim all options
    const trimmedOptions = options.map(opt => opt.trim());
    
    // Validate all options
    const validation = validateAllOptions(trimmedOptions);
    
    if (!validation.valid) {
      setErrors(validation.errors);
      return;
    }
    
    // Filter non-empty options
    const filledOptions = trimmedOptions.filter(opt => opt.length > 0);
    
    if (filledOptions.length < 2) {
      toast({
        title: 'Not enough options',
        description: 'Add at least two options',
        variant: 'destructive',
      });
      return;
    }

    const coreSpintax = buildSpintax(filledOptions);
    
    if (!coreSpintax) {
      toast({
        title: 'Error',
        description: 'Failed to build spintax',
        variant: 'destructive',
      });
      return;
    }

    // Preserve or add spaces around the selection so Spintax won't stick to other words
    const originalSelection = selectedText ?? '';
    let leadingWhitespace = originalSelection.match(/^\s*/)?.[0] ?? '';
    let trailingWhitespace = originalSelection.match(/\s*$/)?.[0] ?? '';

    // If user selected only the word (no spaces), add a single space on both sides
    if (!leadingWhitespace && !trailingWhitespace) {
      leadingWhitespace = ' ';
      trailingWhitespace = ' ';
    }

    const spintaxText = `${leadingWhitespace}${coreSpintax}${trailingWhitespace}`;

    trackEvent('spintax_build_insert', {
      count_options: filledOptions.length,
    });

    onInsertSpintax(spintaxText);
    onClose();
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>, index: number) => {
    // Enter adds new option
    if (e.key === 'Enter') {
      e.preventDefault();
      if (options.length < 8) {
        addOption();
      }
    }
    
    // Cmd/Ctrl+Enter inserts
    if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {
      e.preventDefault();
      handleInsert();
    }
  };

  const loadTemplate = (template: SpintaxTemplate) => {
    setOptions([...template.options]);
    setErrors(new Map());
    toast({
      title: 'Template loaded',
      description: `"${template.name}" options loaded`,
    });
    trackEvent('spintax_template_load', { name: template.name });
  };

  const handleEditTemplate = (template: SpintaxTemplate, e: React.MouseEvent) => {
    e.stopPropagation();
    setOptions([...template.options]);
    setTemplateName(template.name);
    setSaveDialogOpen(true);
    setOverwriteWarning(false);
    setErrors(new Map());
    toast({
      title: 'Editing template',
      description: `Editing "${template.name}"`,
    });
  };

  const handleDeleteTemplate = (templateName: string, e: React.MouseEvent) => {
    e.stopPropagation();
    deleteTemplate(templateName);
    setTemplates(getTemplates());
    toast({
      title: 'Template deleted',
      description: `"${templateName}" has been deleted`,
    });
  };

  const openSaveDialog = () => {
    const filledOptions = options.filter(opt => opt.trim().length > 0);
    if (filledOptions.length < 2) {
      toast({
        title: 'Not enough options',
        description: 'Add at least two options before saving',
        variant: 'destructive',
      });
      return;
    }
    setSaveDialogOpen(true);
    setTemplateName('');
    setOverwriteWarning(false);
  };

  const handleSaveTemplate = () => {
    if (!templateName.trim()) {
      toast({
        title: 'Name required',
        description: 'Please enter a template name',
        variant: 'destructive',
      });
      return;
    }

    const exists = templateExists(templateName.trim());
    
    if (exists && !overwriteWarning) {
      setOverwriteWarning(true);
      return;
    }

    const filledOptions = options.filter(opt => opt.trim().length > 0);
    const template: SpintaxTemplate = {
      name: templateName.trim(),
      options: filledOptions,
    };

    saveTemplate(template);
    setTemplates(getTemplates());
    setSaveDialogOpen(false);
    setOverwriteWarning(false);
    
    toast({
      title: exists ? 'Template updated' : 'Template saved',
      description: `"${template.name}" has been ${exists ? 'updated' : 'saved'}`,
    });
    
    trackEvent('spintax_template_save', { name: template.name, overwrite: exists });
  };

  const canInsert = options.filter(opt => opt.trim().length > 0).length >= 2;

  if (!isOpen) return null;

  return (
    <>
      {/* Backdrop */}
      <div 
        className="fixed inset-0 bg-black/20 z-40"
        onClick={onClose}
      />
      
      {/* Modal */}
      <div className="fixed right-4 top-4 w-[340px] max-h-[600px] bg-white shadow-2xl rounded-lg z-50 flex flex-col border border-gray-200 overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between px-3 py-2 border-b bg-white flex-shrink-0">
          <h2 className="text-sm font-semibold text-gray-900">Spintax</h2>
          <div className="flex items-center gap-1">
            {/* Saved Templates Dropdown */}
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <button className="px-2 py-1 text-xs text-gray-600 hover:bg-gray-100 rounded flex items-center gap-1 transition-colors">
                  <span>Templates</span>
                  <ChevronDown size={12} />
                </button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-64 bg-white">
                {templates.length === 0 ? (
                  <div className="px-3 py-2 text-sm text-gray-500">No templates saved</div>
                ) : (
                  templates.map((template) => (
                    <DropdownMenuItem
                      key={template.name}
                      onClick={() => loadTemplate(template)}
                      className="text-sm cursor-pointer px-3 py-2 hover:bg-blue-50 focus:bg-blue-50"
                    >
                      <div className="flex items-center justify-between w-full gap-2">
                        <div className="flex items-center gap-2 flex-1 min-w-0">
                          <Shuffle size={14} className="text-blue-600 flex-shrink-0" />
                          <span className="font-medium text-gray-900 truncate">{template.name}</span>
                        </div>
                        <div className="flex items-center gap-1 flex-shrink-0">
                          <button
                            onClick={(e) => handleEditTemplate(template, e)}
                            className="p-1 hover:bg-blue-100 rounded transition-colors"
                            title="Edit template"
                          >
                            <Edit size={14} className="text-blue-600" />
                          </button>
                          <button
                            onClick={(e) => handleDeleteTemplate(template.name, e)}
                            className="p-1 hover:bg-red-100 rounded transition-colors"
                            title="Delete template"
                          >
                            <Trash2 size={14} className="text-red-600" />
                          </button>
                        </div>
                      </div>
                    </DropdownMenuItem>
                  ))
                )}
              </DropdownMenuContent>
            </DropdownMenu>

            {/* Save as Template */}
            <button
              onClick={openSaveDialog}
              className="px-3 py-1 text-xs bg-blue-50 text-blue-700 hover:bg-blue-100 rounded-full flex items-center gap-1 transition-colors font-semibold border border-blue-200"
              title="Save as template"
            >
              <Save size={13} />
              <span>Save</span>
            </button>

            {/* Close */}
            <button
              onClick={onClose}
              className="p-1 rounded hover:bg-gray-100 transition-colors"
              aria-label="Close"
            >
              <X size={14} className="text-gray-600" />
            </button>
          </div>
        </div>

        {/* Helper Text */}
        <div className="px-3 py-2 bg-blue-50 border-b border-blue-100 space-y-2">
          <div className="flex items-start gap-1.5">
            <Info size={12} className="text-blue-600 mt-0.5 flex-shrink-0" />
            <div className="flex-1">
              <p className="text-xs text-gray-700 leading-relaxed">
                Add variations for the selected text. One option will be chosen when posting.
              </p>
              
              {selectedText && (
                <div className="mt-2 space-y-1">
                  <div className="flex items-center gap-1">
                    <span className="text-xs font-semibold text-gray-700">Selected text:</span>
                    <code className="px-1.5 py-0.5 bg-white border border-blue-200 rounded text-xs font-mono text-gray-900">
                      {selectedText}
                    </code>
                  </div>
                  {options.filter(opt => opt.trim().length > 0).length >= 2 && (
                    <div className="flex items-center gap-1">
                      <span className="text-xs font-semibold text-gray-700">Preview:</span>
                      <code className="px-1.5 py-0.5 bg-white border border-blue-200 rounded text-xs font-mono text-blue-700">
                        {buildSpintax(options.filter(opt => opt.trim().length > 0))}
                      </code>
                    </div>
                  )}
                </div>
              )}

              {!selectedText && (
                <div className="mt-1 flex items-center gap-1">
                  <span className="text-xs text-gray-600">Example:</span>
                  <code className="px-1.5 py-0.5 bg-white border border-blue-200 rounded text-xs font-mono text-blue-700">
                    {'{fast|quick|rapid}'}
                  </code>
                </div>
              )}

              <button
                onClick={() => setShowManualHint(!showManualHint)}
                className="mt-1 text-xs text-blue-600 hover:text-blue-700 flex items-center gap-0.5"
              >
                <span>How to type it manually</span>
                <ExternalLink size={10} />
              </button>
              {showManualHint && (
                <p className="mt-1 text-xs text-gray-600 leading-relaxed">
                  You can also type it manually like <code className="text-blue-700">{'{fast|quick|rapid}'}</code> directly in the editor.
                </p>
              )}
            </div>
          </div>
        </div>

        {/* Content - Scrollable */}
        <div className="flex-1 overflow-y-auto p-3 space-y-2" style={{maxHeight:"225px",overflowY:"scroll"}}>
          {/* Options List */}
          <div className="space-y-1.5">
            {options.map((option, index) => (
              <div key={index} className="space-y-0.5">
                {index === 0 && selectedText && (
                  <div className="flex items-center gap-1 mb-1 ml-5">
                    <span className="text-xs font-semibold text-blue-700">Original:</span>
                    <code className="px-1.5 py-0.5 bg-blue-100 border border-blue-300 rounded text-xs font-mono text-blue-900">
                      {selectedText}
                    </code>
                  </div>
                )}
                <div className="flex items-center gap-1.5">
                  <GripVertical size={12} className="text-gray-400 flex-shrink-0 cursor-move" />
                  <input
                    ref={el => inputRefs.current[index] = el}
                    type="text"
                    value={option}
                    onChange={(e) => updateOption(index, e.target.value)}
                    onKeyDown={(e) => handleKeyDown(e, index)}
                    placeholder={`Option ${index + 1}`}
                    className={`flex-1 px-2 py-1.5 border rounded text-xs focus:outline-none focus:ring-1 transition-colors ${
                      errors.has(index) 
                        ? 'border-red-300 focus:ring-red-500 bg-red-50' 
                        : 'border-gray-300 focus:ring-blue-500'
                    }`}
                  />
                  {options.length > 2 && (
                    <button
                      onClick={() => removeOption(index)}
                      className="p-1 text-gray-400 hover:text-red-600 rounded transition-colors"
                      aria-label="Remove option"
                    >
                      <X size={12} />
                    </button>
                  )}
                </div>
                {errors.has(index) && (
                  <p className="text-xs text-red-600 ml-5 pl-1">
                    {errors.get(index)}
                  </p>
                )}
              </div>
            ))}
          </div>

          {/* Add Option Button */}
          {options.length < 8 && (
            <button
              onClick={addOption}
              className="flex items-center justify-center gap-1.5 w-full px-4 py-2 bg-gray-50 text-gray-700 border border-gray-200 rounded-full hover:bg-gray-100 transition-colors text-sm font-semibold"
            >
              <Plus size={14} />
              <span>Add option</span>
            </button>
          )}

          {options.length >= 8 && (
            <p className="text-xs text-gray-500 text-center">
              You can add up to 8 options
            </p>
          )}
        </div>

        {/* Footer */}
        <div className="px-3 py-2 border-t bg-gray-50 space-y-2">
          {/* Insert Button */}
          <button
            onClick={handleInsert}
            disabled={!canInsert}
            title={!canInsert ? 'Add at least two options' : 'Insert spintax'}
            className="w-full py-2.5 bg-blue-600 text-white rounded-full font-semibold hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed text-sm"
          >
            Insert
          </button>

          {/* Keyboard Shortcuts */}
          <p className="text-xs text-gray-500 text-center">
            <kbd className="px-1 py-0.5 bg-white border border-gray-300 rounded text-xs">Enter</kbd> to add •{' '}
            <kbd className="px-1 py-0.5 bg-white border border-gray-300 rounded text-xs">⌘Enter</kbd> to insert •{' '}
            <kbd className="px-1 py-0.5 bg-white border border-gray-300 rounded text-xs">Esc</kbd> to close
          </p>
        </div>
      </div>

      {/* Save Template Dialog */}
      <Dialog open={saveDialogOpen} onOpenChange={setSaveDialogOpen}>
        <DialogContent className="sm:max-w-md bg-white">
          <DialogHeader>
            <DialogTitle className="text-lg font-bold text-gray-900">
              {overwriteWarning ? 'Replace existing template?' : 'Save template'}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4 text-gray-900">
            {overwriteWarning ? (
              <div className="space-y-2">
                <p className="text-sm text-gray-700">
                  A template named <span className="font-semibold text-gray-900">"{templateName}"</span> already exists.
                </p>
                <p className="text-sm text-gray-600">
                  Clicking Replace will update it with your current options.
                </p>
              </div>
            ) : (
              <>
                <div className="space-y-2">
                  <p className="text-sm text-gray-700">
                    Save these variations as a reusable template
                  </p>
                  <p className="text-xs text-gray-600">
                    You'll be able to quickly load these options later from the Templates menu.
                  </p>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-semibold text-gray-900 block">
                    Template name
                  </label>
                  <Input
                    value={templateName}
                    onChange={(e) => setTemplateName(e.target.value)}
                    placeholder="e.g., My Custom Greetings"
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        e.preventDefault();
                        handleSaveTemplate();
                      }
                    }}
                    autoFocus
                    className="bg-white text-gray-900 border-gray-300"
                  />
                </div>
              </>
            )}
          </div>
          <DialogFooter className="gap-2 sm:gap-2">
            <Button
              variant="outline"
              onClick={() => {
                setSaveDialogOpen(false);
                setOverwriteWarning(false);
              }}
              className="font-semibold"
            >
              Cancel
            </Button>
            <Button 
              onClick={handleSaveTemplate}
              className="font-semibold bg-blue-600 hover:bg-blue-700"
            >
              {overwriteWarning ? 'Replace' : 'Save template'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}
