import React, { useState } from 'react';
import { ArrowLeft, Send, CheckCircle } from 'lucide-react';
import { validateEmail, validateRequired } from '../../utils/validation';
import { auth } from '../../lib/firebase';
import { sendPasswordResetEmail } from 'firebase/auth/web-extension';

interface ResetPasswordFormProps {
  onLoginClick: () => void;
}

const ResetPasswordForm: React.FC<ResetPasswordFormProps> = ({ onLoginClick }) => {
  const [email, setEmail] = useState('');
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);
  
  const validate = () => {
    const newErrors: Record<string, string> = {};
    
    if (!validateRequired(email)) {
      newErrors.email = 'Email is required';
    } else if (!validateEmail(email)) {
      newErrors.email = 'Please enter a valid email';
    }
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validate()) return;
    
    setIsSubmitting(true);
    
    try {
      await sendPasswordResetEmail(auth, email);
      setIsSubmitted(true);
    } catch (error) {
      setErrors({ 
        form: 'Failed to send reset email. Please try again.' 
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isSubmitted) {
    return (
      <div className="bg-white rounded-lg shadow-lg overflow-hidden">
        <div className="p-8 text-center">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-green-100 text-green-500 mb-6">
            <CheckCircle className="h-8 w-8" />
          </div>
          <h2 className="text-2xl font-bold text-gray-800 mb-2">Check Your Email</h2>
          <p className="text-gray-600 mb-6">
            We've sent password reset instructions to:<br />
            <span className="font-medium text-gray-800">{email}</span>
          </p>
          <p className="text-sm text-gray-500 mb-6">
            If you don't see the email, check other places it might be, like your junk, spam, social, or other folders.
          </p>
          <button
            type="button"
            onClick={onLoginClick}
            className="w-full bg-blue-500 hover:bg-blue-600 focus:ring-4 focus:ring-blue-200 text-white font-medium py-2.5 px-4 rounded-lg transition-all duration-200"
          >
            Back to Login
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow-lg overflow-hidden transition-all duration-300 transform">
      <div className="p-8">
        <div className="text-center mb-8">
          <h1 className="text-2xl font-bold text-gray-800 mb-2">Reset Password</h1>
          <p className="text-gray-600">We'll send you instructions to reset your password</p>
        </div>
        
        {errors.form && (
          <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-md mb-6 text-sm">
            {errors.form}
          </div>
        )}
        
        <form onSubmit={handleSubmit}>
          <div className="mb-6">
            <label htmlFor="reset-email" className="block text-sm font-medium text-gray-700 mb-2">
              Email Address
            </label>
            <input
              id="reset-email"
              type="text"
              className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:outline-none transition-colors ${
                errors.email ? 'border-red-300 focus:ring-red-100' : 'border-gray-300 focus:ring-blue-100 focus:border-blue-400'
              }`}
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="your@email.com"
              aria-invalid={!!errors.email}
              aria-describedby={errors.email ? 'reset-email-error' : undefined}
            />
            {errors.email && (
              <p id="reset-email-error" className="mt-2 text-sm text-red-600">
                {errors.email}
              </p>
            )}
          </div>
          
          <button
            type="submit"
            className="w-full bg-blue-500 hover:bg-blue-600 focus:ring-4 focus:ring-blue-200 text-white font-medium py-2.5 px-4 rounded-lg transition-all duration-200 flex items-center justify-center mb-4"
            disabled={isSubmitting}
          >
            {isSubmitting ? (
              <span className="inline-block h-5 w-5 border-t-2 border-b-2 border-white rounded-full animate-spin mr-2"></span>
            ) : (
              <Send className="h-5 w-5 mr-2" />
            )}
            {isSubmitting ? 'Sending...' : 'Send Reset Instructions'}
          </button>
          
          <button
            type="button"
            className="w-full bg-gray-50 hover:bg-gray-100 border border-gray-300 text-gray-700 font-medium py-2.5 px-4 rounded-lg transition-all duration-200 flex items-center justify-center"
            onClick={onLoginClick}
          >
            <ArrowLeft className="h-5 w-5 mr-2" />
            Back to Login
          </button>
        </form>
      </div>
    </div>
  );
};

export default ResetPasswordForm;