import React, { useEffect, useRef, useState } from "react";
import * as XLSX from "xlsx";
import {
  ArrowLeft,
  Plus,
  X,
  FileSpreadsheet,
  Link2,
  AlertCircle,
  Download,
  Info,
  Edit2,
  Trash2,
  CheckSquare,
} from "lucide-react";
import { FileUploadInfoDialog } from "./FileUploadInfoDialog";
import { useGroupStore } from "../../stores/groupStore";
import { useToast } from "@/hooks/use-toast";

/** Merged: new UI (JSX) with old core functions preserved (chrome.storage, drag/drop, file parsing, duplicate checks, dialogs) */
export function AddGroupUrls({
  groupName = "New group list",
  initialUrls = [],
  listID = null,
  existingListId = null,
  onBack,
  onAddUrls,
}) {
  // core state preserved
  const [editedGroupName, setEditedGroupName] = useState(groupName);
  const [nameTouched, setNameTouched] = useState(false);
  const [nameError, setNameError] = useState(null);

  const [newUrl, setNewUrl] = useState("");
  const [groups, setGroups] = useState([]);
  const [isDragging, setIsDragging] = useState(false);
  const [duplicateAlert, setDuplicateAlert] = useState({ show: false, url: "" });
  const [showUploadInfo, setShowUploadInfo] = useState(false);
  const [selectedGroups, setSelectedGroups] = useState([]);
  const [uploadSummary, setUploadSummary] = useState({ show: false, newGroups: 0, skippedUrls: 0 });
  const [isNotGroupURL, setIsNotGroupURL] = useState(false);

  // refs
  const nameInputRef = useRef(null);
  const fileInputRef = useRef(null);
  const scrollContainerRef = useRef(null);

  // external hooks
  const { groupLists, removeGroupList } = useGroupStore();
  const { toast } = useToast();

  // helper: facebook group URL check (preserved)
  function isFacebookGroupUrl(url) {
    try {
      const parsedUrl = new URL(url);
      const hostname = parsedUrl.hostname.replace(/^www\./, "").toLowerCase();
      const isFacebookDomain = hostname === "facebook.com" || hostname === "fb.com";
      const pathParts = parsedUrl.pathname.split("/").filter(Boolean);
      const isGroupPath = pathParts[0] === "groups" && pathParts.length >= 2;
      return isFacebookDomain && isGroupPath;
    } catch {
      return false;
    }
  }

  useEffect(()=> {
    setEditedGroupName(groupName)
  }, [groupName]);

  // init from chrome.storage + initialUrls (preserved)
  useEffect(() => {
    setEditedGroupName(groupName);
    try {
      chrome.storage.local.get("editListState").then((appState) => {
        console.warn("loading saved editListState:", appState);
        const edit = appState.editListState || {};
        if (Array.isArray(edit.groupsUrls) && edit.groupsUrls.length) {
          // Normalize loaded URLs into proper group objects (in case they're plain URLs or incomplete)
          const normalized = edit.groupsUrls.map((item, idx) => {
            if (typeof item === "string") {
              // Plain URL string — create a full group object
              return {
                id: crypto.randomUUID(),
                url: item,
                name: `Group ${idx + 1}`,
              };
            }
            // Already a group object — ensure it has required properties
            return {
              id: item.id || crypto.randomUUID(),
              url: item.url || item,
              name: item.name || `Group ${idx + 1}`,
            };
          });
          setGroups(normalized);
        }
        // If a saved editedGroupName exists, prefer it over the incoming prop
        if (typeof edit.editedGroupName === "string" && edit.editedGroupName.trim()) {
          setEditedGroupName(edit.editedGroupName);
        }
      }).catch(() => {});
    } catch (e) {
      // ignore if chrome not available in environment
    }

    if (initialUrls.length > 0) {
      const initialGroups = initialUrls.map((url, index) => ({
        id: crypto.randomUUID(),
        url,
        name: `Group ${index + 1}`,
      }));
      setGroups((prev) => [...prev, ...initialGroups]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // auto-increment new list name behavior (preserved)
  useEffect(() => {
    if (!listID && groupName === "New group list") {
      let newName = "New group list";
      let counter = 1;
      while (groupLists?.some((list) => list.name.toLowerCase() === newName.toLowerCase())) {
        newName = `New group list ${counter}`;
        counter++;
      }
      if (newName !== groupName) {
        setEditedGroupName(newName);
      }
    }

    nameInputRef.current?.focus();
    nameInputRef.current?.select();
  }, [groupName, groupLists, listID]);

  // name validation (preserved)
  useEffect(() => {
    if (!nameTouched) return;
    if (!editedGroupName || !editedGroupName.trim()) return setNameError("Please enter a list name.");
    if (editedGroupName.trim().length > 80) return setNameError("Name is too long.");

    const isDuplicate = groupLists?.some(
      (list) => list.name.toLowerCase() === editedGroupName.trim().toLowerCase() && list.id !== listID
    );
    if (isDuplicate) return setNameError("A list with this name already exists.");

    setNameError(null);
  }, [editedGroupName, nameTouched, groupLists, listID]);

  // persist current groups to chrome.storage.editListState (preserved)
  useEffect(() => {
    try {
      chrome.storage.local.get("editListState").then(async (appState) => {
        if (appState.editListState?.showAddUrls) {
          let data = appState;
          data["editListState"]["groupsUrls"] = groups;
          await chrome.storage.local.set(data);
        }
      });
    } catch {
      // ignore if chrome not available
    }
  }, [groups]);

  // small helper to check continue/save eligibility
  const canContinue = editedGroupName && editedGroupName.trim().length > 0 && groups.length > 0 && !nameError;

  // --------------------
  // CORE HANDLERS (preserved)
  // --------------------

  const handleAddUrl = () => {
    const trimmedUrl = newUrl.trim();
    if (trimmedUrl) {
      if (groups.some((g) => g.url === trimmedUrl)) {
        setDuplicateAlert({ show: true, url: trimmedUrl });
        return;
      }

      const newGroup = {
        id: crypto.randomUUID(),
        url: trimmedUrl,
        name: `Group ${groups.length + 1}`,
      };

      setGroups((prev) => [...prev, newGroup]);
      setNewUrl("");
      setIsNotGroupURL(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter") {
      handleAddUrl();
    }
  };

  const handleRemoveGroup = (id) => {
    setGroups((prev) => prev.filter((group) => group.id !== id));
    setSelectedGroups(selectedGroups.filter((gid) => gid !== id));
  };

  const handleEditGroup = (id, url) => {
    // Update the group's URL (not its display name) when editing
    setGroups((prev) => prev.map((group) => (group.id === id ? { ...group, url } : group)));
  };

  const beginEditGroup = (id) => {
    console.log('beginEditGroup called for id:', id, 'current groups:', groups);
    setGroups(prevGroups => {
      const updated = prevGroups.map((group) => (group.id === id ? { ...group, isEditing: true } : group));
      console.log('updated groups:', updated);
      return updated;
    });
  };

  const handleEditGroupKeyDown = (e, id) => {
    if (e.key === "Enter") {
      setGroups((prev) => prev.map((group) => (group.id === id ? { ...group, isEditing: false } : group)));
    }
  };

  const finishEditGroup = (id) => {
    setGroups((prev) => prev.map((group) => (group.id === id ? { ...group, isEditing: false } : group)));
  };

  const toggleGroupSelection = (id) => {
    setSelectedGroups((prev) => (prev.includes(id) ? prev.filter((gid) => gid !== id) : [...prev, id]));
  };

  // file select (kept)
  const handleFileSelect = (e) => {
    const file = e.target.files?.[0];
    if (file) {
      handleFileUpload(file);
      setShowUploadInfo(false);
    }
  };

  // drag/drop handlers (preserved)
  const handleDrop = (e) => {
    e.preventDefault();
    setIsDragging(false);

    const file = e.dataTransfer.files[0];
    if (
      file &&
      (file.name.endsWith(".csv") || file.name.endsWith(".xlsx") || file.name.endsWith(".xls"))
    ) {
      handleFileUpload(file);
      setShowUploadInfo(false);
    } else {
      setUploadSummary({
        show: true,
        newGroups: 0,
        skippedUrls: 0,
      });
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    setIsDragging(false);
  };

  // ORIGINAL handleFileUpload (preserved) — reads file, checks facebook group path pattern
  const handleFileUpload = (file) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result);
        const workbook = XLSX.read(data, { type: "array" });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];

        const range = XLSX.utils.decode_range(worksheet["!ref"] || "A1");
        const urlSet = new Set();
        const existingUrls = new Set(groups.map((g) => g.url));
        const newGroups = [];
        let duplicatesCount = 0;

        for (let row = range.s.r; row <= range.e.r; row++) {
          const cellAddress = XLSX.utils.encode_cell({ r: row, c: 0 });
          const cell = worksheet[cellAddress];

          if (cell && cell.v && typeof cell.v === "string") {
            const url = cell.v.trim();
            if (url && url.includes("facebook.com/groups/")) {
              if (!urlSet.has(url) && !existingUrls.has(url)) {
                urlSet.add(url);
                newGroups.push({
                  id: crypto.randomUUID(),
                  url,
                  name: `Group ${groups.length + newGroups.length + 1}`,
                });
              } else {
                duplicatesCount++;
              }
            }
          }
        }

        if (newGroups.length > 0) {
          setGroups((prevGroups) => [...prevGroups, ...newGroups]);
        }

        setUploadSummary({
          show: true,
          newGroups: newGroups.length,
          skippedUrls: duplicatesCount,
        });
      } catch (error) {
        setUploadSummary({
          show: true,
          newGroups: 0,
          skippedUrls: 0,
        });
      }
    };
    reader.readAsArrayBuffer(file);
  };

  // download sample (preserved)
  const downloadSampleFile = () => {
    const ws = XLSX.utils.aoa_to_sheet([
      ["https://www.facebook.com/groups/754017179061220/"],
      ["https://www.facebook.com/groups/307508187923822/"],
      ["https://www.facebook.com/groups/324145450421516/"],
    ]);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Groups");
    XLSX.writeFile(wb, "facebook-groups-example.xlsx");
  };

  // --------------------
  // UI — new look but wired to preserved functions
  // --------------------
  return (
    <div role="dialog" aria-modal="true" className="w-[350px] h-[95%] bg-white flex flex-col rounded-xl shadow-sm">
      {/* Header (new style) */}
      <div className="border-b px-4 py-3">
        <div className="flex items-center gap-3 mb-3">
          <button
            onClick={onBack}
            className="p-1.5 rounded-lg text-sm font-semibold text-gray-600 hover:bg-gray-100 transition-colors"
            aria-label="Back"
            ref={null}
          >
            <ArrowLeft size={18} className="text-gray-600" />
          </button>
          <h2 className="text-[15px] font-semibold text-gray-900">Add Groups to List</h2>
        </div>

        {/* Editable title */}
        <div>
          <label htmlFor="list-name" className="block text-xs font-medium text-gray-600 mb-1.5">
            List name
          </label>

          <div className="rounded-xl border border-blue-200 bg-blue-50/40 px-3 py-2.5 focus-within:ring-2 focus-within:ring-blue-500">
            <div className="flex items-center gap-2">
              <svg
                width="16"
                height="16"
                viewBox="0 0 24 24"
                fill="none"
                className="text-blue-600 flex-shrink-0"
                aria-hidden="true"
              >
                <path d="M12 20h9" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                <path
                  d="M16.5 3.5a2.121 2.121 0 013 3L8 18l-4 1 1-4 11.5-11.5z"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>

              <input
                id="list-name"
                ref={nameInputRef}
                value={editedGroupName}
                onChange={(e) => setEditedGroupName(e.target.value)}
                onBlur={() => setNameTouched(true)}
                placeholder='Give your list a clear name (e.g., "Q4 Promo")'
                aria-invalid={!!nameError}
                aria-describedby={nameError ? "name-error" : undefined}
                className="flex-1 bg-transparent outline-none text-base font-semibold text-gray-900 placeholder:text-gray-400"
              />
              <Edit2 size={16} className="text-gray-400" />
            </div>
          </div>
          {nameError && (
            <p id="name-error" className="mt-1 text-xs text-red-600">
              {nameError}
            </p>
          )}
        </div>
      </div>

      {/* Body (scrollable) */}
      <div className="flex-1 overflow-y-auto px-4 py-4" ref={scrollContainerRef}>
        {/* Upload area */}
        <div className="mb-4">
          <div className="flex items-center justify-between mb-1">
            <h4 className="text-xs font-medium text-gray-900">Upload Spreadsheet</h4>
            <button
              onClick={downloadSampleFile}
              className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-blue-600 hover:bg-blue-50 transition-colors"
            >
              <Download size={14} />
              <span className="text-xs font-medium text-blue-600">Download Example</span>
            </button>
          </div>
          <p className="text-xs text-gray-500 mb-2">
            Upload a CSV or Excel file with one column containing Facebook group URLs
          </p>

          <label
            className={`block rounded-xl border-2 border-dashed p-2.5 hover:bg-blue-50 cursor-pointer transition-colors ${
              isDragging ? "border-blue-500 bg-blue-50" : "border-gray-200 bg-white"
            }`}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            aria-label="Upload spreadsheet"
          >
            <input
              ref={fileInputRef}
              type="file"
              accept=".csv,.xlsx,.xls"
              className="sr-only"
              onChange={handleFileSelect}
            />
            <div className="flex items-center gap-2">
              <div className="h-9 w-9 rounded-lg bg-blue-100 flex items-center justify-center text-blue-600 flex-shrink-0">
                <FileSpreadsheet size={20} />
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-xs font-medium text-gray-900">Drop file or click to upload</div>
                <div className="text-xs text-gray-600">CSV or Excel (.xlsx, .xls)</div>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-[11px] bg-blue-50 text-blue-700 px-2 py-0.5 rounded-full font-medium">.csv</span>
                <span className="text-[11px] bg-green-50 text-green-700 px-2 py-0.5 rounded-full font-medium">.xlsx</span>
              </div>
            </div>
          </label>
        </div>

        {/* OR divider */}
        <div className="flex items-center gap-3 mb-4">
          <div className="flex-1 h-px bg-gray-200"></div>
          <span className="text-xs font-medium text-gray-500">OR</span>
          <div className="flex-1 h-px bg-gray-200"></div>
        </div>

        {/* Manual input (preserved) */}
        <div className="mb-4">
          <div className="flex items-center gap-2">
            <div className="relative flex-1">
              <svg
                width="16"
                height="16"
                viewBox="0 0 24 24"
                fill="none"
                className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
                aria-hidden="true"
              >
                <path
                  d="M10 13a5 5 0 007.07 0l1.41-1.41a5 5 0 10-7.07-7.07L10 6"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
                <path
                  d="M14 11a5 5 0 01-7.07 0L5.51 9.59a5 5 0 117.07-7.07L14 3"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
              <input
                type="url"
                value={newUrl}
                onChange={(e) => {
                  setNewUrl(e.target.value);
                  setIsNotGroupURL(!isFacebookGroupUrl(e.target.value));
                }}
                onKeyPress={(e) => {
                  if (e.key === "Enter") {
                    handleAddUrl();
                  }
                }}
                placeholder="Paste group link"
                className="w-full h-9 rounded-xl border border-gray-200 pl-9 pr-3 text-xs text-gray-900 placeholder:text-gray-400 bg-gray-50
                    focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent hover:border-gray-300 transition-colors"
              />
            </div>
            <button
              onClick={handleAddUrl}
              disabled={!newUrl.trim() || isNotGroupURL}
              className="h-9 px-3 rounded-xl font-semibold text-xs uppercase tracking-wide bg-blue-600 text-white
                  hover:bg-blue-700 active:bg-blue-800 disabled:bg-blue-300 disabled:cursor-not-allowed transition-colors flex items-center gap-1"
            >
              <Plus size={14} />
              Add
            </button>
          </div>
          {isNotGroupURL && <small className="text-red-800">Enter a valid Facebook Group URL.</small>}
        </div>

        {/* Groups list header */}
        <div className="mb-3 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <h4 className="text-xs font-medium text-gray-900">Added groups</h4>
            <span className="rounded-full bg-gray-100 text-gray-700 text-xs font-medium px-2 py-0.5">{groups.length}</span>
          </div>

          {groups.length > 0 && (
            <button
              onClick={() => {
                if (selectedGroups.length === groups.length) {
                  setSelectedGroups([]);
                } else {
                  setSelectedGroups(groups.map((g) => g.id));
                }
              }}
              className="flex items-center space-x-2 px-3 py-1.5 text-sm font-medium text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
            >
              <CheckSquare size={16} />
              <span>{selectedGroups.length === groups.length ? "Deselect All" : "Select All"}</span>
            </button>
          )}
        </div>

        {/* Groups list (preserved rows & editing) */}
        <div className="space-y-1.5">
          {groups.map((group) => (
            <div
              key={group.id}
              className={`flex items-center px-3 py-2 rounded-xl transition-colors ${
                selectedGroups.includes(group.id) ? "bg-blue-50 hover:bg-blue-100" : "bg-gray-50 hover:bg-gray-100"
              }`}
            >
              <input
                type="checkbox"
                checked={selectedGroups.includes(group.id)}
                onChange={() => toggleGroupSelection(group.id)}
                className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
              />

              <div className="flex-1 min-w-0 ml-3">
                {group.isEditing ? (
                  <input
                    type="url"
                    value={group.url}
                    onChange={(e) => handleEditGroup(group.id, e.target.value)}
                    onBlur={() => finishEditGroup(group.id)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') finishEditGroup(group.id);
                    }}
                    className="w-full px-2 py-1 text-sm bg-white border rounded focus:outline-none focus:ring-1 focus:ring-blue-500"
                    autoFocus
                  />
                ) : (
                  <>
                    <p className="text-sm font-medium text-gray-900 truncate">{group.name || "Group"}</p>
                    <p className="text-xs text-gray-500 truncate">{group.url}</p>
                  </>
                )}
              </div>

              <div className="flex items-center space-x-1 ml-2">
                <button
                  onClick={() => beginEditGroup(group.id)}
                  className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                >
                  <Edit2 size={14} />
                </button>
                <button
                  onClick={() => handleRemoveGroup(group.id)}
                  className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                >
                  <Trash2 size={14} />
                </button>
              </div>
            </div>
          ))}

          {groups.length === 0 && (
            <div className="flex flex-col items-center justify-center py-8">
              <div className="w-12 h-12 bg-gray-100 rounded-full flex items-center justify-center mb-3">
                <Link2 size={20} className="text-gray-400" />
              </div>
              <p className="text-sm text-gray-600 font-medium">No groups added yet</p>
              <p className="text-xs text-gray-500 mt-1">Upload a file or add URLs manually</p>
            </div>
          )}
        </div>
      </div>

      {/* Footer (sticky) */}
      <div className="border-t bg-gray-50/80 backdrop-blur-sm px-4 py-4">
        <div className="flex items-center gap-3">
          <button
              onClick={() => {
                if (!canContinue) {
                  toast?.({
                    title: "No groups added",
                    description: "Add at least one group to continue",
                    variant: "destructive",
                    duration: 1000,
                  });
                  return;
                }
                // pass back the list id when available so parent can update instead of creating
                const listIdToUse = listID || existingListId || null;
                onAddUrls(groups.map((g) => g.url), editedGroupName.trim(), listIdToUse);
                try {
                  chrome.storage.local.remove(["editListState"]);
                } catch {
                  // ignore in non-chrome env
                }
              }}
            disabled={!canContinue}
            className={`flex-1 h-12 rounded-xl font-semibold text-sm uppercase tracking-wide transition-all ${
              canContinue
                ? "bg-blue-600 text-white hover:bg-blue-700 active:bg-blue-800 hover:shadow-md cursor-pointer"
                : "bg-blue-300 text-white cursor-not-allowed"
            }`}
          >
            {/* Continue with {groups.length} {groups.length === 1 ? "Group" : "Groups"} */}
            Save List ({groups.length})
          </button>

          <button
            onClick={onBack}
            className="h-12 px-6 rounded-xl font-medium text-sm text-blue-600 bg-white border-2 border-blue-200 hover:bg-blue-50 hover:border-blue-300 transition-colors uppercase"
          >
            Cancel
          </button>
        </div>
      </div>

      {/* Duplicate Alert Dialog */}
      {duplicateAlert.show && (
        <div className="fixed inset-0 bg-black/30 z-[70] flex items-center justify-center">
          <div className="bg-white w-[300px] rounded-xl shadow-xl p-4 mx-4 animate-scale-in">
            <div className="flex items-start space-x-3">
              <div className="p-2 bg-amber-100 rounded-full">
                <AlertCircle size={20} className="text-amber-600" />
              </div>
              <div className="flex-1">
                <h3 className="text-base font-semibold text-gray-900 mb-1">Duplicate URL</h3>
                <p className="text-sm text-gray-600 mb-3">This URL has already been added to the list.</p>
                <div className="p-2 bg-gray-50 rounded text-xs text-gray-600 break-all mb-4">{duplicateAlert.url}</div>
                <button
                  onClick={() => {
                    setDuplicateAlert({ show: false, url: "" });
                    setNewUrl("");
                  }}
                  className="w-full px-4 py-2 bg-gray-100 text-gray-700 rounded-lg text-sm font-medium hover:bg-gray-200 transition-colors"
                >
                  OK
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Upload Summary Dialog */}
      {uploadSummary.show && (
        <div className="fixed inset-0 bg-black/30 z-[70] flex items-center justify-center">
          <div className="bg-white w-[300px] rounded-xl shadow-xl mx-4 animate-scale-in">
            <div className="p-4">
              <div className="flex items-start space-x-3">
                <div className="p-2 bg-blue-100 rounded-full">
                  <FileSpreadsheet size={20} className="text-blue-600" />
                </div>
                <div className="flex-1">
                  <h3 className="text-lg font-semibold text-gray-900 mb-2">Import Summary</h3>
                  {uploadSummary.newGroups > 0 ? (
                    <>
                      <p className="text-sm text-gray-600 mb-2">
                        Successfully added {uploadSummary.newGroups} new{" "}
                        {uploadSummary.newGroups === 1 ? "group" : "groups"}.
                      </p>
                      {uploadSummary.skippedUrls > 0 && (
                        <p className="text-sm text-amber-600">
                          Skipped {uploadSummary.skippedUrls} duplicate{" "}
                          {uploadSummary.skippedUrls === 1 ? "URL" : "URLs"}.
                        </p>
                      )}
                    </>
                  ) : (
                    <p className="text-sm text-gray-600">No new groups were added. Please check your file format and try again.</p>
                  )}
                  <button
                    onClick={() =>
                      setUploadSummary({
                        show: false,
                        newGroups: 0,
                        skippedUrls: 0,
                      })
                    }
                    className="w-full mt-4 px-4 py-2 bg-gray-100 text-gray-700 rounded-lg text-sm font-medium hover:bg-gray-200 transition-colors"
                  >
                    OK
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* File Upload Info Dialog (kept) */}
      <FileUploadInfoDialog
        isOpen={showUploadInfo}
        onClose={() => setShowUploadInfo(false)}
        onContinue={() => {
          fileInputRef.current?.click();
        }}
        onDownloadSample={downloadSampleFile}
      />
    </div>
  );
}
