import React, { useState } from "react";
import { Eye, EyeOff, LogIn } from "lucide-react";
import { validateEmail, validateRequired } from "../../utils/validation";
import { auth, provider } from "../../lib/firebase";
import { signInWithEmailAndPassword, signInWithPopup } from "firebase/auth/web-extension";
import { toast } from "react-toastify";
import { useNavigate } from "react-router-dom";
import logo from "../../assets/logo.png";

interface LoginFormProps {
  onSignupClick: () => void;
  onResetClick: () => void;
}

const LoginForm: React.FC<LoginFormProps> = ({
  onSignupClick,
  onResetClick,
}) => {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [loginError, setLoginError] = useState("");

  const signInWithGoogle = async () => {
    try {
      // chrome.tabs.create({ url: "https://auth.fbgroupbulkposter.com/signin" });
      chrome.tabs.create({
        url: "https://auth.fbgroupbulkposter.com/",
      });
    } catch (error) {
      console.error("Google Sign-In Error:", error);
    }
  };

  const validate = () => {
    const newErrors: Record<string, string> = {};

    if (!validateRequired(email)) {
      newErrors.email = "Email is required";
    } else if (!validateEmail(email)) {
      newErrors.email = "Please enter a valid email";
    }

    if (!validateRequired(password)) {
      newErrors.password = "Password is required";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validate()) return;

    setIsSubmitting(true);
    setLoginError("");

    try {
      await chrome.storage.sync.set({
        user: {
          email: email,
          uid: null,
        },
      });

      await signInWithEmailAndPassword(auth, email, password)
        .then((userCredential) => {
          toast.success("Login successful!");
          // Login successful
          const user = userCredential.user;
          (async () => {
            const credits = await new Promise((resolve, reject) => {
              chrome.runtime.sendMessage(
                {
                  action: "checkCredits",
                  email: user?.email,
                },
                (response) => {
                  if (chrome.runtime.lastError) {
                    reject(chrome.runtime.lastError.message);
                  } else {
                    resolve(response);
                  }
                }
              );
            });

            chrome.storage.sync.set({
              isPremium: credits?.subscription === "active",
            });
            chrome.storage.sync.set({
              postsRemaining: credits?.postsRemaining,
            });
          })();
          window.location.reload();
          // Now run your function
        })
        .catch((error) => {
          // Handle errors here
          toast.error("Login incomplete. Please try again.");
        });
    } catch (error) {
      toast.info("Please check your email or password.");
    }

    setIsSubmitting(false);
  };

  return (
    <div className="bg-white rounded-lg shadow-lg overflow-hidden transition-all duration-300 transform">
      <div className="p-8">
        <div className="text-center mb-8">
          <img src={logo} alt="Logo" className="mx-auto mb-4 h-12" />
          <h1 className="text-2xl font-bold text-gray-800">Welcome Back</h1>
          <p className="text-gray-600">Sign in to continue to your account</p>
        </div>

        <button
          type="button"
          className="text-white bg-[#4285F4] hover:bg-[#4285F4]/90 focus:ring-4 focus:outline-none focus:ring-[#4285F4]/50 font-medium rounded-lg text-sm px-5 py-2.5 text-center inline-flex items-center dark:focus:ring-[#4285F4]/55 me-2 mb-2 m-auto flex justify-center"
          style={{ width: "100%" }}
          onClick={signInWithGoogle}
        >
          <svg
            className="w-4 h-4 me-2"
            aria-hidden="true"
            xmlns="http://www.w3.org/2000/svg"
            fill="currentColor"
            viewBox="0 0 18 19"
          >
            <path
              fillRule="evenodd"
              d="M8.842 18.083a8.8 8.8 0 0 1-8.65-8.948 8.841 8.841 0 0 1 8.8-8.652h.153a8.464 8.464 0 0 1 5.7 2.257l-2.193 2.038A5.27 5.27 0 0 0 9.09 3.4a5.882 5.882 0 0 0-.2 11.76h.124a5.091 5.091 0 0 0 5.248-4.057L14.3 11H9V8h8.34c.066.543.095 1.09.088 1.636-.086 5.053-3.463 8.449-8.4 8.449l-.186-.002Z"
              clipRule="evenodd"
            />
          </svg>
          Continue with Google
        </button>

        <hr className="mb-2 mt-2" />

        {loginError && (
          <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-md mb-6 text-sm">
            {loginError}
          </div>
        )}

        <form onSubmit={handleSubmit}>
          <div className="mb-6">
            <label
              htmlFor="email"
              className="block text-sm font-medium text-gray-700 mb-2"
            >
              Email
            </label>
            <input
              id="email"
              type="text"
              className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:outline-none transition-colors ${
                errors.email
                  ? "border-red-300 focus:ring-red-100"
                  : "border-gray-300 focus:ring-blue-100 focus:border-blue-400"
              }`}
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="your@email.com"
              aria-invalid={!!errors.email}
              aria-describedby={errors.email ? "email-error" : undefined}
            />
            {errors.email && (
              <p id="email-error" className="mt-2 text-sm text-red-600">
                {errors.email}
              </p>
            )}
          </div>

          <div className="mb-6">
            <div className="flex justify-between mb-2">
              <label
                htmlFor="password"
                className="block text-sm font-medium text-gray-700"
              >
                Password
              </label>
              <button
                type="button"
                className="text-sm text-blue-600 hover:text-blue-800 transition-colors"
                onClick={onResetClick}
              >
                Forgot password?
              </button>
            </div>
            <div className="relative">
              <input
                id="password"
                type={showPassword ? "text" : "password"}
                className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:outline-none transition-colors ${
                  errors.password
                    ? "border-red-300 focus:ring-red-100"
                    : "border-gray-300 focus:ring-blue-100 focus:border-blue-400"
                }`}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••"
                aria-invalid={!!errors.password}
                aria-describedby={
                  errors.password ? "password-error" : undefined
                }
              />
              <button
                type="button"
                className="absolute inset-y-0 right-0 pr-3 flex items-center"
                onClick={() => setShowPassword(!showPassword)}
                aria-label={showPassword ? "Hide password" : "Show password"}
              >
                {showPassword ? (
                  <EyeOff className="h-5 w-5 text-gray-400" />
                ) : (
                  <Eye className="h-5 w-5 text-gray-400" />
                )}
              </button>
            </div>
            {errors.password && (
              <p id="password-error" className="mt-2 text-sm text-red-600">
                {errors.password}
              </p>
            )}
          </div>

          <button
            type="submit"
            className="w-full bg-blue-500 hover:bg-blue-600 focus:ring-4 focus:ring-blue-200 text-white font-medium py-2.5 px-4 rounded-lg transition-all duration-200 flex items-center justify-center"
            disabled={isSubmitting}
          >
            {isSubmitting ? (
              <span className="inline-block h-5 w-5 border-t-2 border-b-2 border-white rounded-full animate-spin mr-2"></span>
            ) : (
              <LogIn className="h-5 w-5 mr-2" />
            )}
            {isSubmitting ? "Signing in..." : "Sign In"}
          </button>
        </form>
      </div>

      <div className="py-4 px-8 bg-gray-50 border-t border-gray-100 text-center">
        <p className="text-sm text-gray-600">
          Don't have an account?{" "}
          <button
            type="button"
            className="text-blue-600 hover:text-blue-800 font-medium transition-colors"
            onClick={onSignupClick}
          >
            Sign Up
          </button>
        </p>
      </div>
    </div>
  );
};

export default LoginForm;
