import { useEffect } from 'react';
import { usePostStore } from '../stores/postStore';

export function useSubscription(email?: string) {
  const subscription = usePostStore((state) => state.subscription);
  const subscriptionLoading = usePostStore((state) => state.subscriptionLoading);
  const subscriptionError = usePostStore((state) => state.subscriptionError);
  const isPremium = usePostStore((state) => state.isPremium);
  const fetchSubscription = usePostStore((state) => state.fetchSubscription);

  useEffect(() => {
    if (email) {
      fetchSubscription(email);
    }
  }, [email, fetchSubscription]);

  return {
    subscription,
    subscriptionLoading,
    subscriptionError,
    isPremium,
    refetch: (force = false) => email && fetchSubscription(email, force)
  };
}
