import React from 'react';
import { Clock, CheckCircle2 } from 'lucide-react';
import { formatTimeRemaining } from './utils';
import type { PostProgressStats } from './types';

interface PostProgressHeaderProps {
  isComplete: boolean;
  timeRemaining: number;
  stats: PostProgressStats;
}

export function PostProgressHeader({ isComplete, timeRemaining, stats }: PostProgressHeaderProps) {
  return (
    <div className="bg-gradient-to-r from-blue-500 to-blue-600 px-4 py-4 text-white">
      <div className="flex items-center space-x-3">
        <div className="w-10 h-10 bg-white/10 rounded-lg flex items-center justify-center backdrop-blur-sm">
          {isComplete ? (
            <CheckCircle2 className="w-6 h-6" />
          ) : (
            <Clock className="w-6 h-6" />
          )}
        </div>
        <div>
          <h2 className="text-lg font-semibold">
            {isComplete ? 'Posting Complete!' : 'Posting in Progress'}
          </h2>
          <p className="text-sm text-blue-100">
            {isComplete ? (
              `Posted to ${stats.successful} of ${stats.total} groups`
            ) : (
              `Estimated time remaining: ${formatTimeRemaining(timeRemaining)}`
            )}
          </p>
        </div>
      </div>
    </div>
  );
}