export async function buildCheckoutUrlFromEmail(email?: string | null): Promise<string> {
  const base = 'https://server.fbgroupbulkposter.com/';
  const params = new URLSearchParams();
  params.set('checkout', 'true');

  // Only include email param if provided
  const safeEmail = email ? String(email).trim() : null;
  if (safeEmail) {
    params.set('email', safeEmail);
  }

  // Try to fetch user info only if we have an email
  if (safeEmail) {
    try {
      const res = await fetch(`${base}user?email=${encodeURIComponent(safeEmail)}`);
      if (res.ok) {
        const data = await res.json();
        const displayName = data?.displayName;
        if (displayName && typeof displayName === 'string' && displayName.trim().length > 0) {
          const parts = displayName.trim().split(/\s+/);
          if (parts.length === 1) {
            params.set('fname', parts[0]);
          } else if (parts.length >= 2) {
            params.set('fname', parts[0]);
            params.set('lname', parts[parts.length - 1]);
          }
        }
      }
    } catch (e) {
      // ignore fetch errors and return link with whatever params we have
      console.error('Failed to fetch user for checkout URL', e);
    }
  }

  const query = params.toString();
  return `${base}?${query}`;
}
