export interface SpintaxTemplate {
  name: string;
  options: string[];
}

const STORAGE_KEY = 'spintax_templates_v1';

function readStorage(): SpintaxTemplate[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    return JSON.parse(raw) as SpintaxTemplate[];
  } catch {
    return [];
  }
}

function writeStorage(items: SpintaxTemplate[]) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  } catch {
    // ignore
  }
}

export function getTemplates(): SpintaxTemplate[] {
  return readStorage();
}

export function templateExists(name: string): boolean {
  const items = readStorage();
  return items.some(t => t.name === name);
}

export function saveTemplate(template: SpintaxTemplate) {
  const items = readStorage();
  const idx = items.findIndex(t => t.name === template.name);
  if (idx >= 0) {
    items[idx] = template;
  } else {
    items.push(template);
  }
  writeStorage(items);
}

export function deleteTemplate(name: string) {
  const items = readStorage().filter(t => t.name !== name);
  writeStorage(items);
}
