import React, { useEffect, useRef } from 'react';
import { Send, Check } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '../../ui/dialog';
import { Button } from '../../ui/button';
import { useToast } from '../../../hooks/use-toast';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../../ui/select';
import { Checkbox } from '../../ui/checkbox';

interface FeedbackModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function FeedbackModal({ isOpen, onClose }: FeedbackModalProps) {
  const [feedbackType, setFeedbackType] = React.useState('general');
  const [message, setMessage] = React.useState('');
  const [includeTechInfo, setIncludeTechInfo] = React.useState(true);
  const [isSubmitting, setIsSubmitting] = React.useState(false);
  const [isSubmitted, setIsSubmitted] = React.useState(false);
  const email = useRef('')
  const { toast } = useToast();

  useEffect(() => {
      (async () => {
        let user = await chrome.storage.sync.get(["user"]);
        email.current = user.user?.email || '';
      })();
    }, []);

  const handleClose = () => {
    setMessage('');
    setFeedbackType('general');
    setIncludeTechInfo(true);
    setIsSubmitted(false);
    onClose();
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!message.trim()) {
      toast({
        title: "Message required",
        description: "Please enter your feedback before submitting.",
        variant: "destructive",
      });
      return;
    }

    setIsSubmitting(true);
    try {
      const payload: any = {
        feedback_type: feedbackType,
        message: message.trim(),
        email: email.current.trim(),
      };

      if (includeTechInfo) {
        payload.meta = {
          user_agent: typeof navigator !== 'undefined' ? navigator.userAgent : undefined,
          url: typeof window !== 'undefined' ? window.location.href : undefined,
        };
      }

      const res = await fetch('https://server.fbgroupbulkposter.com/feedback', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload),
      });

      const data = await res.json().catch(() => ({}));

      if (!res.ok) {
        throw new Error(data?.message || `Server responded with ${res.status}`);
      }

      setIsSubmitting(false);
      setIsSubmitted(true);
      toast({
        title: 'Feedback sent',
        description: 'Thanks — we received your feedback.',
      });

      // Auto close after 2 seconds
      setTimeout(() => {
        handleClose();
      }, 2000);
    } catch (err: any) {
      setIsSubmitting(false);
      console.error('Feedback submit error:', err);
      toast({
        title: 'Submission failed',
        description: err?.message || 'Unable to send feedback. Please try again later.',
        variant: 'destructive',
      });
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-md">
        {!isSubmitted ? (
          <>
            <DialogHeader>
              <DialogTitle>Send Feedback</DialogTitle>
              <DialogDescription>
                Tell us what's working, what's not, or what you'd love to see next.
              </DialogDescription>
            </DialogHeader>
            
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-2">
                <label className="text-sm font-medium text-foreground">
                  Type
                </label>
                <Select value={feedbackType} onValueChange={setFeedbackType}>
                  <SelectTrigger className="w-full">
                    <SelectValue placeholder="Select feedback type" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="bug">Bug / Issue</SelectItem>
                    <SelectItem value="feature">Feature request</SelectItem>
                    <SelectItem value="general">General feedback</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-medium text-foreground">
                  Message
                </label>
                <textarea
                  value={message}
                  onChange={(e) => setMessage(e.target.value)}
                  placeholder="Describe your feedback in a few words…"
                  className="w-full min-h-[100px] px-3 py-2 text-sm border border-input rounded-md bg-background resize-none focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                  disabled={isSubmitting}
                  maxLength={1000}
                />
              </div>
              
              <div className="flex gap-2 justify-end pt-2">
                <Button
                  type="button"
                  variant="ghost"
                  onClick={handleClose}
                  disabled={isSubmitting}
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  disabled={isSubmitting || !message.trim()}
                >
                  {isSubmitting ? (
                    <>Sending...</>
                  ) : (
                    <>
                      <Send size={16} />
                      Send
                    </>
                  )}
                </Button>
              </div>
            </form>
          </>
        ) : (
          <div className="py-8 text-center space-y-3">
            <div className="mx-auto w-12 h-12 rounded-full bg-green-100 flex items-center justify-center">
              <Check className="w-6 h-6 text-green-600" />
            </div>
            <div className="space-y-1">
              <h3 className="text-lg font-semibold text-foreground">
                Thanks for your feedback ❤️
              </h3>
              <p className="text-sm text-muted-foreground">
                This really helps us improve.
              </p>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}
