import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { PostStore } from '../types/store';
import { serializePost, deserializePost, serializeDraft, deserializeDraft } from '../utils/storageUtils';

// ============================================================
// IndexedDB Helper Functions for Triple Redundancy (PostStore)
// ============================================================

const DB_NAME_POST = "PostStoreDB";
const DB_VERSION_POST = 1;
const STORE_NAME_POST = "postData";

async function openPostStoreDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME_POST, DB_VERSION_POST);

    request.onerror = () => {
      reject(new Error("Failed to open IndexedDB for PostStore"));
    };

    request.onsuccess = () => {
      resolve(request.result);
    };

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME_POST)) {
        db.createObjectStore(STORE_NAME_POST, { keyPath: "key" });
      }
    };
  });
}

async function saveToIndexedDBPost(key: string, data: any): Promise<void> {
  try {
    const db = await openPostStoreDB();
    const transaction = db.transaction(STORE_NAME_POST, "readwrite");
    const store = transaction.objectStore(STORE_NAME_POST);

    return new Promise((resolve, reject) => {
      const request = store.put({ key, data, timestamp: Date.now() });

      request.onerror = () => {
        reject(new Error("Failed to save to IndexedDB (PostStore)"));
      };

      request.onsuccess = () => {
        resolve();
      };
    });
  } catch (error) {
    console.warn("IndexedDB save failed (PostStore):", error);
  }
}

async function loadFromIndexedDBPost(key: string): Promise<any | null> {
  try {
    const db = await openPostStoreDB();
    const transaction = db.transaction(STORE_NAME_POST, "readonly");
    const store = transaction.objectStore(STORE_NAME_POST);

    return new Promise((resolve, reject) => {
      const request = store.get(key);

      request.onerror = () => {
        reject(new Error("Failed to read from IndexedDB (PostStore)"));
      };

      request.onsuccess = () => {
        resolve(request.result?.data || null);
      };
    });
  } catch (error) {
    console.warn("IndexedDB load failed (PostStore):", error);
    return null;
  }
}

async function removeFromIndexedDBPost(key: string): Promise<void> {
  try {
    const db = await openPostStoreDB();
    const transaction = db.transaction(STORE_NAME_POST, "readwrite");
    const store = transaction.objectStore(STORE_NAME_POST);

    return new Promise((resolve, reject) => {
      const request = store.delete(key);

      request.onerror = () => {
        reject(new Error("Failed to remove from IndexedDB (PostStore)"));
      };

      request.onsuccess = () => {
        resolve();
      };
    });
  } catch (error) {
    console.warn("IndexedDB remove failed (PostStore):", error);
  }
}

// ============================================================
// Multi-Storage Save/Load Helper (PostStore)
// ============================================================

async function saveToAllStoragesPost(key: string, payload: any): Promise<void> {
  const promises: Promise<void>[] = [];

  // 1. Save to chrome.storage
  const isChrome = typeof chrome !== "undefined" && chrome.storage && chrome.storage.local;
  if (isChrome) {
    promises.push(
      new Promise<void>((resolve) => {
        chrome.storage.local.set({ [key]: payload }, () => {
          if ((chrome as any).runtime?.lastError) {
            console.warn("Chrome storage save failed (PostStore):", (chrome as any).runtime.lastError);
          }
          resolve();
        });
      })
    );
  }

  // 2. Save to localStorage
  if (typeof localStorage !== "undefined") {
    try {
      localStorage.setItem(key, JSON.stringify(payload));
    } catch (error) {
      console.warn("localStorage save failed (PostStore):", error);
    }
  }

  // 3. Save to IndexedDB
  promises.push(
    saveToIndexedDBPost(key, payload).catch(err => {
      console.warn("IndexedDB save failed:", err);
    })
  );

  // CRITICAL FIX: AWAIT all saves to complete before returning
  try {
    await Promise.all(promises);
  } catch (error) {
    console.error("One or more storage backends failed (PostStore):", error);
    throw error;
  }
}

async function loadFromAllStoragesPost(key: string): Promise<any | null> {
  const isChrome = typeof chrome !== "undefined" && chrome.storage && chrome.storage.local;

  // 1. Try chrome.storage first
  if (isChrome) {
    try {
      const result = await new Promise<any>((resolve) => {
        chrome.storage.local.get([key], (result) => resolve(result));
      });
      const data = result?.[key];
      if (data) {
        return data;
      }
    } catch (error) {
      console.warn("Chrome storage load failed (PostStore):", error);
    }
  }

  // 2. If empty, try localStorage
  if (typeof localStorage !== "undefined") {
    try {
      const stored = localStorage.getItem(key);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (parsed) {
          // Restore to chrome.storage
          if (isChrome) {
            await new Promise<void>((resolve) => {
              chrome.storage.local.set({ [key]: parsed }, () => resolve());
            });
          }
          return parsed;
        }
      }
    } catch (error) {
      console.warn("localStorage load failed (PostStore):", error);
    }
  }

  // 3. If still empty, try IndexedDB
  try {
    const data = await loadFromIndexedDBPost(key);
    if (data) {
      // Restore to chrome.storage
      if (isChrome) {
        await new Promise<void>((resolve) => {
          chrome.storage.local.set({ [key]: data }, () => resolve());
        });
      }
      return data;
    }
  } catch (error) {
    console.warn("IndexedDB load failed (PostStore):", error);
  }

  return null;
}

export const usePostStore = create<PostStore>()(
  persist(
    (set, _get) => ({
      // State
      scheduledPosts: [],
      draftPost: null,
      selectedGroupId: null,
      error: null,
      isLoading: false,
      postsRemaining: undefined,
      height: "600px",
      width: "400px",
      isPremium: false,
      subscription: null,
      subscriptionLoading: false,
      subscriptionError: null,
      subscriptionLastFetched: null,
      // Track if store has been hydrated from persisted storage
      _hydrated: false,
      setHydrated: (hydrated: boolean) => {
        set({ _hydrated: hydrated });
      },
      setHeight: (height: string)=>{
        set({height:height})
      },
      setWidth: (width: string)=>{
        set({width:width})
      },

      // Actions
      setDraftPost: (draft) => {
        try {
          set({ draftPost: draft });
        } catch (error) {
          console.error("[postStore] Error setting draftPost:", error);
          set({ error: 'Failed to update draft post' });
        }
      },

      addScheduledPost: (post) => {
        try {
          const newPost = {
            id: crypto.randomUUID(),
            content: post.content,
            schedule: post.schedule,
            createdAt: new Date()
          };

          set((state) => ({
            scheduledPosts: [...state.scheduledPosts, newPost],
            draftPost: null,
            error: null
          }));
        } catch (error) {
          set({ error: 'Failed to schedule post' });
        }
      },

      removeScheduledPost: (id) => {
        try {
          set((state) => ({
            scheduledPosts: state.scheduledPosts.filter(post => post.id !== id),
            error: null
          }));
        } catch (error) {
          set({ error: 'Failed to remove post' });
        }
      },

      updateScheduledPost: (id, updates) => {
        try {
          set((state) => ({
            scheduledPosts: state.scheduledPosts.map(post =>
              post.id === id ? { ...post, ...updates } : post
            ),
            error: null
          }));
        } catch (error) {
          set({ error: 'Failed to update post' });
        }
      },

      setSelectedGroup: (groupId) => {
        set({ selectedGroupId: groupId });
      },

      setError: (error) => {
        set({ error });
      },

      setLoading: (isLoading) => {
        set({ isLoading });
      },

      setPostsRemaining: (postsRemaining) => {
        set({ postsRemaining });
      }
      ,
      setIsPremium: (isPremium: boolean) => {
        set({ isPremium });
      },

      fetchSubscription: async (email: string, force = false) => {
        const state = _get();
        const CACHE_DURATION = 5 * 60 * 1000; // 5 minutes cache
        const now = Date.now();
        
        console.log("[fetchSubscription] Called with email:", email, "force:", force);
        
        // If force=true, always fetch (used on page mount)
        // If force=false, skip if recently fetched
        if (!force && state.subscriptionLastFetched && (now - state.subscriptionLastFetched) < CACHE_DURATION) {
          console.log("[fetchSubscription] Skipping - using cache");
          return;
        }

        // Skip if already loading (unless forcing)
        if (!force && state.subscriptionLoading) {
          console.log("[fetchSubscription] Skipping - already loading");
          return;
        }

        console.log("[fetchSubscription] Starting fetch from server...");        try {
          set({ subscriptionLoading: true, subscriptionError: null });
          console.log("[fetchSubscription] Set subscriptionLoading = true");

          const response = await fetch(
            `https://auth.fbgroupbulkposter.com/api/subscription?email=${encodeURIComponent(email)}`
          );
          const data = await response.json();
          console.log("[fetchSubscription] Received response:", data);

          if (data.status === "success" && data.subscription) {
            const subscription = {
              status: data.subscription.status || null,
              payment_method: data.subscription.payment_method,
              plan: data.subscription.plan,
              email: email
            };
            const isPremiumStatus = data.subscription.status === "active";
            console.log("[fetchSubscription] Subscription fetched successfully, isPremium:", isPremiumStatus);
            
            // Update Zustand store
            set({
              subscription,
              isPremium: isPremiumStatus,
              subscriptionLoading: false,
              subscriptionLastFetched: now,
              subscriptionError: null
            });
            
            // CRITICAL: Also update chrome.storage so polling reads correct value
            try {
              await chrome.storage.sync.set({ isPremium: isPremiumStatus });
              console.log("[fetchSubscription] Updated chrome.storage.sync isPremium:", isPremiumStatus);
            } catch (e) {
              console.warn("[fetchSubscription] Failed to update chrome.storage:", e);
            }
          } else {
            console.log("[fetchSubscription] No subscription data in response");
            
            // Update Zustand store
            set({
              subscription: null,
              isPremium: false,
              subscriptionLoading: false,
              subscriptionLastFetched: now,
              subscriptionError: null
            });
            
            // CRITICAL: Also update chrome.storage
            try {
              await chrome.storage.sync.set({ isPremium: false });
              console.log("[fetchSubscription] Updated chrome.storage.sync isPremium: false");
            } catch (e) {
              console.warn("[fetchSubscription] Failed to update chrome.storage:", e);
            }
          }
        } catch (error) {
          set({
            subscriptionLoading: false,
            subscriptionError: error instanceof Error ? error.message : 'Failed to fetch subscription',
            subscriptionLastFetched: now
          });
        }
      },

      clearSubscription: () => {
        set({
          subscription: null,
          subscriptionLoading: false,
          subscriptionError: null,
          subscriptionLastFetched: null,
          isPremium: false
        });
      },

      clearSubscriptionCache: () => {
        set({ subscriptionLastFetched: null });
      }
    }),
    {
      name: 'fb-post-scheduler',
      // FIX: Only persist state properties, not action methods (which cannot be serialized)
      partialize: (state) => ({
        state: {
          scheduledPosts: state.scheduledPosts,
          draftPost: state.draftPost,
          selectedGroupId: state.selectedGroupId,
          error: state.error,
          isLoading: state.isLoading,
          postsRemaining: state.postsRemaining,
          height: state.height,
          width: state.width,
          isPremium: state.isPremium,
          subscription: state.subscription,
          subscriptionLastFetched: state.subscriptionLastFetched,
        }
      }),
      // Mark when hydration from storage completes so components can use the persisted values
      onRehydrateStorage: () => (state, error) => {
        if (error) {
          console.error("[PostStore] Hydration error:", error);
          return;
        }
        
        if (state) {
          console.log("[PostStore] Hydrated with:", {
            selectedGroupId: state.selectedGroupId || "(none)",
            draftPostLength: state.draftPost?.content?.length || 0,
            isPremium: state.isPremium
          });
          state.setHydrated(true);
        }
      },
      storage: {
        getItem: async (name) => {
          // Use the multi-storage load function
          const data = await loadFromAllStoragesPost(name);

          if (!data) {
            return null;
          }

          const result = {
            ...data,
            state: {
              ...data.state,
              scheduledPosts: data.state?.scheduledPosts?.map(deserializePost) || [],
              draftPost: data.state?.draftPost ? deserializeDraft(data.state.draftPost) : null,
              selectedGroupId: typeof data.state?.selectedGroupId === 'string' ? data.state.selectedGroupId : null,
              error: null,
              isLoading: false,
              postsRemaining: typeof data.state?.postsRemaining === 'number' ? data.state.postsRemaining : undefined,
              isPremium: typeof data.state?.isPremium === 'boolean' ? data.state.isPremium : false,
              height: typeof data.state?.height === 'string' ? data.state.height : '600px',
              width: typeof data.state?.width === 'string' ? data.state.width : '400px',
            },
          };
          
          return result;
        },
        setItem: async (name, value) => {
          // Type assertion for zustand persist structure
          const stateValue = value as any;
          
          const payload = {
            ...stateValue,
            state: {
              ...stateValue.state,
              selectedGroupId: typeof stateValue.state?.selectedGroupId === 'string' ? stateValue.state.selectedGroupId : null,
              scheduledPosts: Array.isArray(stateValue.state?.scheduledPosts) ? stateValue.state.scheduledPosts.map(serializePost) : [],
              draftPost: stateValue.state?.draftPost ? serializeDraft(stateValue.state.draftPost) : null,
              error: typeof stateValue.state?.error === 'string' ? stateValue.state.error : null,
              isLoading: Boolean(stateValue.state?.isLoading),
              postsRemaining: typeof stateValue.state?.postsRemaining === 'number' ? stateValue.state.postsRemaining : undefined,
              isPremium: typeof stateValue.state?.isPremium === 'boolean' ? stateValue.state.isPremium : false,
              height: typeof stateValue.state?.height === 'string' ? stateValue.state.height : '600px',
              width: typeof stateValue.state?.width === 'string' ? stateValue.state.width : '400px',
            }
          };

          // Use the multi-storage save function (saves to all 3 places simultaneously)
          await saveToAllStoragesPost(name, payload);
        },
        removeItem: async (name) => {
          const isChrome = typeof chrome !== "undefined" && chrome.storage && chrome.storage.local;

          // Remove from chrome.storage
          if (isChrome) {
            await new Promise<void>((resolve) => {
              chrome.storage.local.remove([name], () => resolve());
            });
          }

          // Remove from localStorage
          if (typeof localStorage !== "undefined") {
            try {
              localStorage.removeItem(name);
            } catch (error) {
              console.warn("localStorage remove failed (PostStore):", error);
            }
          }

          // Remove from IndexedDB
          try {
            await removeFromIndexedDBPost(name);
          } catch (error) {
            console.warn("IndexedDB remove failed (PostStore):", error);
          }
        },
      }
    }
  )
);

// Start short-polling to keep postsRemaining and isPremium in sync with chrome.storage.
// This runs centrally from the store so all components reading the store get updates.
try {
  if (typeof chrome !== "undefined" && chrome?.storage) {
    // Delay start slightly to allow environment to initialize
    setTimeout(() => {
      setInterval(() => {
        try {
          // Use callback-style sync.get and apply safe defaults
          chrome.storage.sync.get(["postsRemaining", "isPremium"], (result) => {
            try {
              const postsRemaining = typeof result?.postsRemaining !== 'undefined' ? result.postsRemaining : 6;
              const isPremium = typeof result?.isPremium !== 'undefined' ? Boolean(result.isPremium) : false;
              const state = usePostStore.getState();
              if (state.setPostsRemaining) state.setPostsRemaining(postsRemaining);
              if (state.setIsPremium) state.setIsPremium(isPremium);
            } catch (err) {
              // ignore per-call errors
            }
          });
        } catch (e) {
          // ignore errors in environments without chrome
        }
      }, 1000);
    }, 300);
  }
} catch (e) {}