import React, { memo } from 'react';
import { X } from 'lucide-react';

export const SelectedDayTag = memo(function SelectedDayTag({ 
  label, 
  onRemove 
}) {
  return (
    <div className="inline-flex items-center space-x-1 bg-white px-2.5 py-1.5 rounded-lg border border-gray-200">
      <span className="text-sm font-medium text-gray-700">{label}</span>
      <button
        onClick={onRemove}
        className="text-gray-400 hover:text-red-500 p-0.5 hover:bg-red-50 rounded-full transition-colors"
      >
        <X size={14} />
      </button>
    </div>
  );
});