import React from 'react';

export function BackgroundColorButton({ onClick, isActive, selectedStyle }) {
  const bg = selectedStyle ? (selectedStyle.type === 'solid' ? selectedStyle.value : selectedStyle.value) : 'linear-gradient(45deg, #FF6B6B, #9B3AF0)';
  const textColor = selectedStyle?.textColor || '#FFFFFF';

  return (
    <button
      onClick={onClick}
      className={`
        w-8 h-8 rounded-full flex items-center justify-center transition-all
        ${isActive 
          ? 'bg-blue-50 text-blue-600' 
          : 'hover:bg-gray-100'
        }
      `}
      title={selectedStyle ? "Background style (selected)" : "Background style"}
    >
      <div 
        className="w-5 h-5 rounded-full flex items-center justify-center font-semibold text-xs"
        style={{
          background: bg,
          color: textColor,
        }}
      >
        Aa
      </div>
    </button>
  );
}