import React from 'react';
import { PartyPopper, ArrowRight } from 'lucide-react';
import confetti from 'canvas-confetti';

export function SuccessDialog({ isOpen, onClose, onContinue }) {
  React.useEffect(() => {
    if (isOpen) {
      confetti({
        particleCount: 100,
        spread: 70,
        origin: { y: 0.6 }
      });
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleContinue = () => {
    onClose();
    onContinue();
  };

  return (
    <div className="fixed inset-0 bg-black/30 z-[60] flex items-center justify-center">
      <div className="bg-white w-full max-w-sm rounded-2xl shadow-xl mx-4 overflow-hidden animate-scale-in">
        {/* Header */}
        <div className="bg-gradient-to-r from-blue-500 to-blue-600 px-6 py-5 text-white">
          <div className="flex items-center space-x-3">
            <div className="w-12 h-12 bg-white/10 rounded-full flex items-center justify-center backdrop-blur-sm">
              <PartyPopper className="w-7 h-7" />
            </div>
            <div>
              <h2 className="text-2xl font-semibold">Almost there!</h2>
              <p className="text-sm text-blue-100">One final step to schedule your post</p>
            </div>
          </div>
        </div>

        {/* Content */}
        <div className="p-6">
          <div className="space-y-4">
            {/* Success message */}
            <div className="flex items-start space-x-3 bg-green-50 rounded-xl px-4 py-3">
              <span className="text-2xl mt-0.5">🎉</span>
              <div>
                <p className="font-medium text-green-800">
                  Great job! You've set up your schedule.
                </p>
              </div>
            </div>

            {/* Next steps */}
            <div className="bg-blue-50 rounded-xl p-4">
              <h3 className="text-sm font-medium text-blue-800 mb-2">Next steps:</h3>
              <ol className="space-y-2 text-sm text-blue-700">
                <li className="flex items-center space-x-2">
                  <span className="w-5 h-5 rounded-full bg-blue-100 flex items-center justify-center text-xs font-medium flex-shrink-0">
                    1
                  </span>
                  <span>Click 'Continue' below</span>
                </li>
                <li className="flex items-center space-x-2">
                  <span className="w-5 h-5 rounded-full bg-blue-100 flex items-center justify-center text-xs font-medium flex-shrink-0">
                    2
                  </span>
                  <span>Click the 'Schedule Post' button to save your post</span>
                </li>
              </ol>
            </div>

            {/* Important note */}
            <div className="bg-amber-50 border border-amber-200 rounded-xl p-3">
              <p className="text-sm text-amber-700 flex items-center space-x-2">
                <span>⚠️</span>
                <span>
                  <span className="font-medium">Important:</span> Keep this browser tab open until the post is scheduled.
                </span>
              </p>
            </div>
          </div>

          {/* Action Button */}
          <div className="mt-6">
            <button
              onClick={handleContinue}
              className="w-full px-4 py-3 text-white bg-blue-600 hover:bg-blue-700 rounded-lg font-medium transition-colors flex items-center justify-center space-x-2 group"
            >
              <span>Continue</span>
              <ArrowRight size={18} className="group-hover:translate-x-0.5 transition-transform" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}