import React, { useEffect, useRef, useState } from "react";
import {
  ArrowLeft,
  Plus,
  Users,
  Edit2,
  Trash2,
  ChevronDown,
} from "lucide-react";
import { AddGroupUrls } from "./AddGroupUrls";
import { useGroupStore } from "../../stores/groupStore";

/**
 * GroupListManager (merged)
 * - Keeps original export name and original state variable names
 * - New UI/UX (rounded, tonal, improved buttons, updated flows)
 * - Uses the newer AddGroupUrls component for the Add / Edit flow
 *
 * Note: kept as plain JS/JSX (not strict TS) to match your original file.
 */

export function GroupListManager({
  selectedId = null,
  isOpen,
  onClose,
  onCreateList,
  onSelectList,
}) {
  // === preserved state names from your old file ===
  const [newListName, setNewListName] = useState("");
  const [selectedListId, setSelectedListId] = useState(null);
  const [showAddUrls, setShowAddUrls] = useState(false);
  const [createdListName, setCreatedListName] = useState("");
  const [editingListId, setEditingListId] = useState(selectedId);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(null);
  const [isDropdownOpen, setIsDropdownOpen] = useState(true); // Always open by default

  const { groupLists, addGroupList, removeGroupList, updateGroupList, setSelectedGroupList } = useGroupStore();

  const nameInputRef = useRef(null);

  // restore in-progress AddUrls state from chrome.storage (preserve old behaviour)
  useEffect(() => {
    try {
      if (chrome && chrome.storage && chrome.storage.local && chrome.storage.local.get) {
        chrome.storage.local.get("editListState").then((appState) => {
          if (appState.editListState && appState.editListState.showAddUrls) {
            setShowAddUrls(true);
            setEditingListId(appState.editListState.editingListId);
            setCreatedListName(appState.editListState.createdListName);
          }
        });
      }
    } catch (e) {
      // ignore if chrome.storage isn't available
      // console.warn("chrome.storage not available", e);
    }
    setEditingListId(selectedId);
  }, []);

  useEffect(() => {
    try {
      if (showAddUrls) {
        chrome.storage.local.set({
          editListState: { showAddUrls, editingListId, createdListName },
        });
      }
    } catch (e) {
      // ignore if chrome.storage isn't available
    }
  }, [showAddUrls, editingListId, createdListName]);

  // If parent provided a selectedId (prop) make AddGroupUrls live with that list's params
  useEffect(() => {
    if (selectedId) {
      const list = groupLists.find((l) => l.id === selectedId);
      if (list) {
        setEditingListId(selectedId);
        setCreatedListName(list.name || "");
        setShowAddUrls(true);
      }
    }
    // note: intentionally not clearing these when selectedId becomes null per instruction
  }, [selectedId, groupLists]);

  // Reset state when dialog opens
  useEffect(() => {
    if (isOpen) {
      setNewListName("");
      setSelectedListId(null);
      setEditingListId(null);
      setShowDeleteConfirm(null);
      setIsDropdownOpen(true); // Always show dropdown when opening
      // focus the name input if present
      setTimeout(() => nameInputRef.current?.focus?.(), 0);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  // === preserved handlers (adapted to new UI) ===
  const handleCreateList = () => {
    if (newListName.trim()) {
      setCreatedListName(newListName.trim());
      setShowAddUrls(true);
      setEditingListId(null);
    }
  };

  const handleEditList = (listId) => {
    const list = groupLists.find((list) => list.id === listId);
    if (list) {
      setEditingListId(listId);
      setCreatedListName(list.name);
      setShowAddUrls(true);
    }
  };

  const handleDeleteList = (listId) => {
    removeGroupList(listId);
    setShowDeleteConfirm(null);
    // if deleted list was selected, clear selection
    if (selectedListId === listId) setSelectedListId(null);
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter" && newListName.trim()) {
      handleCreateList();
    }
  };

  const handleAddUrls = (urls, groupName, listId) => {
    // prefer explicit list id passed from child; fall back to local editingListId
    const idToUse = listId || editingListId || null;
    console.warn("handleAddUrls called with:", { urls, groupName, listId, editingListId });

    if (idToUse) {
      const existingList = groupLists.find((list) => list.id === idToUse);
      if (existingList) {
        // Explicitly update the existing list so subscribers react immediately
        updateGroupList(idToUse, {
          name: groupName,
          count: urls.length,
          urls,
        });
      } else {
        // If id provided but not found, create with provided id
        addGroupList({
          id: idToUse,
          name: groupName,
          count: urls.length,
          urls,
        });
      }

      // select the updated/created list so UI reflects change immediately
      try {
        setSelectedGroupList(idToUse);
      } catch (e) {}

      // notify parent the list was created/updated and provide id
      onSelectList && onSelectList(idToUse);

      setEditingListId(null);
    } else {
      // Create a new group list with the provided URLs
      const newListId = crypto.randomUUID();
      addGroupList({
        id: newListId,
        name: groupName,
        count: urls.length,
        urls,
      });

      // select the newly created list immediately
      try {
        setSelectedGroupList(newListId);
      } catch (e) {}

      // notify parent about the new list id so it can select it too
      onSelectList && onSelectList(newListId);
    }

    // Reset state and close dialogs
    setNewListName("");
    setShowAddUrls(false);
    try {
      chrome.storage.local.remove(["editListState"]);
    } catch (e) {
      // ignore if chrome not available
    }

    // Notify parent component
    onCreateList && onCreateList(groupName);
  };

  const formatDate = (date) => {
    if (!date) return "";
    return new Date(date).toLocaleDateString("en-US", {
      day: "numeric",
      month: "numeric",
      year: "numeric",
    });
  };

  const selectedList = selectedListId
    ? groupLists.find((list) => list.id === selectedListId)
    : null;

  // === UI (updated to new AddGroupUrls style) ===
  return (
    <div
      className="fixed inset-0 bg-black/40 z-[60] flex items-center justify-center px-4"
      role="dialog"
      aria-modal="true"
      aria-label="Manage Group Lists"
    >
      {true ? (
        <AddGroupUrls
          groupName={createdListName}
          initialUrls={
            selectedId
              ? groupLists.find((list) => list.id === selectedId)?.urls || []
              : []
          }
          listID={selectedId}
          existingListId={editingListId}
          onBack={() => {
            setShowAddUrls(false);
            setEditingListId(null);
            setCreatedListName("");
            onClose();
            try {
              chrome.storage.local.remove(["editListState"]);
            } catch (e) {}
          }}
          onAddUrls={handleAddUrls}
        />
      ) : (
        <div className="w-full max-w-md max-h-[90vh] bg-white rounded-2xl shadow-2xl overflow-hidden flex flex-col">
          {/* Header — tonal top, rounded */}
          <div className="px-5 py-4 border-b flex items-center gap-3 sticky top-0 bg-white z-10">
            <button
              onClick={onClose}
              aria-label="Close"
              className="p-2 rounded-lg hover:bg-gray-100 transition-colors"
            >
              <ArrowLeft size={18} className="text-gray-700" />
            </button>

            <div className="flex-1 min-w-0">
              <h2 className="text-lg font-semibold text-gray-900 truncate">
                Manage Group Lists
              </h2>
              <p className="text-xs text-gray-500 mt-0.5 truncate">
                Create, edit or delete lists
              </p>
            </div>

            <div className="flex items-center gap-2">
              <div className="flex items-center text-sm text-gray-500 px-3 py-1 bg-gray-50 rounded-lg gap-2">
                <Users size={16} />
                <span className="hidden sm:inline">Lists</span>
              </div>
            </div>
          </div>

          <div className="p-5 space-y-5 overflow-y-auto flex-1">
            {/* Create New List — new visual */}
            <div className="flex items-center gap-3">
              <div className="flex-1">
                <label htmlFor="newList" className="sr-only">
                  New group list name
                </label>
                <div className="rounded-xl border border-blue-200 bg-blue-50/40 px-3 py-2.5 focus-within:ring-2 focus-within:ring-blue-500">
                  <div className="flex items-center gap-2">
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true" className="text-blue-600 flex-shrink-0">
                      <path d="M12 20h9" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                      <path d="M16.5 3.5a2.121 2.121 0 013 3L8 18l-4 1 1-4 11.5-11.5z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                    <input
                      id="newList"
                      ref={nameInputRef}
                      type="text"
                      value={newListName}
                      onChange={(e) => setNewListName(e.target.value)}
                      onKeyPress={handleKeyPress}
                      placeholder='Give your list a clear name (e.g., "Q4 Promo")'
                      className="w-full bg-transparent outline-none text-sm font-semibold text-gray-900 placeholder:text-gray-400"
                    />
                  </div>
                </div>
              </div>

              <button
                onClick={handleCreateList}
                disabled={!newListName.trim()}
                className="inline-flex items-center gap-2 px-4 py-2.5 bg-blue-600 text-white rounded-xl text-sm font-medium 
                  hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <Plus size={14} />
                <span>Create</span>
              </button>
            </div>

            {/* Selected preview / counts */}
            <div className="flex items-center justify-between gap-3">
              <div className="flex items-center gap-3">
                <div className="text-sm text-gray-700 font-medium">Select a list</div>
                <div className="text-xs text-gray-400">({groupLists.length})</div>
              </div>

              <div className="flex items-center gap-2">
                <div
                  className="px-3 py-1 rounded-full bg-gray-100 text-xs text-gray-600"
                  title={selectedList ? selectedList.name : "No list selected"}
                >
                  {selectedList ? selectedList.name : "None selected"}
                </div>
              </div>
            </div>

            {/* Dropdown selector — updated styling */}
            <div className="relative">
              <button
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className="w-full flex items-center justify-between px-4 py-3 bg-white border border-gray-100 rounded-xl text-left shadow-sm"
                aria-expanded={isDropdownOpen}
              >
                <div className="flex items-center space-x-3">
                  <div className="flex items-center justify-center w-8 h-8 rounded-lg bg-blue-50">
                    <Users size={16} className="text-blue-600" />
                  </div>
                  <div className="min-w-0">
                    <div className="text-sm font-medium text-gray-900 truncate">
                      {selectedList ? selectedList.name : "Choose a group list"}
                    </div>
                    <div className="text-xs text-gray-400 truncate">
                      {selectedList
                        ? `${selectedList.count} ${selectedList.count === 1 ? "URL" : "URLs"}`
                        : "Pick a list to continue"}
                    </div>
                  </div>
                </div>

                <ChevronDown
                  size={18}
                  className={`text-gray-400 transition-transform ${isDropdownOpen ? "rotate-180" : ""}`}
                />
              </button>

              {/* Group list panel */}
              <div className="mt-3 bg-white border border-gray-100 rounded-xl shadow-sm overflow-hidden">
                <div className="max-h-[300px] overflow-y-auto">
                  {groupLists.length > 0 ? (
                    <div className="py-1">
                      {groupLists.map((list) => (
                        <div
                          key={list.id}
                          className={`relative border-b border-gray-100 last:border-b-0 ${
                            selectedListId === list.id ? "bg-blue-50" : ""
                          }`}
                        >
                          <div
                            className="flex items-center justify-between px-4 py-3 hover:bg-gray-50 cursor-pointer"
                            onClick={() => {
                              setSelectedListId(list.id);
                            }}
                          >
                            <div className="flex-1 min-w-0 flex items-center gap-3">
                              <div
                                className={`w-9 h-9 rounded-md flex items-center justify-center text-sm font-semibold ${
                                  selectedListId === list.id ? "bg-blue-100 text-blue-700" : "bg-gray-100 text-gray-700"
                                }`}
                              >
                                {list.name.charAt(0).toUpperCase()}
                              </div>

                              <div className="min-w-0">
                                <div className="flex items-center gap-2">
                                  <span
                                    className={`font-medium truncate ${
                                      selectedListId === list.id ? "text-blue-600" : "text-gray-900"
                                    }`}
                                  >
                                    {list.name}
                                  </span>
                                </div>
                                <div className="text-xs text-gray-500 mt-0.5 flex items-center gap-2">
                                  <span>
                                    {list.count} {list.count === 1 ? "URL" : "URLs"}
                                  </span>
                                  <span className="text-gray-300">•</span>
                                  <span>Created {formatDate(list.createdAt)}</span>
                                </div>
                              </div>
                            </div>

                            {/* Edit/delete buttons — always visible */}
                            <div className="flex items-center space-x-1">
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  handleEditList(list.id);
                                }}
                                className="p-1.5 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                aria-label={`Edit ${list.name}`}
                              >
                                <Edit2 size={16} />
                              </button>
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setShowDeleteConfirm(list.id);
                                }}
                                className="p-1.5 text-gray-500 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                aria-label={`Delete ${list.name}`}
                              >
                                <Trash2 size={16} />
                              </button>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div className="text-center py-8">
                      <p className="text-gray-500 text-sm">No group lists yet</p>
                      <p className="text-gray-400 text-xs mt-2">Create a list to get started</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* Footer Actions (sticky) */}
          <div className="p-4 space-y-3 bg-white border-t sticky bottom-0">
            <button
              onClick={() => selectedListId && onSelectList(selectedListId)}
              disabled={!selectedListId}
              className="w-full px-4 py-3 bg-blue-600 text-white rounded-xl text-sm font-medium 
                hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            >
              Continue with Selected List
            </button>
            <div className="flex gap-2">
              <button
                onClick={() => {
                  // quick shortcut to open AddGroupUrls in create mode with a nice name
                  setCreatedListName(newListName.trim() || "New group list");
                  setShowAddUrls(true);
                }}
                className="flex-1 px-4 py-3 text-sm font-medium bg-white border border-blue-200 text-blue-600 rounded-xl hover:bg-blue-50 transition-colors"
              >
                Import / Add
              </button>
              <button
                onClick={onClose}
                className="flex-1 px-4 py-3 text-sm font-medium text-gray-700 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 transition-colors"
              >
                Back
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation Dialog */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 bg-black/50 z-[70] flex items-center justify-center px-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-5 mx-4 animate-scale-in">
            <h3 className="text-lg font-semibold text-gray-900 mb-2">Delete Group List</h3>
            <p className="text-gray-600 mb-4">
              Are you sure you want to delete this group list? This action cannot be undone.
            </p>
            <div className="flex space-x-3">
              <button
                onClick={() => setShowDeleteConfirm(null)}
                className="flex-1 px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={() => handleDeleteList(showDeleteConfirm)}
                className="flex-1 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
              >
                Delete
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
