import { MessageCircle, Mail, Video, Zap, Check, Copy } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

export function HelpScreen() {
  const [copied, setCopied] = useState(false);
  const handleCopyEmail = () => {
    navigator.clipboard.writeText("support@fbgroupbulkposter.com");
    setCopied(true);
    toast.success("Email copied to clipboard!");
    setTimeout(() => setCopied(false), 2000);
  };
  return (
    <div className="h-full flex flex-col p-6 bg-gradient-to-br from-blue-50 via-white to-indigo-50">
      <div className="space-y-6 max-w-md mx-auto w-full">
        <div className="text-center space-y-3 pt-4">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-2xl shadow-lg">
            <MessageCircle className="w-8 h-8 text-white" strokeWidth={2.5} />
          </div>
          <h2 className="text-3xl font-bold text-gray-900">How can we help?</h2>
          <p className="text-gray-600 text-sm max-w-xs mx-auto leading-relaxed">
            Our support team is available 24/7 for any questions or issues
          </p>
        </div>

        <a
          href="https://www.fbgroupbulkposter.com/help"
          target="_blank"
          rel="noopener noreferrer"
          className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-semibold py-4 px-6 rounded-xl transition-all shadow-lg hover:shadow-xl flex items-center justify-center gap-3 transform hover:scale-[1.02]"
        >
          <MessageCircle className="w-6 h-6" strokeWidth={2.5} />
          <span className="text-base">Open Live Chat</span>
        </a>

        <div className="space-y-3">
          <h3 className="text-sm font-semibold text-gray-700 px-1">
            Other ways to reach us
          </h3>

          <div className="bg-white rounded-xl p-4 shadow-sm border border-gray-100 hover:shadow-md transition-shadow">
            <div className="flex items-start gap-3">
              <div className="w-10 h-10 bg-blue-100 rounded-lg flex items-center justify-center flex-shrink-0">
                <Mail className="w-5 h-5 text-blue-600" />
              </div>
              <div className="flex-1 min-w-0">
                <h4 className="font-semibold text-gray-900 text-sm">
                  Email Support
                </h4>
                <p className="text-xs text-gray-500 mt-0.5 break-all">
                  support@fbgroupbulkposter.com
                </p>
              </div>
              <button
                onClick={handleCopyEmail}
                className="flex-shrink-0 w-8 h-8 bg-blue-50 hover:bg-blue-100 rounded-lg flex items-center justify-center transition-colors"
                title="Copy email"
              >
                {copied ? (
                  <Check className="w-4 h-4 text-green-600" />
                ) : (
                  <Copy className="w-4 h-4 text-blue-600" />
                )}
              </button>
            </div>
          </div>

          {/* Video tutorial card hidden for now */}
          {/* <div className="bg-white rounded-xl p-4 shadow-sm border border-gray-100 hover:shadow-md transition-shadow">
            <div className="flex items-start gap-3">
              <div className="w-10 h-10 bg-purple-100 rounded-lg flex items-center justify-center flex-shrink-0">
                <Video className="w-5 h-5 text-purple-600" />
              </div>
              <div className="flex-1">
                <h4 className="font-semibold text-gray-900 text-sm">
                  Video Tutorials
                </h4>
                <p className="text-xs text-gray-500 mt-0.5">
                  Quick and easy learning
                </p>
              </div>
            </div>
          </div> */}
        </div>
      </div>
    </div>
  );
}
