import React from 'react';
import { ListPlus, AlertCircle } from 'lucide-react';

export function GroupSelectionDialog({ isOpen, onClose, onCreateGroup }) {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/30 z-[60] flex items-center justify-center">
      <div className="bg-white w-full max-w-sm mx-4 rounded-xl shadow-xl animate-scale-in">
        <div className="p-6">
          {/* Icon and Header */}
          <div className="flex items-start space-x-4">
            <div className="w-12 h-12 rounded-full bg-blue-50 flex items-center justify-center flex-shrink-0">
              <AlertCircle className="w-6 h-6 text-blue-600" />
            </div>
            <div className="flex-1">
              <h3 className="text-xl font-semibold text-gray-900 mb-2">
                Hold on! You're almost there.
              </h3>
              <p className="text-gray-600 leading-relaxed">
                💡 Before scheduling your post, please create or select a list of groups you'd like to send it to.
              </p>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="mt-6 space-y-3">
            <button
              onClick={onCreateGroup}
              className="w-full px-4 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium transition-colors flex items-center justify-center space-x-2 group"
            >
              <ListPlus className="w-5 h-5" />
              <span>Create Group List</span>
            </button>
            
            <button
              onClick={onClose}
              className="w-full px-4 py-3 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-lg font-medium transition-colors"
            >
              Back
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}