import { serializeDate, deserializeDate } from './dateUtils';

/**
 * Serializes a schedule configuration for storage
 * @param {import('../types/scheduling').ScheduleConfig} schedule - The schedule to serialize
 * @returns {Object} - The serialized schedule
 */
export const serializeSchedule = (schedule) => ({
  ...schedule,
  startDate: serializeDate(schedule.startDate),
  endDate: schedule.endDate ? serializeDate(schedule.endDate) : undefined
});

/**
 * Deserializes a schedule configuration from storage
 * @param {Object} schedule - The serialized schedule
 * @returns {import('../types/scheduling').ScheduleConfig} - The deserialized schedule
 */
export const deserializeSchedule = (schedule) => ({
  ...schedule,
  startDate: deserializeDate(schedule.startDate),
  endDate: schedule.endDate ? deserializeDate(schedule.endDate) : undefined
});

/**
 * Serializes a post for storage
 * @param {import('../types/scheduling').ScheduledPost} post - The post to serialize
 * @returns {Object} - The serialized post
 */
export const serializePost = (post) => ({
  ...post,
  createdAt: serializeDate(post.createdAt),
  schedule: serializeSchedule(post.schedule)
});

/**
 * Deserializes a post from storage
 * @param {Object} post - The serialized post
 * @returns {import('../types/scheduling').ScheduledPost} - The deserialized post
 */
export const deserializePost = (post) => ({
  ...post,
  createdAt: deserializeDate(post.createdAt),
  schedule: deserializeSchedule(post.schedule)
});

/**
 * Serializes a draft post for storage
 * @param {import('../types/scheduling').DraftPost | null} draft - The draft to serialize
 * @returns {Object | null} - The serialized draft
 */
export const serializeDraft = (draft) => {
  if (!draft) return null;
  return {
    ...draft,
    schedule: draft.schedule ? serializeSchedule(draft.schedule) : null
  };
};

/**
 * Deserializes a draft post from storage
 * @param {Object | null} draft - The serialized draft
 * @returns {import('../types/scheduling').DraftPost | null} - The deserialized draft
 */
export const deserializeDraft = (draft) => {
  if (!draft) return null;
  return {
    ...draft,
    schedule: draft.schedule ? deserializeSchedule(draft.schedule) : null
  };
};