import React from 'react';
import { FileSpreadsheet, Download, Link2, ArrowRight } from 'lucide-react';

export function FileUploadInfoDialog({ isOpen, onClose, onContinue, onDownloadSample }) {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/30 z-[70] flex items-center justify-center">
      <div className="w-[350px] bg-white rounded-xl shadow-xl overflow-hidden animate-scale-in">
        {/* Header */}
        <div className="bg-gradient-to-r from-blue-500 to-blue-600 px-4 py-3 text-white">
          <div className="flex items-center space-x-3">
            <div className="w-9 h-9 bg-white/10 rounded-lg flex items-center justify-center backdrop-blur-sm">
              <FileSpreadsheet className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-base font-semibold">Import Groups from File</h2>
              <p className="text-xs text-blue-100">CSV or XLSX format</p>
            </div>
          </div>
        </div>

        {/* Content */}
        <div className="p-4 space-y-4">
          <p className="text-sm text-gray-600">
            Easily import your Facebook groups using a CSV or XLSX file instead of adding them one by one!
          </p>

          <div className="space-y-2">
            <h3 className="text-sm font-medium text-gray-900 flex items-center space-x-2">
              <span>📌</span>
              <span>How to format your file:</span>
            </h3>
            <ul className="space-y-1.5 text-xs text-gray-600">
              <li className="flex items-start space-x-2">
                <span>•</span>
                <span>One group URL per row in Column A</span>
              </li>
              <li className="flex items-start space-x-2">
                <span>•</span>
                <span>No headers needed - just paste links directly</span>
              </li>
              <li className="flex items-start space-x-2">
                <span>•</span>
                <span>Ensure all links are valid (no empty rows)</span>
              </li>
            </ul>
          </div>

          <div className="space-y-2">
            <h4 className="text-sm font-medium text-gray-900">Example Format:</h4>
            <div className="bg-gray-50 rounded-lg border border-gray-200 overflow-hidden">
              <div className="px-3 py-1.5 bg-gray-100 border-b text-xs font-medium text-gray-500">
                Column A (Group URLs)
              </div>
              <div className="divide-y divide-gray-100">
                {[
                  '754017179061220',
                  '307508187923822',
                  '324145450421516'
                ].map((id) => (
                  <div key={id} className="px-3 py-1.5 hover:bg-blue-50 transition-colors group">
                    <div className="flex items-center space-x-2">
                      <Link2 size={12} className="text-blue-500 flex-shrink-0 opacity-0 group-hover:opacity-100 transition-opacity" />
                      <span className="text-xs text-blue-600 font-medium font-mono truncate">
                        facebook.com/groups/{id}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Sample File Download */}
          <button
            onClick={onDownloadSample}
            className="w-full flex items-center justify-between px-3 py-2 bg-blue-50 hover:bg-blue-100 rounded-lg transition-colors group"
          >
            <div className="flex items-center space-x-2">
              <Download size={14} className="text-blue-600" />
              <span className="text-sm font-medium text-blue-700">Download Example File</span>
            </div>
            <ArrowRight size={14} className="text-blue-500 group-hover:translate-x-0.5 transition-transform" />
          </button>
        </div>

        {/* Action Buttons */}
        <div className="p-4 bg-gray-50 border-t space-y-2">
          <button
            onClick={onContinue}
            className="w-full px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium transition-colors flex items-center justify-center space-x-2 group"
          >
            <span>Upload File</span>
            <ArrowRight size={16} className="group-hover:translate-x-0.5 transition-transform" />
          </button>
          <button
            onClick={onClose}
            className="w-full px-4 py-2 text-gray-700 hover:bg-gray-100 rounded-lg text-sm font-medium transition-colors"
          >
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
}