import React, { useState, useEffect } from 'react';
import { CheckCircle2, XCircle, Clock, AlertCircle, ArrowRight } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { GroupPostStatus } from './types';
import { PostProgressHeader } from './PostProgressHeader';
import { PostProgressStats } from './PostProgressStats';
import { PostProgressList } from './PostProgressList';
import { PostProgressSummary } from './PostProgressSummary';

interface PostProgressManagerProps {
  isOpen: boolean;
  onClose: () => void;
  groupUrls: string[];
  postContent: string;
}

export function PostProgressManager({ isOpen, onClose, groupUrls, postContent }: PostProgressManagerProps) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [groupStatuses, setGroupStatuses] = useState<GroupPostStatus[]>([]);
  const [timeRemaining, setTimeRemaining] = useState(0);
  const [isComplete, setIsComplete] = useState(false);

  // Initialize group statuses
  useEffect(() => {
    if (isOpen && groupUrls.length > 0) {
      const initialStatuses: GroupPostStatus[] = groupUrls.map((url) => ({
        url,
        status: 'pending',
        name: `Group ${url.split('/').pop()}`, // Simplified for example
        error: null
      }));
      setGroupStatuses(initialStatuses);
      setTimeRemaining(groupUrls.length * 5); // Estimate 5 seconds per group
      setCurrentIndex(0);
      setIsComplete(false);
    }
  }, [isOpen, groupUrls]);

  // Timer countdown
  useEffect(() => {
    if (!isOpen || isComplete) return;

    const timer = setInterval(() => {
      setTimeRemaining((prev) => {
        if (prev <= 0) return 0;
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [isOpen, isComplete]);

  // Simulate posting progress
  useEffect(() => {
    if (!isOpen || isComplete) return;

    const postToGroup = async () => {
      // Simulate API call with random success/failure
      await new Promise((resolve) => setTimeout(resolve, 3000 + Math.random() * 2000));
      const success = Math.random() > 0.2; // 80% success rate

      setGroupStatuses((prev) => {
        const updated = [...prev];
        updated[currentIndex] = {
          ...updated[currentIndex],
          status: success ? 'success' : 'error',
          error: success ? null : 'Failed to post to group'
        };
        return updated;
      });

      if (currentIndex < groupUrls.length - 1) {
        setCurrentIndex((prev) => prev + 1);
      } else {
        setIsComplete(true);
      }
    };

    postToGroup();
  }, [currentIndex, groupUrls.length, isOpen, isComplete]);

  if (!isOpen) return null;

  // Calculate statistics
  const stats = {
    total: groupUrls.length,
    completed: groupStatuses.filter(g => g.status === 'success' || g.status === 'error').length,
    successful: groupStatuses.filter(g => g.status === 'success').length,
    failed: groupStatuses.filter(g => g.status === 'error').length,
    pending: groupStatuses.filter(g => g.status === 'pending').length
  };

  return (
    <div className="fixed inset-0 bg-black/30 z-[60] flex items-center justify-center">
      <motion.div 
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.95 }}
        className="bg-white w-[350px] rounded-2xl shadow-xl overflow-hidden"
      >
        {/* Header */}
        <PostProgressHeader 
          isComplete={isComplete}
          timeRemaining={timeRemaining}
          stats={stats}
        />

        {/* Content */}
        <div className="p-4 space-y-4">
          {/* Progress Stats */}
          <PostProgressStats stats={stats} />

          {/* Current Activity */}
          {!isComplete && currentIndex < groupUrls.length && (
            <div className="bg-blue-50 border border-blue-100 rounded-xl p-3">
              <div className="flex items-center space-x-3">
                <div className="w-8 h-8 bg-blue-100 rounded-lg flex items-center justify-center">
                  <Clock size={18} className="text-blue-600 animate-pulse" />
                </div>
                <div>
                  <h3 className="text-sm font-medium text-blue-900">
                    Currently Posting To:
                  </h3>
                  <p className="text-xs text-blue-700 mt-0.5">
                    {groupStatuses[currentIndex]?.name}
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* Groups List */}
          {!isComplete && (
            <PostProgressList 
              groups={groupStatuses}
              currentIndex={currentIndex}
            />
          )}

          {/* Summary (shown when complete) */}
          {isComplete && (
            <PostProgressSummary 
              stats={stats}
              groups={groupStatuses}
            />
          )}
        </div>

        {/* Footer */}
        <div className="border-t bg-gray-50 p-4">
          {isComplete ? (
            <button
              onClick={onClose}
              className="w-full px-4 py-2.5 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors flex items-center justify-center space-x-2"
            >
              <span>Done</span>
              <ArrowRight size={16} className="group-hover:translate-x-0.5 transition-transform" />
            </button>
          ) : (
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-600">
                Please keep this window open
              </span>
              <span className="text-blue-600 font-medium">
                {Math.round((stats.completed / stats.total) * 100)}% Complete
              </span>
            </div>
          )}
        </div>
      </motion.div>
    </div>
  );
}