import { useState } from "react";
import { ChevronLeft, AlertCircle, Clock, CheckCircle } from "lucide-react";

interface UnsubscribePageProps {
  onBack: () => void; // Add onBack prop for navigation
}

export default function UpdatedUnsubscribePage({
  onBack,
}: UnsubscribePageProps) {
  const [showConfirm, setShowConfirm] = useState(false);
  const [showcanceled, setShowcanceled] = useState(false);
  const [cancellingLoader, setCancellingLoader] = useState(false);
  const [cancelSuccessful, setCancelSuccessful] = useState(false);

  const handleUnsubscribe = () => {
    setShowConfirm(true);
  };

  const fetchSubscriptionId = async (email: string) => {
    try {
      if (!email) return null;

      const response = await fetch(
        `https://auth.fbgroupbulkposter.com/api/subscription?email=${encodeURIComponent(email)}`
      );
      const data = await response.json();
      let subscriptionId=null

      if (data.status === "success" && data.subscription) {
        subscriptionId=data?.subscription?.subscription_id || null
      }
      return subscriptionId;
    } catch (error) {
      return null
    }
  };

  const confirmUnsubscribe = () => {
    // cancel-subscription.js

    async function cancelSubscription() {
      let user = await chrome.storage.sync.get(["user"]);
      const subscriptionId = await fetchSubscriptionId(user?.user?.email);
      if(!subscriptionId){
        setCancellingLoader(false);
        setCancelSuccessful(false)
        setShowcanceled(true);
      }
      try {
        setCancellingLoader(true);
        const res = await fetch(
          `https://server.fbgroupbulkposter.com/cancel/${subscriptionId}`,
          {
            method: "POST",
          }
        );
        const data = await res.json();

        setCancellingLoader(false);
        setShowcanceled(true);
        if (data.success) {
          setCancelSuccessful(true);
          chrome.storage.sync.set({
            isPremium: false,
          });
        } else {
          setCancelSuccessful(false);
        }
      } catch (error) {
        console.error("Request failed:", error);
      }
    }

    cancelSubscription();
    // Handle the actual unsubscribe process here
  };

  return (
    <div className="bg-white flex flex-col text-sm font-sans">
      <div className="p-3 bg-blue-600 text-white flex items-center">
        <button
          onClick={onBack}
          className="mr-2 hover:bg-blue-700 rounded-full p-1"
          disabled={cancellingLoader}
        >
          <ChevronLeft size={18} />
        </button>
        <h1 className="text-lg font-bold">Cancel Subscription</h1>
      </div>

      <div className="flex-grow overflow-y-auto p-3">
        {!showConfirm ? (
          <>
            <div className="mb-4">
              <h2 className="text-base font-semibold mb-2 text-gray-800">
                You'll lose these benefits:
              </h2>
              <ul className="space-y-2">
                <li className="flex items-center text-gray-600">
                  <CheckCircle size={16} className="text-green-500 mr-2" />
                  Unlimited posts to multiple groups
                </li>
                <li className="flex items-center text-gray-600">
                  <CheckCircle size={16} className="text-green-500 mr-2" />
                  Priority customer support
                </li>
                <li className="flex items-center text-gray-600">
                  <CheckCircle size={16} className="text-green-500 mr-2" />
                  Your data will be retained for 30 days
                </li>
              </ul>
            </div>
            {/* <div className="mb-4 bg-blue-50 p-3 rounded-md">
              <p className="text-blue-800 flex items-center">
                <Clock size={16} className="mr-2" />
                Your subscription will end on: <strong className="ml-1">September 30, 2023</strong>
              </p>
            </div> */}
            <div className="mb-4">
              <p className="text-gray-600">
                If you're experiencing any issues, please{" "}
                <a href="#" className="text-blue-600 hover:underline">
                  contact our support team
                </a>
                . We're here to help!
              </p>
            </div>
          </>
        ) : (
          <>
            {!showcanceled ? (
              <>
                <div className="flex flex-col items-center justify-center h-full">
                  <AlertCircle size={48} className="text-red-500 mb-4" />
                  <p className="text-center text-gray-700 mb-4">
                    Are you sure you want to cancel your subscription? This
                    action cannot be undone.
                  </p>
                </div>
              </>
            ) : (
              <>
                <div className="min-h-screen flex items-center justify-center bg-gray-100 px-4">
                  <div className="bg-white rounded-2xl shadow-md p-8 max-w-md text-center space-y-4">
                    {cancelSuccessful ? (
                      <>
                        <div className="text-green-500">
                          <svg
                            className="w-16 h-16 mx-auto"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="1.5"
                            viewBox="0 0 24 24"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
                            />
                          </svg>
                        </div>
                        <h2 className="text-2xl font-semibold text-gray-800">
                          Subscription canceled
                        </h2>
                        <p className="text-gray-600">
                          Your subscription has been successfully canceled.
                        </p>
                      </>
                    ) : (
                      <>
                        <div className="text-red-500">
                          <svg
                            className="w-16 h-16 mx-auto"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="1.5"
                            viewBox="0 0 24 24"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              d="M12 9v2m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
                            />
                          </svg>
                        </div>
                        <h2 className="text-2xl font-semibold text-gray-800">
                          Cancellation Failed
                        </h2>
                        <p className="text-gray-600">
                          Something went wrong while cancelling. Please try
                          again later.
                        </p>
                      </>
                    )}
                  </div>
                </div>
              </>
            )}
          </>
        )}
      </div>

      <div className="p-3 border-t border-gray-200">
        {!showConfirm ? (
          <div className="space-y-2">
            <button
              onClick={handleUnsubscribe}
              className="w-full bg-red-500 hover:bg-red-600 text-white p-2 rounded-md transition duration-150 text-sm font-medium"
            >
              Cancel Subscription
            </button>
            {/* <button
              onClick={keepSubscription}
              className="w-full bg-blue-600 hover:bg-blue-700 text-white p-2 rounded-md transition duration-150 text-sm font-medium"
            >
              Keep My Subscription
            </button> */}
          </div>
        ) : (
          <div className="flex space-x-2">
            <button
              onClick={() => setShowConfirm(false)}
              className="flex-1 bg-gray-200 text-gray-800 p-2 rounded-md hover:bg-gray-300 transition duration-150 text-sm font-medium"
            >
              Go Back
            </button>
            <button
              onClick={confirmUnsubscribe}
              className="flex-1 bg-red-500 text-white p-2 rounded-md hover:bg-red-600 transition duration-150 text-sm font-medium"
              disabled={cancellingLoader}
            >
              {cancellingLoader ? "Cancelling..." : "Confirm Cancellation"}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
