import React from 'react';
import { CheckCircle2, XCircle, Clock } from 'lucide-react';
import type { PostProgressStats } from './types';

interface PostProgressStatsProps {
  stats: PostProgressStats;
}

export function PostProgressStats({ stats }: PostProgressStatsProps) {
  return (
    <div className="grid grid-cols-3 gap-2">
      {/* Successful Posts */}
      <div className="bg-green-50 rounded-xl p-3">
        <div className="flex items-center space-x-2">
          <CheckCircle2 size={16} className="text-green-600" />
          <span className="text-xs font-medium text-green-900">Success</span>
        </div>
        <p className="text-lg font-semibold text-green-700 mt-1">
          {stats.successful}
        </p>
      </div>

      {/* Failed Posts */}
      <div className="bg-red-50 rounded-xl p-3">
        <div className="flex items-center space-x-2">
          <XCircle size={16} className="text-red-600" />
          <span className="text-xs font-medium text-red-900">Failed</span>
        </div>
        <p className="text-lg font-semibold text-red-700 mt-1">
          {stats.failed}
        </p>
      </div>

      {/* Pending Posts */}
      <div className="bg-amber-50 rounded-xl p-3">
        <div className="flex items-center space-x-2">
          <Clock size={16} className="text-amber-600" />
          <span className="text-xs font-medium text-amber-900">Pending</span>
        </div>
        <p className="text-lg font-semibold text-amber-700 mt-1">
          {stats.pending}
        </p>
      </div>
    </div>
  );
}