import React from 'react';
import { Info, X } from 'lucide-react';
import { useDeliveryOptions, DeliveryMode, DeliveryOptions } from './Spintax/hooks/useDeliveryOptions';
import { trackEvent } from './Spintax/utils/analytics';

interface DeliveryOptionsDialogProps {
  targetCount: number;
  context: 'schedule' | 'composer';
  onClose: () => void;
  onApply?: (options: DeliveryOptions) => void;
}

export function DeliveryOptionsDialog({ targetCount, context, onClose, onApply }: DeliveryOptionsDialogProps) {
  const options = useDeliveryOptions((state) => state.options);
  const setMode = useDeliveryOptions((state) => state.setMode);
  const setBatchSize = useDeliveryOptions((state) => state.setBatchSize);
  const setWaitMinutes = useDeliveryOptions((state) => state.setWaitMinutes);
  const setRandomizeWait = useDeliveryOptions((state) => state.setRandomizeWait);
  const calculateEstimatedTime = useDeliveryOptions((state) => state.calculateEstimatedTime);

  const estimatedTime = calculateEstimatedTime(targetCount);
  const showEstimate = options.mode === 'throttled' && estimatedTime.max > 0;

  const handleApply = () => {
    onApply?.(options);
    onClose();
  };

  React.useEffect(() => {
    trackEvent('delivery_open', { context });
  }, [context]);

  const handleModeChange = (mode: DeliveryMode) => {
    setMode(mode);
    trackEvent('delivery_mode_change', { mode });
  };

  const handleValuesSave = () => {
    trackEvent('delivery_values_save', {
      batch: options.batchSize,
      wait: options.waitMinutes,
      randomize: options.randomizeWait,
    });
  };

  React.useEffect(() => {
    if (options.mode === 'continuous') {
      trackEvent('delivery_applied', {
        groups: targetCount,
        est_total_min: 0,
      });
    }
  }, [options.mode, targetCount]);

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-xl w-full max-w-md max-h-[90vh] overflow-hidden shadow-xl">
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b bg-gradient-to-r from-blue-50 to-white">
          <h2 className="text-lg font-semibold text-gray-900">Delivery Pacing</h2>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="p-4 overflow-y-auto max-h-[calc(90vh-140px)]">
          <div className="space-y-4">
            {/* Mode Selection */}
            <div className="space-y-2">
              <label className="flex items-center space-x-2 cursor-pointer group">
                <input
                  type="radio"
                  name={`delivery-mode-${context}`}
                  value="continuous"
                  checked={options.mode === 'continuous'}
                  onChange={() => handleModeChange('continuous')}
                  className="w-4 h-4 text-blue-600 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
                />
                <div className="flex flex-col">
                  <span className="text-sm text-gray-700 group-hover:text-gray-900 transition-colors">
                    Continuous
                  </span>
                  <span className="text-[10px] text-gray-500">
                    Fastest allowed
                  </span>
                </div>
              </label>
              
              <label className="flex items-center space-x-2 cursor-pointer group">
                <input
                  type="radio"
                  name={`delivery-mode-${context}`}
                  value="throttled"
                  checked={options.mode === 'throttled'}
                  onChange={() => handleModeChange('throttled')}
                  className="w-4 h-4 text-blue-600 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
                />
                <div className="flex flex-col">
                  <span className="text-sm text-gray-700 group-hover:text-gray-900 transition-colors">
                    Throttled
                  </span>
                  <span className="text-[10px] text-gray-500">
                    Recommended for many groups
                  </span>
                </div>
              </label>
              
              <p className="text-[10px] text-gray-500 italic">
                Helps avoid rate limits and duplicate detection
              </p>
            </div>

            {/* Throttled Options */}
            {options.mode === 'throttled' && (
              <div className="space-y-3 pl-4 border-l-2 border-blue-100">
                {/* Batch Size */}
                <div>
                  <label className="block text-xs font-medium text-gray-700 mb-1.5">
                    Post to this many groups before waiting
                  </label>
                  <input
                    type="number"
                    min={1}
                    max={20}
                    value={options.batchSize}
                    onChange={(e) => setBatchSize(parseInt(e.target.value) || 1)}
                    onBlur={handleValuesSave}
                    className="w-full h-12 px-3 border border-gray-300 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                </div>

                {/* Wait Minutes */}
                <div>
                  <label className="block text-xs font-medium text-gray-700 mb-1.5">
                    Wait time (minutes)
                  </label>
                  <input
                    type="number"
                    min={1}
                    max={120}
                    value={options.waitMinutes}
                    onChange={(e) => setWaitMinutes(parseInt(e.target.value) || 1)}
                    onBlur={handleValuesSave}
                    className="w-full h-12 px-3 border border-gray-300 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                </div>

                {/* Randomize Wait */}
                <label className="flex items-center space-x-2 cursor-pointer group">
                  <div className="relative">
                    <input
                      type="checkbox"
                      checked={options.randomizeWait}
                      onChange={(e) => {
                        setRandomizeWait(e.target.checked);
                        handleValuesSave();
                      }}
                      className="sr-only peer"
                    />
                    <div className="w-11 h-6 bg-gray-200 rounded-full peer peer-focus:ring-2 peer-focus:ring-blue-500 peer-focus:ring-offset-2 peer-checked:bg-blue-600 transition-colors">
                      <div className="absolute top-0.5 left-0.5 bg-white w-5 h-5 rounded-full shadow-md transform peer-checked:translate-x-5 transition-transform" />
                    </div>
                  </div>
                  <span className="text-sm text-gray-700 group-hover:text-gray-900 transition-colors flex-1">
                    Randomize wait (70–150%)
                  </span>
                </label>

                {/* Estimated Time */}
                {showEstimate && (
                  <div className="bg-blue-50 rounded-lg p-2.5 border border-blue-200">
                    <div className="flex items-start space-x-2">
                      <Info size={14} className="text-blue-600 mt-0.5 flex-shrink-0" />
                      <div>
                        <p className="text-[10px] font-medium text-blue-700 uppercase tracking-wide mb-0.5">
                          Estimated total time
                        </p>
                        <p className="text-xs text-blue-800 font-semibold">
                          {options.randomizeWait
                            ? `~${estimatedTime.min}–${estimatedTime.max} minutes`
                            : `~${estimatedTime.max} minutes`}
                        </p>
                        <p className="text-[10px] text-blue-600 mt-0.5">
                          For {targetCount} {context === 'schedule' ? 'scheduled slots' : 'groups'}
                        </p>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-end gap-2 px-4 py-3 border-t bg-gray-50">
          <button
            onClick={onClose}
            className="px-4 py-2 text-sm font-bold uppercase text-gray-700 hover:bg-gray-100 rounded-2xl transition-colors tracking-wide"
          >
            Cancel
          </button>
          <button
            onClick={handleApply}
            className="px-4 py-2 text-sm font-bold uppercase text-white bg-blue-600 hover:bg-blue-700 rounded-2xl transition-colors tracking-wide"
          >
            Apply
          </button>
        </div>
      </div>
    </div>
  );
}
