import React, { useEffect, useState } from "react";
import { X, Calendar } from "lucide-react";

export function CompactScheduleModal({
  isOpen,
  onClose,
  onSchedule,
  onShowAlmostThere,
  initialSchedule,
  group
}) {
  const now = new Date();
  const defaultDateString = now.toISOString().split("T")[0];
  const defaultTimeString = now
    .toLocaleTimeString("en-US", { hour12: false, hour: "2-digit", minute: "2-digit" })
    .padStart(5, "0");

  // --- hooks always declared here (stable order) ---
  const [frequency, setFrequency] = useState("once");
  const [selectedDate, setSelectedDate] = useState(defaultDateString);
  const [time, setTime] = useState(defaultTimeString);
  const [selectedWeekDays, setSelectedWeekDays] = useState([]);
  const [selectedMonthDays, setSelectedMonthDays] = useState([]);

  // stable constant
  const WEEKDAYS = [
    { short: "Sun", full: "Sunday", value: 0 },
    { short: "Mon", full: "Monday", value: 1 },
    { short: "Tue", full: "Tuesday", value: 2 },
    { short: "Wed", full: "Wednesday", value: 3 },
    { short: "Thu", full: "Thursday", value: 4 },
    { short: "Fri", full: "Friday", value: 5 },
    { short: "Sat", full: "Saturday", value: 6 }
  ];

  // hydrate initialSchedule once; effect's presence doesn't change hook order
  useEffect(() => {
    if (!initialSchedule) return;

    const sched = initialSchedule;
    if (sched.frequency) setFrequency(sched.frequency);
    if (sched.startDate) {
      const d = new Date(sched.startDate);
      if (!isNaN(d.getTime())) setSelectedDate(d.toISOString().split("T")[0]);
    }
    if (sched.time) setTime(sched.time);

    if (sched.recurring) {
      if (sched.recurring.weekDays) setSelectedWeekDays(sched.recurring.weekDays);
      if (sched.recurring.monthDays) setSelectedMonthDays(sched.recurring.monthDays);
    }
    // only run when initialSchedule changes
  }, [initialSchedule]);

  // If the modal is closed, render nothing. This early return is safe because hooks have already run.
  if (!isOpen) return null;

  const toggleWeekDay = (day) => {
    if (frequency === "weekly") {
      setSelectedWeekDays((prev) =>
        prev.includes(day) ? prev.filter((d) => d !== day) : [...prev, day]
      );
    } else {
      setSelectedWeekDays((prev) => (prev.includes(day) ? prev.filter((d) => d !== day) : [day]));
    }
  };

  const toggleMonthDay = (num) => {
    setSelectedMonthDays((prev) =>
      prev.includes(num) ? prev.filter((d) => d !== num) : [...prev, num]
    );
  };

  const isValid = () => {
    if (!time) return false;
    if (frequency === "once" && !selectedDate) return false;
    if (frequency === "weekly" && selectedWeekDays.length === 0) return false;
    if (frequency === "monthly" && selectedMonthDays.length === 0) return false;
    return true;
  };

  const handleSubmit = () => {
    const recurring =
      frequency === "weekly" && selectedWeekDays.length > 0
        ? { weekDays: selectedWeekDays }
        : frequency === "monthly" && selectedMonthDays.length > 0
        ? { monthDays: selectedMonthDays }
        : undefined;

    // Build schedule and ensure weekly schedules use the next selected weekday
    const schedule = {
      startDate: new Date(selectedDate),
      time,
      frequency,
      recurring
    };

    if (frequency === "weekly" && Array.isArray(selectedWeekDays) && selectedWeekDays.length > 0) {
      const nowLocal = new Date();
      const [hour, minute] = (time || "").split(":").map(Number);
      const today = nowLocal.getDay();

      let minDaysUntil = Infinity;
      for (const wd of selectedWeekDays) {
        const dayIndex = Number(wd);
        if (Number.isNaN(dayIndex)) continue;
        let daysUntil = (dayIndex - today + 7) % 7;
        if (daysUntil === 0) {
          // If it's today, only keep today if the scheduled time is still in the future
          if (!Number.isNaN(hour) && !Number.isNaN(minute)) {
            const scheduledToday = new Date(nowLocal.getFullYear(), nowLocal.getMonth(), nowLocal.getDate(), hour, minute, 0, 0);
            if (scheduledToday.getTime() <= nowLocal.getTime()) {
              daysUntil = 7; // use next week
            }
          }
        }
        if (daysUntil < minDaysUntil) minDaysUntil = daysUntil;
      }

      const next = new Date(nowLocal.getFullYear(), nowLocal.getMonth(), nowLocal.getDate() + (minDaysUntil === Infinity ? 0 : minDaysUntil), 0, 0, 0, 0);
      schedule.startDate = next;
    }

    onSchedule(schedule);
    onClose();
    if (onShowAlmostThere) onShowAlmostThere();
  };

  return (
    <div className="fixed inset-0 bg-black/30 z-50 flex items-center justify-center p-2">
      <div className="bg-white w-full max-w-[420px] rounded-2xl shadow-xl overflow-hidden animate-scale-in">
        <div className="relative h-12 bg-blue-600 px-3.5 flex items-center justify-between">
          <h2 className="text-[15px] font-semibold text-white">Schedule Post</h2>
          <button onClick={onClose} className="p-1 hover:bg-white/20 rounded-full text-white">
            <X size={18} />
          </button>
        </div>

        <div className="p-3 space-y-3">
          <div className="grid grid-cols-2 gap-1.5">
            {["once", "daily", "weekly", "monthly"].map((f) => (
              <button
                key={f}
                onClick={() => setFrequency(f)}
                className={`py-2.5 rounded-lg text-[13px] font-medium transition-all ${
                  frequency === f
                    ? "bg-blue-50 text-blue-600 border-2 border-blue-600"
                    : "bg-white text-gray-600 border border-gray-300 hover:border-gray-400"
                } relative`}
              >
                {f[0].toUpperCase() + f.slice(1)}
                {(f === "weekly" || f === "monthly") && (
                  <span
                    className={`absolute top-0.5 right-1.5 text-[8px] ${
                      frequency === f ? "text-blue-400" : "text-gray-400"
                    }`}
                  >
                    Multi-select
                  </span>
                )}
              </button>
            ))}
          </div>

          {frequency === "weekly" && (
            <div className="grid grid-cols-7 gap-1">
              {WEEKDAYS.map((d) => (
                <button
                  key={d.value}
                  onClick={() => toggleWeekDay(d.value)}
                  className={`py-2 text-[11px] rounded-lg font-medium ${
                    selectedWeekDays.includes(d.value)
                      ? "bg-blue-600 text-white"
                      : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                  }`}
                >
                  {d.short}
                </button>
              ))}
            </div>
          )}

          {frequency === "monthly" && (
            <div>
              <div className="text-[13px] font-medium text-gray-600 mb-1">Select Dates</div>
              <div className="grid grid-cols-8 gap-1">
                {Array.from({ length: 31 }, (_, i) => i + 1).map((num) => (
                  <button
                    key={num}
                    onClick={() => toggleMonthDay(num)}
                    className={`h-8 text-[12px] font-medium rounded-lg ${
                      selectedMonthDays.includes(num)
                        ? "bg-blue-600 text-white"
                        : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                    }`}
                  >
                    {num}
                  </button>
                ))}
              </div>
            </div>
          )}

          {frequency === "once" && (
            <div>
              <div className="text-[13px] font-medium text-gray-600 mb-1">Select Date</div>
              <div className="flex items-center gap-2 bg-gray-50 px-2.5 py-2 rounded-lg border border-gray-200">
                <Calendar size={16} className="text-gray-500" />
                <input
                  type="date"
                  value={selectedDate}
                  onChange={(e) => setSelectedDate(e.target.value)}
                  className="bg-transparent flex-1 outline-none text-[13px]"
                />
              </div>
            </div>
          )}

          <div>
            <div className="text-[13px] font-medium text-gray-600 mb-1.5">Time</div>
            <div className="flex gap-2.5">
              <div className="w-[55%] flex items-center gap-2 bg-gray-50 px-2.5 py-2 rounded-lg border border-gray-200">
                <svg width="16" height="16" viewBox="0 0 24 24" className="text-gray-500">
                  <circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2" />
                  <path d="M12 7v5l3 3" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                </svg>
                <input
                  type="time"
                  value={time}
                  onChange={(e) => setTime(e.target.value)}
                  className="bg-transparent flex-1 outline-none text-[13px]"
                />
              </div>

              <button
                disabled={!isValid()}
                onClick={handleSubmit}
                className={`flex-1 py-2 rounded-xl font-bold text-[13px] uppercase tracking-wide ${
                  isValid() ? "bg-blue-600 text-white hover:bg-blue-700" : "bg-gray-300 text-gray-500 cursor-not-allowed"
                }`}
              >
                SCHEDULE
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

// preserved helper
function getOrdinalSuffix(day) {
  if (day > 3 && day < 21) return "th";
  switch (day % 10) {
    case 1:
      return "st";
    case 2:
      return "nd";
    case 3:
      return "rd";
    default:
      return "th";
  }
}
