// Spintax parsing and expansion utilities

export interface SpintaxGroup {
  original: string;
  options: string[];
}

/**
 * Parse spintax from text and return groups
 * Example: "Hello {world|universe|friend}" returns [{original: "{world|universe|friend}", options: ["world", "universe", "friend"]}]
 */
export function parseSpintax(text: string): SpintaxGroup[] {
  const groups: SpintaxGroup[] = [];
  const regex = /\{([^{}]+)\}/g;
  let match;

  while ((match = regex.exec(text)) !== null) {
    const original = match[0];
    const options = match[1].split('|').map(opt => opt.trim()).filter(opt => opt.length > 0);
    
    if (options.length > 1) {
      groups.push({ original, options });
    }
  }

  return groups;
}

/**
 * Expand spintax text once (randomly select one option from each group)
 */
export function expandOnce(text: string): string {
  const groups = parseSpintax(text);
  let result = text;

  groups.forEach(group => {
    const randomOption = group.options[Math.floor(Math.random() * group.options.length)];
    result = result.replace(group.original, randomOption);
  });

  return result;
}

/**
 * Generate N unique expansions of spintax text
 */
export function expandN(text: string, n: number): string[] {
  const groups = parseSpintax(text);
  
  if (groups.length === 0) {
    return [text];
  }

  const maxPermutations = countPermutations(text);
  const targetCount = Math.min(n, maxPermutations);
  const results = new Set<string>();

  // Generate unique expansions
  let attempts = 0;
  const maxAttempts = targetCount * 10; // Prevent infinite loops

  while (results.size < targetCount && attempts < maxAttempts) {
    results.add(expandOnce(text));
    attempts++;
  }

  return Array.from(results);
}

/**
 * Count total possible permutations in spintax text
 */
export function countPermutations(text: string): number {
  const groups = parseSpintax(text);
  
  if (groups.length === 0) {
    return 1;
  }

  return groups.reduce((total, group) => total * group.options.length, 1);
}

/**
 * Build spintax string from array of options
 */
export function buildSpintax(options: string[]): string {
  const cleaned = options.map(opt => opt.trim()).filter(opt => opt.length > 0);
  
  if (cleaned.length < 2) {
    return '';
  }

  // Escape special characters
  const escaped = cleaned.map(opt => 
    opt.replace(/\{/g, '\\{')
       .replace(/\}/g, '\\}')
       .replace(/\|/g, '\\|')
  );

  return `{${escaped.join('|')}}`;
}

/**
 * Validate spintax text
 */
export function validateSpintax(text: string): { valid: boolean; errors: string[] } {
  const errors: string[] = [];

  // Check for balanced braces
  const openCount = (text.match(/\{/g) || []).length;
  const closeCount = (text.match(/\}/g) || []).length;
  
  if (openCount !== closeCount) {
    errors.push('Unbalanced braces');
  }

  // Check for nested spintax (not supported)
  const nestedRegex = /\{[^{}]*\{[^{}]*\}[^{}]*\}/;
  if (nestedRegex.test(text)) {
    errors.push('Nested spintax is not supported');
  }

  // Check for empty options
  const emptyOptions = /\{\s*\||\|\s*\||\|\s*\}/;
  if (emptyOptions.test(text)) {
    errors.push('Empty options found');
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

/**
 * Get a preview sample of spintax (first option from each group)
 */
export function getPreviewSample(options: string[]): string {
  const cleaned = options.filter(opt => opt.trim().length > 0);
  
  if (cleaned.length < 2) {
    return '';
  }

  return `{${cleaned.join('|')}} → ${cleaned[0]}`;
}
