import React from 'react';
import { Star, Heart } from 'lucide-react';
import { useRedirect } from '../../../hooks/useRedirect';
import { URLS } from '../constants/urls';

interface FeedbackBarProps {
  onSubmit?: (rating: number) => void;
}

export function FeedbackBar({ onSubmit }: FeedbackBarProps) {
  const [rating, setRating] = React.useState<number>(0);
  const [hoveredRating, setHoveredRating] = React.useState<number>(0);
  const [isSubmitted, setIsSubmitted] = React.useState(false);
  const redirect = useRedirect();

  const handleRatingClick = (selectedRating: number) => {
    setRating(selectedRating);
    if (selectedRating === 5) {
      setTimeout(() => {
        redirect(URLS.CHROME_STORE_REVIEW);
      }, 1500);
    }
    setIsSubmitted(true);
    onSubmit?.(selectedRating);
  };

  const getRatingLabel = (rating: number): string => {
    switch (rating) {
      case 1: return 'Poor';
      case 2: return 'Fair';
      case 3: return 'Good';
      case 4: return 'Great';
      case 5: return 'Excellent';
      default: return 'Rate your experience';
    }
  };

  return (
    <div className="px-3 py-2 bg-gray-50 border-t">
      {!isSubmitted ? (
        <div className="flex flex-col items-center space-y-2">
          <div className="text-xs text-gray-700 font-medium">
            {getRatingLabel(hoveredRating)}
          </div>
          <div className="flex items-center justify-center space-x-4">
            {[1, 2, 3, 4, 5].map((value) => (
              <button
                key={value}
                className="p-1 focus:outline-none focus:ring-2 focus:ring-blue-400 rounded-full transition-transform hover:scale-125 active:scale-95"
                onMouseEnter={() => setHoveredRating(value)}
                onMouseLeave={() => setHoveredRating(0)}
                onClick={() => handleRatingClick(value)}
              >
                <Star
                  size={20}
                  className={`${
                    value <= hoveredRating
                      ? 'fill-yellow-400 text-yellow-400'
                      : 'text-gray-300'
                  } transition-colors`}
                />
              </button>
            ))}
          </div>
        </div>
      ) : (
        <div className="flex items-center justify-center space-x-2 py-1">
          <Heart
            size={14}
            className={`${
              rating === 5 ? 'fill-red-500 text-red-500' : 'text-gray-400'
            }`}
          />
          <span className="text-xs text-gray-700 font-medium">
            {rating === 5
              ? 'Thanks! Redirecting to leave a review...'
              : 'Thank you for your feedback'}
          </span>
        </div>
      )}
    </div>
  );
}