import React, { useState, useEffect } from "react";
import { Clock, Trash2, PenSquare, Calendar } from "lucide-react";
import { usePostStore } from "../../stores/postStore";
import { CompactScheduleModal } from "../../components/PostScheduler/CompactScheduleModal.tsx";
import {
  ScheduleConfig,
  ScheduledPost,
  WeekDay,
  MonthDay,
} from "../../types/scheduling";
import { formatNextScheduledTime } from "../../utils/dateUtils";
import { stripHtmlTags } from "../../utils/textFormatting";

export function ScheduledPostsManager() {
  const [editingPostId, setEditingPostId] = useState<string | null>(null);
  const [snapshotPosts, setSnapshotPosts] = useState<any[]>([]);
  const [showScheduleEditor, setShowScheduleEditor] = useState<boolean>(false);
  const [editingPost, setEditingPost] = useState<ScheduledPost | null>({});
  const [showNoticeModal,setShowNoticeModal]=useState(false)

  useEffect(() => {
    if (!editingPostId) {
      setShowScheduleEditor(false);
      return;
    }
    setShowScheduleEditor(true);
  }, [editingPostId]);

  const { scheduledPosts, removeScheduledPost, updateScheduledPost } =
    usePostStore();

  async function fetchSavedSchedules(){
    await chrome.runtime.sendMessage({ action: "getScheduledPosts" }, (response) => {
      console.warn("Fetched scheduled posts:=================>", response);
      if(response?.snapshots){
        setSnapshotPosts(response?.snapshots)
      }
      if (chrome.runtime.lastError) {
        return;
      }
    });
  }

  useEffect(() => {
    fetchSavedSchedules()
  }, []);

  function deleteSnapshotById(snapshotId: string): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open("permanentStore", 1);

      request.onsuccess = () => {
        const db = request.result;
        const tx = db.transaction("snapshots", "readwrite");
        const store = tx.objectStore("snapshots");

        const deleteRequest = store.delete(snapshotId);
        deleteRequest.onsuccess = () => {
          resolve();
        };
        deleteRequest.onerror = () => {
          reject(deleteRequest.error);
        };
      };

      request.onerror = () => {
        reject(request.error);
      };
    });
  }

  function openDB(name: any, version: any, onUpgradeNeeded: any) {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(name, version);

      request.onupgradeneeded = (e) => {
        const db = request.result;
        onUpgradeNeeded?.(db);
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }
  async function updateSnapshotSchedule(snapshotId: any, newScheduleValue: any) {
    const PERMANENT_DB_NAME = "permanentStore";
    const SNAPSHOT_STORE_NAME = "snapshots";

    try {

      const db = await openDB(PERMANENT_DB_NAME, 1);
      const tx = db.transaction(SNAPSHOT_STORE_NAME, "readwrite");
      const store = tx.objectStore(SNAPSHOT_STORE_NAME);

      const snapshot = await new Promise((resolve, reject) => {
        const req = store.get(snapshotId);
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error);
      });

      if (!snapshot) {
        db.close();
        return;
      }

      // Update the schedule value inside metadata
      snapshot.metadata = {
        ...snapshot.metadata,
        schedule: newScheduleValue,
      };

      // Put the updated snapshot back into the store
      await new Promise((resolve, reject) => {
        const req = store.put(snapshot);
        req.onsuccess = () => resolve(true);
        req.onerror = () => reject(req.error);
      });

      await fetchSavedSchedules()
      setShowNoticeModal(true)
      db.close();
    } catch (error) {
      console.error("❌ Failed to update schedule:", error);
    }
  }

  const handleUpdateSchedule = (
    postId: string,
    newSchedule: ScheduleConfig
  ) => {
    (async()=>await updateSnapshotSchedule(postId, newSchedule))()
    setEditingPostId(null);
  };

  const formatRecurringSchedule = (post: ScheduledPost) => {
    const { frequency, recurring } = post.schedule;

    if (frequency === "once") return "Once";
    if (frequency === "daily") return "Daily";

    if (frequency === "weekly" && recurring?.weekDays) {
      const dayNames = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
      const days = recurring.weekDays
        .sort((a, b) => a - b)
        .map((day) => dayNames[day])
        .join(", ");
      return `Weekly on ${days}`;
    }

    if (frequency === "monthly" && recurring?.monthDays) {
      const days = recurring.monthDays
        .sort((a, b) => a - b)
        .map((day) => `${day}${getOrdinalSuffix(day)}`)
        .join(", ");
      return `Monthly on ${days}`;
    }

    return frequency.charAt(0).toUpperCase() + frequency.slice(1);
  };

  const getOrdinalSuffix = (day: number): string => {
    if (day > 3 && day < 21) return "th";
    switch (day % 10) {
      case 1:
        return "st";
      case 2:
        return "nd";
      case 3:
        return "rd";
      default:
        return "th";
    }
  };

  const sortedPosts = [...scheduledPosts].sort((a, b) => {
    const dateA = new Date(
      `${a.schedule.startDate.toDateString()} ${a.schedule.time}`
    );
    const dateB = new Date(
      `${b.schedule.startDate.toDateString()} ${b.schedule.time}`
    );
    return dateA.getTime() - dateB.getTime();
  });

  return (
    <div className="p-3">
      <div className="space-y-2">
        {snapshotPosts.map((snap) => (
          <div
            key={snap.id}
            className="bg-white rounded-lg border p-3 hover:border-blue-200 transition-colors"
          >
            <div className="flex items-start justify-between mb-2">
              <div className="flex flex-col space-y-1 break-words" style={{maxWidth:"282px"}}>
                <div className="flex items-center space-x-1.5 text-xs text-gray-500">
                  <Clock size={12} className="text-blue-500" />
                  <span className="font-medium">
                    Date created - {new Date(
                      snap.metadata?.scheduledTime || snap.createdAt
                    ).toLocaleDateString()}{" "}
                    •
                    {new Date(
                      snap.metadata?.scheduledTime || snap.createdAt
                    ).toLocaleTimeString([], {
                      hour: "2-digit",
                      minute: "2-digit",
                    })}
                  </span>
                </div>
                <span className="inline-flex items-center px-2 py-0.5 bg-blue-50 text-blue-600 rounded text-xs font-medium max-w-[250px] overflow-hidden whitespace-nowrap" style={{width:"fit-content"}}>
                  <Calendar size={10} className="mr-1 shrink-0" />
                  <span className="truncate">
                    {snap.metadata?.schedule?.frequency || "Unknown"}&nbsp;
                    {snap.metadata?.schedule?.recurring ? (
                      <>
                        (
                        {snap.metadata?.schedule?.recurring?.weekDays ? (() => {
                          const dayNames = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
                          return snap.metadata.schedule.recurring.weekDays.map((d: number) => dayNames[d]).join(", ");
                        })() : (
                          snap.metadata?.schedule?.recurring?.monthDays?.join(", ")
                        )}
                        )
                      </>
                    ) : null}
                  </span>
                </span>
                <div>
                  <div className="text-blue-800 text-xs mb-1">Description:</div>
                  <div 
                    className="text-xs text-gray-700 overflow-hidden"
                    style={{ maxHeight: '200px' }}
                    dangerouslySetInnerHTML={{ __html: snap.metadata?.content || 'No content' }}
                  />
                </div>
              </div>
              <div className="flex space-x-1">
                <button
                  onClick={() => {
                    if (snap.id) {
                      setEditingPostId(snap.id);
                      setEditingPost(snap);
                    }
                  }}
                  className="p-1.5 text-gray-400 hover:text-blue-500 hover:bg-blue-50 rounded transition-colors"
                  title="Edit Schedule"
                >
                  <PenSquare size={14} />
                </button>
                <button
                  onClick={async () => {
                    await deleteSnapshotById(snap.id);
                    setSnapshotPosts((prev) =>
                      prev.filter((s) => s.id !== snap.id)
                    );
                  }}
                  className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded transition-colors"
                  title="Delete Schedule"
                >
                  <Trash2 size={14} />
                </button>
              </div>
            </div>
            <small className="text-sm line-clamp-2 break-words text-xs font-medium text-gray-500">
              <font className="text-green-800">Media - {snap.items.length || 0}&nbsp;&nbsp;</font>{" "}&nbsp;<font className="text-red-800">Next Trigger -</font>{" "}
              {formatNextScheduledTime(snap.metadata?.schedule)}<br/>
                <font className="text-green-800">Group - </font>{snap.metadata?.schedule?.group}
            </small>
          </div>
        ))}

        {snapshotPosts.length === 0 && (
          <div className="text-center py-8 text-gray-500">
            <Clock className="w-12 h-12 mx-auto mb-3 text-gray-300" />
            <p className="text-sm">No scheduled posts yet</p>
            <p className="text-xs text-gray-400 mt-1">
              Posts you schedule will appear here
            </p>
          </div>
        )}
      </div>

      {showScheduleEditor && (
        <CompactScheduleModal
          isOpen={!!editingPostId}
          onClose={() => setEditingPostId(null)}
          onSchedule={(schedule) =>
            handleUpdateSchedule(editingPostId, schedule || {})
          }
          initialSchedule={editingPost?.metadata?.schedule || {}}
        />
      )}
      {showNoticeModal ? (
        <>
          <div
            id="static-modal"
            data-modal-backdrop="static"
            tabIndex="-1"
            aria-hidden="true"
            className="overflow-y-auto overflow-x-hidden fixed top-0 right-0 left-0 z-50 flex justify-center items-center w-full md:inset-0 h-[calc(100%-1rem)] max-h-full bg-white"
            style={{
              backgroundColor: "#00000069",
              backdropFilter: "blur(5px)",
              height: "100%",
            }}
          >
            <div className="relative p-4 w-full max-w-2xl max-h-full">
              <div className="relative bg-white rounded-lg shadow-lg border border-gray-200">
                <div className="flex items-center justify-between p-4 md:p-5 border-b border-gray-200 rounded-t">
                  <h3 className="text-xl font-semibold text-gray-900 flex items-center gap-2">
                    <svg
                      className="w-6 h-6 text-blue-600"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
                      />
                    </svg>
                    Done!
                  </h3>
                </div>
                <div className="p-4 md:p-5 space-y-4">
                  <div className="flex items-start gap-3">
                    <svg
                      className="w-6 h-6 text-green-500 mt-1"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        d="M5 13l4 4L19 7"
                      />
                    </svg>
                    <p className="text-base text-gray-700">
                      Schedule updated successfully! Your changes will be reflected in the scheduled posts list.
                    </p>
                  </div>
                </div>
                <div className="flex items-center p-4 md:p-5 border-t border-gray-200 rounded-b">
                  <button
                    data-modal-hide="static-modal"
                    type="button"
                    className="text-white bg-blue-600 hover:bg-blue-700 focus:ring-4 focus:outline-none focus:ring-blue-300 font-medium rounded-lg text-sm px-5 py-2.5 w[100px]"
                    onClick={() => setShowNoticeModal(false)}
                  >
                    Close
                  </button>
                </div>
              </div>
            </div>
          </div>
        </>
      ) : (
        <></>
      )}
    </div>
  );
}
