import React, { useState } from 'react';
import { CheckCircle2, AlertCircle, ExternalLink, ChevronDown } from 'lucide-react';
import type { PostProgressStats, GroupPostStatus } from './types';

interface PostProgressSummaryProps {
  stats: PostProgressStats;
  groups: GroupPostStatus[];
}

export function PostProgressSummary({ stats, groups }: PostProgressSummaryProps) {
  const [expandedSection, setExpandedSection] = useState<'success' | 'failed' | 'pending' | null>(null);
  const allSuccessful = stats.successful === stats.total;
  
  const successfulGroups = groups.filter(g => g.status === 'success');
  const failedGroups = groups.filter(g => g.status === 'error');
  const pendingGroups = groups.filter(g => g.status === 'pending');

  const handleGroupClick = (url: string) => {
    window.open(url, '_blank');
  };
  
  return (
    <div className="space-y-4">
      {/* Summary Card */}
      <div className={`
        rounded-xl p-4 border
        ${allSuccessful 
          ? 'bg-green-50 border-green-100' 
          : 'bg-amber-50 border-amber-100'
        }
      `}>
        <div className="flex items-start space-x-3">
          <div className={`
            w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0
            ${allSuccessful ? 'bg-green-100' : 'bg-amber-100'}
          `}>
            {allSuccessful ? (
              <CheckCircle2 size={18} className="text-green-600" />
            ) : (
              <AlertCircle size={18} className="text-amber-600" />
            )}
          </div>
          <div>
            <h3 className={`
              text-sm font-medium
              ${allSuccessful ? 'text-green-900' : 'text-amber-900'}
            `}>
              {allSuccessful 
                ? 'All posts were successful!' 
                : 'Some posts encountered issues'
              }
            </h3>
            <ul className="mt-2 space-y-1 text-xs">
              <li className="text-green-700">
                ✓ Successfully posted to {stats.successful} groups
              </li>
              {stats.failed > 0 && (
                <li className="text-red-700">
                  ✗ Failed to post to {stats.failed} groups
                </li>
              )}
              {stats.pending > 0 && (
                <li className="text-amber-700">
                  ⏳ {stats.pending} groups pending
                </li>
              )}
            </ul>
          </div>
        </div>
      </div>

      {/* Successful Groups Section */}
      {successfulGroups.length > 0 && (
        <div className="rounded-xl border border-gray-200 overflow-hidden">
          <button
            onClick={() => setExpandedSection(expandedSection === 'success' ? null : 'success')}
            className="w-full flex items-center justify-between px-4 py-3 bg-green-50 hover:bg-green-100 transition-colors"
          >
            <div className="flex items-center space-x-2">
              <CheckCircle2 size={16} className="text-green-600" />
              <span className="text-sm font-medium text-green-900">
                Successful Posts ({successfulGroups.length})
              </span>
            </div>
            <ChevronDown 
              size={16} 
              className={`text-green-600 transition-transform ${
                expandedSection === 'success' ? 'rotate-180' : ''
              }`} 
            />
          </button>
          
          {expandedSection === 'success' && (
            <div className="divide-y divide-gray-100">
              {successfulGroups.map((group) => (
                <button
                  key={group.url}
                  onClick={() => handleGroupClick(group.url)}
                  className="w-full flex items-center justify-between px-4 py-2 hover:bg-gray-50 transition-colors"
                >
                  <span className="text-sm text-gray-700 truncate">
                    {group.name}
                  </span>
                  <ExternalLink size={14} className="text-gray-400" />
                </button>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Failed Groups Section */}
      {failedGroups.length > 0 && (
        <div className="rounded-xl border border-gray-200 overflow-hidden">
          <button
            onClick={() => setExpandedSection(expandedSection === 'failed' ? null : 'failed')}
            className="w-full flex items-center justify-between px-4 py-3 bg-red-50 hover:bg-red-100 transition-colors"
          >
            <div className="flex items-center space-x-2">
              <AlertCircle size={16} className="text-red-600" />
              <span className="text-sm font-medium text-red-900">
                Failed Posts ({failedGroups.length})
              </span>
            </div>
            <ChevronDown 
              size={16} 
              className={`text-red-600 transition-transform ${
                expandedSection === 'failed' ? 'rotate-180' : ''
              }`} 
            />
          </button>
          
          {expandedSection === 'failed' && (
            <div className="divide-y divide-gray-100">
              {failedGroups.map((group) => (
                <button
                  key={group.url}
                  onClick={() => handleGroupClick(group.url)}
                  className="w-full flex items-center justify-between px-4 py-2 hover:bg-gray-50 transition-colors"
                >
                  <div className="flex flex-col items-start">
                    <span className="text-sm text-gray-700 truncate">
                      {group.name}
                    </span>
                    {group.error && (
                      <span className="text-xs text-red-600 mt-0.5">
                        {group.error}
                      </span>
                    )}
                  </div>
                  <ExternalLink size={14} className="text-gray-400" />
                </button>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Pending Groups Section */}
      {pendingGroups.length > 0 && (
        <div className="rounded-xl border border-gray-200 overflow-hidden">
          <button
            onClick={() => setExpandedSection(expandedSection === 'pending' ? null : 'pending')}
            className="w-full flex items-center justify-between px-4 py-3 bg-amber-50 hover:bg-amber-100 transition-colors"
          >
            <div className="flex items-center space-x-2">
              <AlertCircle size={16} className="text-amber-600" />
              <span className="text-sm font-medium text-amber-900">
                Pending Posts ({pendingGroups.length})
              </span>
            </div>
            <ChevronDown 
              size={16} 
              className={`text-amber-600 transition-transform ${
                expandedSection === 'pending' ? 'rotate-180' : ''
              }`} 
            />
          </button>
          
          {expandedSection === 'pending' && (
            <div className="divide-y divide-gray-100">
              {pendingGroups.map((group) => (
                <button
                  key={group.url}
                  onClick={() => handleGroupClick(group.url)}
                  className="w-full flex items-center justify-between px-4 py-2 hover:bg-gray-50 transition-colors"
                >
                  <span className="text-sm text-gray-700 truncate">
                    {group.name}
                  </span>
                  <ExternalLink size={14} className="text-gray-400" />
                </button>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}