// Validation utilities for spintax options

export interface ValidationResult {
  valid: boolean;
  error?: string;
}

// Check if option is empty (after trim)
export function validateNotEmpty(option: string): ValidationResult {
  if (option.trim().length === 0) {
    return { valid: false, error: "This option can't be empty" };
  }
  return { valid: true };
}

// Check for unmatched braces and pipes (allowing escaped ones)
export function validateBracesAndPipes(option: string): ValidationResult {
  // Remove escaped characters
  let cleaned = option.replace(/\\[{}|]/g, '');
  
  // Check for unmatched braces
  let braceCount = 0;
  for (const char of cleaned) {
    if (char === '{') braceCount++;
    if (char === '}') braceCount--;
    if (braceCount < 0) {
      return { valid: false, error: 'Unmatched closing brace }' };
    }
  }
  
  if (braceCount !== 0) {
    return { valid: false, error: 'Unmatched opening brace {' };
  }
  
  // Check for pipes (not allowed in options)
  if (cleaned.includes('|')) {
    return { valid: false, error: "Pipe | not allowed (use \\| to escape)" };
  }
  
  return { valid: true };
}

// Full validation
export function validateOption(option: string): ValidationResult {
  const emptyCheck = validateNotEmpty(option);
  if (!emptyCheck.valid) return emptyCheck;
  
  const bracesCheck = validateBracesAndPipes(option);
  if (!bracesCheck.valid) return bracesCheck;
  
  return { valid: true };
}

// Validate all options
export function validateAllOptions(options: string[]): { valid: boolean; errors: Map<number, string> } {
  const errors = new Map<number, string>();
  
  options.forEach((option, index) => {
    const result = validateOption(option);
    if (!result.valid && result.error) {
      errors.set(index, result.error);
    }
  });
  
  return {
    valid: errors.size === 0,
    errors
  };
}
