import React, { useState, useCallback, useEffect } from "react";
import {
  Send,
  Image,
  Link,
  Smile,
  Calendar,
  Clock,
  X,
  Zap,
  SendHorizonalIcon,
  AlarmClockCheckIcon,
  AlertCircle,
  ListPlus,
  ArrowRight,
  PartyPopper,
  Crown,
  ArrowLeft,
  Pencil,
  Sparkles,
  AlertTriangle,
} from "lucide-react";
import { ScheduleConfig } from "../../types/scheduling";
import { CompactScheduleModal } from "./CompactScheduleModal";
import { usePostStore } from "../../stores/postStore";
import { BackgroundColorSelector } from "../Post/BackgroundColorSelector";
import { BackgroundStyle } from "../Post/BackgroundColorSelector/backgroundStyles";
import { FeedbackBar } from "../Feedback/FeedbackBar";
import { GroupSelector } from "./GroupSelector";
import { GroupSelectionDialog } from "./GroupSelectionDialog";
import { ValidationDialog } from "./ValidationDialog";
import { SuccessDialog } from "./SuccessDialog";
import { ImmediatePostDialog } from "./ImmediatePostDialog";
import { GroupListManager } from "../Groups/GroupListManager";
import { FormattingHelpDialog } from "./FormattingHelpDialog";
import { RichTextEditor } from "./RichTextEditor";
import { extractUrls, isYouTubeUrl } from "../../utils/linkUtils";
import { PostProgressManager } from "../PostProgress/PostProgressManager";
import { UpgradeDialog } from "../Upgrade/UpgradeDialog";
import PostingComponent from "./PostingComponent";
import { useGroupStore } from "../../stores/groupStore";
import { LinkPreview } from "./LinkPreview";
import { toast } from "react-toastify";
import EmojiPicker from "emoji-picker-react";
import { DeliveryOptions } from "./DeliveryOptions";
import { useDeliveryOptions } from "./Spintax/hooks/useDeliveryOptions";

export function PostScheduler() {
  const {
    selectedGroupId,
    setSelectedGroup,
    draftPost,
    setDraftPost,
    decrementRemainingPosts,
    scheduledPosts,
    _hydrated,
  } = usePostStore();

  // Get delivery options from Zustand store
  const deliveryOptions = useDeliveryOptions((state) => state.options);

  // Read initial values from the central store
  const storeIsPremium = usePostStore((state) => state.isPremium);
  const storeRemainingPosts = usePostStore((state) => state.postsRemaining);
  const setStorePostsRemaining = usePostStore((state) => state.setPostsRemaining);
  const setStoreIsPremium = usePostStore((state) => state.setIsPremium);

  const { groupLists } = useGroupStore();

  // Local component state (kept in sync by short polling below)
  const [isPremium, setIsPremium] = useState<boolean>(storeIsPremium ?? false);
  const [remainingPosts, setRemainingPosts] = useState<number | undefined>(
    typeof storeRemainingPosts === "number" ? storeRemainingPosts : undefined
  );
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [showGroupDialog, setShowGroupDialog] = useState(false);
  const [showSuccessDialog, setShowSuccessDialog] = useState(false);
  const [showImmediatePostDialog, setShowImmediatePostDialog] = useState(false);
  const [showGroupListManager, setShowGroupListManager] = useState(false);
  const [showFormattingHelp, setShowFormattingHelp] = useState(false);
  const [showPostProgress, setShowPostProgress] = useState(false);
  const [showUpgradeDialog, setShowUpgradeDialog] = useState(false);
  const [selectedStyle, setSelectedStyle] = useState<BackgroundStyle | null>(
    null
  );
  const [missingGroup, setMissingGroup] = useState(false);
  const [missingContent, setMissingContent] = useState(false);
  const [validationMessage, setValidationMessage] = useState("");
  const [groupUrls, setGroupUrls] = useState<string[]>([]);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [showValidationDialog, setShowValidationDialog] = useState(false);
  const [isPosting, setIsPosting] = useState(false);
  const [showNoticeModal, setShowNoticeModal] = useState(false);
  const [showContentNoticeModal, setShowContentNoticeModal] = useState(false);
  const [showSuccessScheduleModal, setShowSuccessScheduleModal] =
    useState(false);
  const [showScheduleFinalStep, setShowScheduleFinalStep] = useState(false);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [email, setEmail] = useState("");
  const [editableSelectedGroupId, setEditableSelectedGroupId] = useState<
    string | null
  >(null);

  // Helper to open the Group List Manager and persist its open state to local storage
  const openGroupListManager = async (listId = null) => {
    try {
      // If a listId is provided, open that existing list. Otherwise start a new list.
      const group = listId ? groupLists.find((g) => g.id === listId) : null;

      const editState = {
        showAddUrls: true,
        // For new lists prefer a blank/new name; for existing, use the group's name
        editedGroupName: group?.name || "New group list",
        groupsUrls: group?.urls || [],
        openedListId: listId || null,
      };

      await chrome.storage.local.set({ editListState: editState });
    } catch (e) {
      // ignore in non-extension environments
    }

    setEditableSelectedGroupId(listId || null);
    setShowGroupListManager(true);
  };

  // On mount: restore from localStorage and sync to Zustand store
  useEffect(() => {
    // Restore rich text content from localStorage
    const savedContent = localStorage.getItem('richTextEditorContent');
    if (savedContent && !draftPost?.content) {
      setDraftPost({ 
        content: savedContent, 
        schedule: draftPost?.schedule || null 
      });
    }

    // Restore selected group from localStorage
    const savedGroupId = localStorage.getItem('selectedGroupId');
    if (savedGroupId && !selectedGroupId) {
      // Verify the group still exists
      if (groupLists.find(g => g.id === savedGroupId)) {
        setSelectedGroup(savedGroupId);
      }
    }

    // Auto-open manager if the last session left it open
    try {
      chrome.storage.local
        .get("editListState")
        .then((res) => {
          const s = res?.editListState;
          if (s?.showAddUrls) {
            setEditableSelectedGroupId(s.openedListId || null);
            setShowGroupListManager(true);
          }
        })
        .catch(() => {});
    } catch (e) {
      // ignore in non-extension env
    }
  }, []);
  useEffect(() => {
    (async () => {
      let user = await chrome.storage.sync.get(["user"]);
      setEmail(user?.user?.email || "");
    })();
  }, []);

  const onEmojiClick = (emojiObject: any) => {
    setShowEmojiPicker(false);
    let tmp = draftPost;
    if (tmp) {
      tmp.content += emojiObject.emoji;
      setDraftPost(tmp);
    }
  };

  // Short polling: keep the component (and central store) updated every second
  // by reading values from chrome.storage.sync. This ensures the UI reflects
  // changes made elsewhere without requiring a manual refresh.
  useEffect(() => {
    let intervalId: number | undefined;

    const fetchFromStorage = () => {
      try {
        chrome.storage.sync.get(["postsRemaining", "isPremium"], (result) => {
          try {
            // Only update if values are actually present in storage
            if (typeof result?.postsRemaining !== "undefined") {
              const postsRemaining = result.postsRemaining;
              if (remainingPosts !== postsRemaining) {
                setRemainingPosts(postsRemaining);
                if (typeof setStorePostsRemaining === "function") {
                  setStorePostsRemaining(postsRemaining);
                }
              }
            }
            
            if (typeof result?.isPremium !== "undefined") {
              const premium = Boolean(result.isPremium);
              if (isPremium !== premium) {
                setIsPremium(premium);
                if (typeof setStoreIsPremium === "function") {
                  setStoreIsPremium(premium);
                }
              }
            }
          } catch (e) {
            // ignore per-call errors
          }
        });
      } catch (e) {
        // ignore when chrome not available
      }
    };

    // initial read
    fetchFromStorage();
    // poll every 1s
    intervalId = window.setInterval(fetchFromStorage, 1000);

    return () => {
      if (intervalId) clearInterval(intervalId);
    };
  }, [setStorePostsRemaining, setStoreIsPremium, remainingPosts, isPremium]);

  async function getFilesFromIndexedDB() {
    function getCurrentDB(): Promise<IDBDatabase> {
      return new Promise((resolve, reject) => {
        const request = indexedDB.open("MediaDB", 1);

        request.onupgradeneeded = (e) => {
          const db = (e.target as IDBOpenDBRequest).result;
          if (!db.objectStoreNames.contains("media")) {
            db.createObjectStore("media", { keyPath: "key" });
          }
        };

        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
    }
    const db = await getCurrentDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction("media", "readonly");
      const store = tx.objectStore("media");
      const request = store.getAll();

      request.onsuccess = async () => {
        const entries = request.result || [];
        try {
          const processed = await Promise.all(
            entries.map(async ({ key, value }) => {
              const blob = value.blob;
              if (!(blob instanceof Blob)) {
                return null;
              }
              const base64 = await blobToBase64(blob);
              const type = value.type.startsWith("image/")
                ? "image"
                : value.type.startsWith("video/")
                ? "video"
                : "unknown";
              return {
                id: key,
                data: base64,
                type,
              };
            })
          );
          resolve(processed.filter(Boolean));
        } catch (error) {
          reject(error);
        }
      };
      request.onerror = () => reject(request.error);
    });
  }

  const [uploadedMedia, setUploadedMedia] = useState<{
    type: "image" | "video";
    data: string;
  }>([]);

  // Helper function to check if HTML content is truly empty (ignoring HTML tags)
  const isContentEmpty = (htmlContent: string | undefined | null): boolean => {
    if (!htmlContent) return true;
    // Remove all HTML tags and check if there's any text left
    const textOnly = htmlContent
      .replace(/<[^>]*>/g, '') // Remove all HTML tags
      .replace(/&nbsp;/g, ' ') // Replace &nbsp; with space
      .trim();
    return textOnly.length === 0;
  };

  const handleContentChange = useCallback(
    (content: string) => {
      // Ensure draftPost has proper structure with all required fields
      const updatedDraft = {
        content,
        schedule: draftPost?.schedule || null,
      };
      setDraftPost(updatedDraft as any);

      // Extract and set video URL if present
      const urls = extractUrls(content);
      const youtubeUrl = urls.find(isYouTubeUrl);
      setVideoUrl(youtubeUrl || null);
    },
    [draftPost, setDraftPost]
  );

  useEffect(() => {
    (async () => {
      const files = await getFilesFromIndexedDB();
      setUploadedMedia(files);
    })();
  }, []);

  const handleScheduleClick = () => {
    if (remainingPosts === 0 && !isPremium) {
      setShowUpgradeDialog(true);
      return;
    }
    if (
      !groupLists.find((group) => group.id === selectedGroupId)?.urls.length &&
      isContentEmpty(draftPost?.content)
    ) {
      setMissingGroup(true);
      setMissingContent(true);
    }
    if (
      !groupLists.find((group) => group.id === selectedGroupId)?.urls.length &&
      !isContentEmpty(draftPost?.content)
    ) {
      setMissingGroup(true);
      setMissingContent(false);
    }
    if (
      groupLists.find((group) => group.id === selectedGroupId)?.urls.length &&
      isContentEmpty(draftPost?.content)
    ) {
      setMissingGroup(false);
      setMissingContent(true);
    }
    if (
      !groupLists.find((group) => group.id === selectedGroupId)?.urls.length
    ) {
      setShowValidationDialog(true);
      return;
    }
    if (isContentEmpty(draftPost?.content)) {
      setShowValidationDialog(true);
      return;
    }
    setShowScheduleModal(true);
  };

  const handleSchedule = useCallback(
    (schedule: ScheduleConfig | null) => {
      if (schedule) {
        schedule["group"] = schedule.group = groupLists.find(
          (group) => group.id === selectedGroupId
        )?.name;
      }

      setDraftPost({ ...draftPost, schedule });
      setShowScheduleModal(false);
      setShowScheduleFinalStep(true);
    },
    [draftPost, setDraftPost]
  );

  function blobToBase64(blob: Blob): Promise<string> {
    return new Promise((res, rej) => {
      const reader = new FileReader();
      reader.onload = () => res(reader.result as string);
      reader.onerror = (e) => rej(e);
      reader.readAsDataURL(blob);
    });
  }

  // Your main post handler
  const handlePost = async () => {
    // Prevent double-submission
    if (isPosting) {
      console.log("Post already in progress, ignoring duplicate request");
      return;
    }

    console.log("[handlePost] Starting post...");
    console.log("[handlePost] draftPost?.content:", draftPost?.content);
    console.log("[handlePost] selectedGroupId:", selectedGroupId);
    console.log("[handlePost] isContentEmpty:", isContentEmpty(draftPost?.content));
    console.log("[handlePost] Group URLs length:", groupLists.find((group) => group.id === selectedGroupId)?.urls.length);

    try {
      setIsPosting(true);
      
      // CRITICAL SECURITY: Verify premium status from server before posting
      console.log("[handlePost] Verifying premium status from server...");
      const user = await chrome.storage.sync.get(["user"]);
      const userEmail = user?.user?.email || email;
      
      if (!userEmail) {
        alert("User email not found. Please log in again.");
        setIsPosting(false);
        return;
      }

      // Call server to verify premium status
      let serverIsPremium = false;
      let serverPostsRemaining = 0;
      
      try {
        const response = await fetch(
          `https://auth.fbgroupbulkposter.com/api/subscription?email=${encodeURIComponent(userEmail)}`
        );
        const data = await response.json();
        
        if (data.status === "success" && data.subscription) {
          serverIsPremium = data.subscription.status === "active";
          console.log("[handlePost] Server verification - isPremium:", serverIsPremium);
        }
        
        // Also get posts remaining from server
        const creditsResponse = await new Promise((resolve, reject) => {
          chrome.runtime.sendMessage(
            { action: "checkCredits", email: userEmail },
            (response) => {
              if (chrome.runtime.lastError) {
                reject(chrome.runtime.lastError.message);
              } else {
                resolve(response);
              }
            }
          );
        });
        
        serverPostsRemaining = creditsResponse?.postsRemaining || 0;
        console.log("[handlePost] Server verification - postsRemaining:", serverPostsRemaining);
        
      } catch (error) {
        console.error("[handlePost] Server verification failed:", error);
        alert("Unable to verify subscription status. Please check your internet connection and try again.");
        setIsPosting(false);
        return;
      }

      // Check premium/posts remaining based on SERVER data (not client)
      if (serverPostsRemaining === 0 && !serverIsPremium) {
        console.log("[handlePost] BLOCKED: No posts remaining and not premium");
        setShowUpgradeDialog(true);
        setIsPosting(false);
        return;
      }
      
      if (
        !groupLists.find((group) => group.id === selectedGroupId)?.urls.length &&
        !isContentEmpty(draftPost?.content)
      ) {
        setMissingGroup(true);
        setMissingContent(false);
      }
      if (
        groupLists.find((group) => group.id === selectedGroupId)?.urls.length &&
        isContentEmpty(draftPost?.content)
      ) {
        setMissingGroup(false);
        setMissingContent(true);
      }
      if (
        !groupLists.find((group) => group.id === selectedGroupId)?.urls.length &&
        isContentEmpty(draftPost?.content)
      ) {
        setMissingGroup(true);
        setMissingContent(true);
      }
      if (
        !groupLists.find((group) => group.id === selectedGroupId)?.urls.length
      ) {
        console.log("[handlePost] BLOCKED: No group URLs");
        setShowValidationDialog(true);
        setIsPosting(false);
        return;
      }
      if (isContentEmpty(draftPost?.content)) {
        console.log("[handlePost] BLOCKED: Content is empty");
        setShowValidationDialog(true);
        setIsPosting(false);
        return;
      }

      console.log("[handlePost] Validation passed, preparing payload...");

      const images = uploadedMedia
        .filter((m) => m.type === "image")
        .map((m) => (m as { type: "image"; data: string }).data);

      const videos = uploadedMedia
        .filter((m) => m.type === "video")
        .map((m) => (m as { type: "video"; data: File }).data); // ⬅️ Expecting File/Blob

      const videoRefs: { type: "video"; key: string }[] = [];
      const videoIds: string[] = [];

      uploadedMedia.forEach((el) => {
        videoIds.push(el.id);
      });

      const finalMedia = [
        ...images.map((data) => ({ type: "image", data })),
        ...videoRefs,
      ];

      const payload: PostPayload = {
        action: "",
        post: {
          title: "title 1",
          text: draftPost?.content || "",
          images: finalMedia,
          links: [],
          video_id: videoIds,
        },
        group: {
          urls:
            groupLists.find((group) => group.id === selectedGroupId)?.urls ||
            [],
        },
        timeInSeconds: 10,
        background: selectedStyle,
        activeIndex: "0",
        activeIndexProducts: "",
        avoidNightTimePosting: false,
        deliveryOptions: deliveryOptions,
        campaignId: draftPost?.id, // CRITICAL FIX: Pass campaign ID so background can track it
      };

      chrome.runtime.sendMessage({ action: "POST_PAYLOAD", payload });
      console.log("Posted payload:", payload);
      
      // Reset posting state after a short delay to allow background script to receive message
      setTimeout(() => {
        setIsPosting(false);
      }, 1000);
    } catch (err) {
      console.error("❌ Error in handlePost:", err);
      setIsPosting(false);
    }
  };

  const schedulePost = async () => {
    // CRITICAL SECURITY: Verify premium status from server before scheduling
    console.log("[schedulePost] Verifying premium status from server...");
    const user = await chrome.storage.sync.get(["user"]);
    const userEmail = user?.user?.email || email;
    
    if (!userEmail) {
      alert("User email not found. Please log in again.");
      return;
    }

    // Call server to verify premium status
    let serverIsPremium = false;
    let serverPostsRemaining = 0;
    
    try {
      const response = await fetch(
        `https://auth.fbgroupbulkposter.com/api/subscription?email=${encodeURIComponent(userEmail)}`
      );
      const data = await response.json();
      
      if (data.status === "success" && data.subscription) {
        serverIsPremium = data.subscription.status === "active";
        console.log("[schedulePost] Server verification - isPremium:", serverIsPremium);
      }
      
      // Also get posts remaining from server
      const creditsResponse = await new Promise((resolve, reject) => {
        chrome.runtime.sendMessage(
          { action: "checkCredits", email: userEmail },
          (response) => {
            if (chrome.runtime.lastError) {
              reject(chrome.runtime.lastError.message);
            } else {
              resolve(response);
            }
          }
        );
      });
      
      serverPostsRemaining = creditsResponse?.postsRemaining || 0;
      console.log("[schedulePost] Server verification - postsRemaining:", serverPostsRemaining);
      
    } catch (error) {
      console.error("[schedulePost] Server verification failed:", error);
      alert("Unable to verify subscription status. Please check your internet connection and try again.");
      return;
    }

    // Check premium/posts remaining based on SERVER data (not client)
    if (serverPostsRemaining === 0 && !serverIsPremium) {
      console.log("[schedulePost] BLOCKED: No posts remaining and not premium");
      setShowUpgradeDialog(true);
      return;
    }

    // Validation logic - same as handlePost
    if (
      !groupLists.find((group) => group.id === selectedGroupId)?.urls.length &&
      !isContentEmpty(draftPost?.content)
    ) {
      setMissingGroup(true);
      setMissingContent(false);
    }
    if (
      groupLists.find((group) => group.id === selectedGroupId)?.urls.length &&
      isContentEmpty(draftPost?.content)
    ) {
      setMissingGroup(false);
      setMissingContent(true);
    }
    if (
      !groupLists.find((group) => group.id === selectedGroupId)?.urls.length &&
      isContentEmpty(draftPost?.content)
    ) {
      setMissingGroup(true);
      setMissingContent(true);
    }
    if (
      !groupLists.find((group) => group.id === selectedGroupId)?.urls.length
    ) {
      setShowValidationDialog(true);
      return;
    }
    if (isContentEmpty(draftPost?.content)) {
      setShowValidationDialog(true);
      return;
    }

    if (draftPost) {
      draftPost["group"] = {
        urls:
          groupLists.find((group) => group.id === selectedGroupId)?.urls || [],
      };
      // Add delivery options to the scheduled post
      draftPost["deliveryOptions"] = deliveryOptions;
      // Add background style to the scheduled post
      (draftPost as any)["background"] = selectedStyle;
    }
    // Send message to Chrome extension and wait for response
    await chrome.runtime.sendMessage(
      { action: "schedulePost", payload: draftPost },
      (response) => {
        if (chrome.runtime.lastError) {
          return;
        }

        if (response?.success) {
          setDraftPost(null);
          setUploadedMedia([]);
          toast.success("Post scheduled successfully!");
          setShowSuccessScheduleModal(true);
        } else {
          toast.error("Failed to schedule post");
        }
      }
    );
  };

  const handlePostComplete = useCallback(() => {
    // Reset posting state in background script
    try {
      chrome.runtime.sendMessage({ action: "resetPostingState" }, (response) => {
        if (chrome.runtime.lastError) {
          console.error("Error resetting posting state:", chrome.runtime.lastError);
        } else {
          console.log("Posting state reset in background");
        }
      });
    } catch (e) {
      console.error("Error sending reset message:", e);
    }

    setShowPostProgress(false);
    setDraftPost({ content: "", schedule: null });
    setSelectedStyle(null);
  }, [setDraftPost]);

  const handleRemoveVideo = useCallback(() => {
    setVideoUrl(null);
  }, []);

  const removeMedia = (index: number, id: any) => {
    chrome.runtime.sendMessage({ action: "clearCurrentDB", fileId: id });
    setUploadedMedia((prevMedia) => {
      const updatedMedia = prevMedia.filter((_, i) => i !== index);
      chrome.storage.local.set({ uploadedMedia: updatedMedia });
      try {
        // if (mediaLength != 1) {
        //   sendChunksToBackground();
        // }
      } catch (e) {
        console.log(e);
      }
      return updatedMedia;
    });
  };

  const handleMediaUploadClick = () => {
    window.close();
    chrome.runtime.sendMessage({
      action: "show_select_files",
    });
  };

  // Wait for store to be hydrated from persistent storage before rendering
  if (!_hydrated) {
    return (
      <div className="flex items-center justify-center h-full bg-white">
        <div className="text-center">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto mb-2"></div>
          <div className="text-gray-500 text-sm">Loading...</div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-white">
      {/* Main Content Area */}
      <div className="flex-1 flex flex-col">
        {/* Group Selector and Schedule Info */}
        <div className="p-2 space-y-1.5">
          <GroupSelector
            onSelect={setSelectedGroup}
            selectedId={selectedGroupId}
            onManageGroups={(e, id) => {
              openGroupListManager(id);
            }}
            onEditGroup={(id) => {
              openGroupListManager(id);
            }}
          />

          {draftPost?.schedule && (
            <div className="flex items-center justify-between bg-blue-50 px-2 py-1 rounded-lg">
              <div className="flex items-center space-x-1.5">
                <Clock size={12} className="text-blue-600 flex-shrink-0" />
                <div className="flex flex-col min-w-0">
                  <span className="text-[10px] font-medium text-blue-700 truncate">
                    Starting from &nbsp;
                    {draftPost.schedule.startDate.toLocaleDateString()} •{" "}
                    {draftPost.schedule.time}
                  </span>
                  <span className="text-[10px] text-blue-600">
                    {draftPost.schedule.frequency}
                    {draftPost.schedule.frequency == "monthly" ? (
                      <>
                        {" "}
                        on {draftPost.schedule.recurring?.monthDays?.join(
                          ","
                        )}{" "}
                        of every month at {draftPost.schedule.time}
                      </>
                    ) : null}
                    {draftPost.schedule.frequency == "weekly" ? (
                      <>
                        {" "}
                        on{" "}
                        {draftPost.schedule.recurring?.weekDays
                          ?.map((day) => {
                            const dayNames = [
                              "Sunday",
                              "Monday",
                              "Tuesday",
                              "Wednesday",
                              "Thursday",
                              "Friday",
                              "Saturday",
                            ];
                            if (typeof day === "number") return dayNames[day] || String(day);
                            const s = String(day || "");
                            return s.charAt(0).toUpperCase() + s.slice(1);
                          })
                          .join(",")} {" "}
                        of every week at {draftPost.schedule.time}
                      </>
                    ) : null}
                  </span>
                </div>
              </div>
              <div className="flex items-center space-x-1 flex-shrink-0 ml-1">
                <button
                  onClick={() => handleScheduleClick()}
                  className="p-0.5 hover:bg-blue-100 rounded transition-colors"
                >
                  <Clock size={12} className="text-blue-600" />
                </button>
                <button
                  onClick={() => setDraftPost({ ...draftPost, schedule: null })}
                  className="p-0.5 hover:bg-blue-100 rounded transition-colors"
                >
                  <X size={12} className="text-blue-600" />
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Text Editor */}
        <div className="px-2 pb-2">
          <div className="border rounded-lg overflow-hidden shadow-sm">
            <RichTextEditor
              value={draftPost?.content || ""}
              onChange={handleContentChange}
              style={{
                background: selectedStyle?.value || undefined,
                color: selectedStyle?.textColor || undefined,
              }}
              onStyleChange={(s) => {
                setSelectedStyle(s?.id);
              }}
              characterCount={draftPost?.content?.length || 0}
              onMediaClick={handleMediaUploadClick}
              onEmojiClick={() => setShowEmojiPicker(true)}
              showEmojiPicker={showEmojiPicker}
              onScheduleClick={handleScheduleClick}
              draftSchedule={draftPost?.schedule}
              onEmojiSelect={onEmojiClick}
            />
          </div>

          {/* Video Preview */}
          {videoUrl && (
            <div className="mt-2">
              <LinkPreview url={videoUrl} onRemove={handleRemoveVideo} />
            </div>
          )}
        </div>

        {uploadedMedia.length > 0 && (
          <div
            id="selectedProductMedia"
            className="flex overflow-x-auto whitespace-nowrap gap-2 mt-1 mb-1.5"
          >
            {uploadedMedia.map((media, index) => (
              <div
                key={index}
                className="media-container relative border rounded-md overflow-hidden flex-none bg-black flex items-center justify-center"
                style={{ width: "70px", height: "70px" }}
              >
                {media.type === "image" ? (
                  <img
                    className="w-full h-full object-cover"
                    src={media.data}
                    alt={`Uploaded Image ${index}`}
                  />
                ) : (
                  <video
                    className="h-full object-contain"
                    src={media.data}
                    // controls
                  />
                )}
                <span
                  className="remove-icon absolute top-0 right-0 bg-gray-800 text-white text-sm cursor-pointer px-1"
                  onClick={() => removeMedia(index, media.id)}
                >
                  ✕
                </span>
              </div>
            ))}
          </div>
        )}

        {/* Delivery Pacing */}
        <div className="px-2">
          <div className="border rounded-lg overflow-hidden bg-white">
            <DeliveryOptions
              targetCount={
                selectedGroupId
                  ? groupLists.find((g) => g.id === selectedGroupId)?.urls
                      .length || 0
                  : 0
              }
              context="composer"
              isEnabled={!isContentEmpty(draftPost?.content) && !!selectedGroupId}
            />
          </div>
        </div>

        <div className="px-2 pt-2 pb-2 space-y-2">
          <div className="flex items-center gap-3">
            {draftPost?.schedule ? (
              /* Schedule Post Button - when scheduled */
              <button
                onClick={() =>
                  draftPost?.schedule ? schedulePost(draftPost) : handlePost()
                }
                disabled={isPosting || isContentEmpty(draftPost?.content) || !selectedGroupId}
                className={`
          flex-[2] py-3 rounded-xl text-sm font-semibold transition-all shadow-md 
          flex items-center justify-center gap-2
          bg-blue-600 text-white hover:bg-blue-700 
          disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-blue-600
          ${
            isContentEmpty(draftPost?.content) || !selectedGroupId || isPosting
              ? "opacity-50 hover:bg-blue-600 cursor-default"
              : ""
          }
        `}
              >
                <Clock size={18} />
                <span>
                  {isPosting ? "Posting..." : `Schedule post (
                  ${isPremium ? "Unlimited Left" : `${remainingPosts} left`})`}
                </span>
              </button>
            ) : (
              /* POST NOW Button - when not scheduled */
              <button
                onClick={() =>
                  draftPost?.schedule ? schedulePost(draftPost) : handlePost()
                }
                disabled={isPosting || isContentEmpty(draftPost?.content) || !selectedGroupId}
                className={`
          flex-[2] py-3 rounded-xl text-sm font-semibold transition-all shadow-md 
          flex items-center justify-center gap-2 uppercase tracking-wide
          bg-gradient-to-r from-blue-600 to-blue-500 text-white 
          hover:from-blue-700 hover:to-blue-600
          disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:from-blue-600 disabled:hover:to-blue-500
          ${
            isContentEmpty(draftPost?.content) || !selectedGroupId || isPosting
              ? "opacity-50 hover:from-blue-600 hover:to-blue-500 cursor-default"
              : ""
          }
        `}
              >
                <span>{isPosting ? "POSTING..." : "POST NOW"}</span>
                <span className="text-xs opacity-90">
                  ({isPremium ? "Unlimited" : `${remainingPosts} left`})
                </span>
              </button>
            )}

            {/* Schedule Button - 30% width */}
            <button
              onClick={handleScheduleClick}
              className={`
        flex-[1] py-3 bg-blue-50 text-blue-700 border border-blue-200 
        rounded-xl text-sm font-semibold uppercase tracking-wide 
        flex items-center justify-center gap-1.5
        ${
          isContentEmpty(draftPost?.content) || !selectedGroupId
            ? "opacity-50 cursor-default"
            : ""
        }
      `}
            >
              <Clock size={18} />
              SCHEDULE
            </button>
          </div>

          {/* Upgrade CTA left unchanged */}
        </div>
      </div>

      {/* Modals */}
      <CompactScheduleModal
        isOpen={showScheduleModal}
        onClose={() => setShowScheduleModal(false)}
        onSchedule={handleSchedule}
        initialSchedule={draftPost?.schedule || null}
        group={groupLists.find((group) => group.id === selectedGroupId)}
      />

      <GroupSelectionDialog
        isOpen={showGroupDialog}
        onClose={() => setShowGroupDialog(false)}
        onCreateGroup={() => {
          setShowGroupDialog(false);
          setShowGroupListManager(true);
        }}
      />

      <ValidationDialog
        isOpen={showValidationDialog}
        onClose={() => setShowValidationDialog(false)}
        message={validationMessage}
        missingGroup={missingGroup}
        missingContent={missingContent}
      />

      <SuccessDialog
        isOpen={showSuccessDialog}
        onClose={() => setShowSuccessDialog(false)}
        onContinue={() => {
          setShowSuccessDialog(false);
        }}
      />

      <ImmediatePostDialog
        isOpen={showImmediatePostDialog}
        onClose={() => setShowImmediatePostDialog(false)}
        onCreateGroup={() => {
          setShowImmediatePostDialog(false);
          openGroupListManager();
        }}
      />

      <GroupListManager
        selectedId={editableSelectedGroupId}
        isOpen={showGroupListManager}
        onClose={() => {
          setShowGroupListManager(false);
          try {
            chrome.storage.local.remove(["editListState"]);
          } catch {}
        }}
        onCreateList={(name) => {
          setShowGroupListManager(false);
          try {
            chrome.storage.local.remove(["editListState"]);
          } catch {}
        }}
        onSelectList={(listId) => {
          setSelectedGroup(listId);
          setShowGroupListManager(false);
          try {
            chrome.storage.local.remove(["editListState"]);
          } catch {}
        }}
      />

      <FormattingHelpDialog
        isOpen={showFormattingHelp}
        onClose={() => setShowFormattingHelp(false)}
      />

      <PostProgressManager
        isOpen={showPostProgress}
        onClose={handlePostComplete}
        groupUrls={groupUrls}
        postContent={draftPost?.content || ""}
      />

      <UpgradeDialog
        isOpen={showUpgradeDialog}
        onClose={() => setShowUpgradeDialog(false)}
        onUpgrade={() => {
          // Handle upgrade action
          setShowUpgradeDialog(false);
        }}
        email={email}
      />
      <PostingComponent
        payload={{
          action: "", // Fill with the action string
          post: {
            title: "postContent.slice(0, 30)",
            text: "postContent",
            images: null,
            links: [],
          },
          group: {
            title: "groupTitle",
            links: ["https://example.com/group-link"],
          },
          timeInSeconds: 20,
          activeIndex: "0",
          activeIndexProducts: "",
          avoidNightTimePosting: false,
        }}
      />
      {/* Notice modal */}
      {showNoticeModal ? (
        <>
          <div className="fixed inset-0 bg-black/30 z-[60] flex items-center justify-center">
            <div className="bg-white w-full max-w-sm mx-4 rounded-xl shadow-xl animate-scale-in">
              <div className="p-6">
                {/* Icon and Header */}
                <div className="flex items-start space-x-4">
                  <div className="w-12 h-12 rounded-full bg-blue-50 flex items-center justify-center flex-shrink-0">
                    <AlertCircle className="w-6 h-6 text-blue-600" />
                  </div>
                  <div className="flex-1">
                    <h3 className="text-xl font-semibold text-gray-900 mb-2">
                      Hold on! You're almost there.
                    </h3>
                    <p className="text-gray-600 leading-relaxed">
                      💡 Before scheduling your post, please create or select a
                      list of groups you'd like to send it to.
                    </p>
                  </div>
                </div>

                {/* Action Buttons */}
                <div className="mt-6 space-y-3">
                  <button
                    onClick={() => {
                      setShowNoticeModal(false);
                      openGroupListManager();
                    }}
                    className="w-full px-4 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium transition-colors flex items-center justify-center space-x-2 group"
                  >
                    <ListPlus className="w-5 h-5" />
                    <span>Create Group List</span>
                  </button>

                  <button
                    onClick={() => setShowNoticeModal(false)}
                    className="w-full px-4 py-3 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-lg font-medium transition-colors"
                  >
                    Back
                  </button>
                </div>
              </div>
            </div>
          </div>
        </>
      ) : (
        <></>
      )}
      {showContentNoticeModal ? (
        <>
          <div className="fixed inset-0 bg-black/30 z-[60] flex items-center justify-center">
            <div className="bg-white w-full max-w-sm mx-4 rounded-xl shadow-xl animate-scale-in">
              <div className="p-6">
                {/* Icon and Message */}
                <div className="flex items-start space-x-4">
                  <div className="w-10 h-10 rounded-full bg-amber-100 flex items-center justify-center flex-shrink-0">
                    <AlertCircle className="w-5 h-5 text-amber-600" />
                  </div>
                  <div className="flex-1 pt-1">
                    <h3 className="text-lg font-semibold text-gray-900 mb-2">
                      Oops! You missed a step.
                    </h3>
                    <p className="text-gray-600">
                      Please enter some content for your post before scheduling.
                    </p>
                  </div>
                </div>

                {/* Action Button */}
                <div className="mt-6">
                  <button
                    onClick={() => setShowContentNoticeModal(false)}
                    className="w-full px-4 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium transition-colors"
                  >
                    OK
                  </button>
                </div>
              </div>
            </div>
          </div>
        </>
      ) : (
        <></>
      )}
      {showSuccessScheduleModal ? (
        <>
          <div
            id="static-modal"
            data-modal-backdrop="static"
            tabIndex="-1"
            aria-hidden="true"
            className="overflow-y-auto overflow-x-hidden fixed top-0 right-0 left-0 z-50 flex justify-center items-center w-full md:inset-0 h-[calc(100%-1rem)] max-h-full bg-white"
            style={{
              backgroundColor: "#00000069",
              backdropFilter: "blur(5px)",
              height: "100%",
            }}
          >
            <div className="relative p-4 w-full max-w-2xl max-h-full">
              <div className="relative bg-white rounded-lg shadow-lg border border-gray-200">
                <div className="flex items-center justify-between p-4 md:p-5 border-b border-gray-200 rounded-t">
                  <h3 className="text-xl font-semibold text-gray-900 flex items-center gap-2">
                    <svg
                      className="w-6 h-6 text-blue-600"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
                      />
                    </svg>
                    Done!
                  </h3>
                </div>
                <div className="p-4 md:p-5 space-y-4">
                  <div className="flex items-start gap-3">
                    <svg
                      className="w-6 h-6 text-green-500 mt-1"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        d="M5 13l4 4L19 7"
                      />
                    </svg>
                    <p className="text-base text-gray-700">
                      Schedule successful.
                    </p>
                  </div>
                </div>
                <div className="flex items-center p-4 md:p-5 border-t border-gray-200 rounded-b">
                  <button
                    data-modal-hide="static-modal"
                    type="button"
                    className="text-white bg-blue-600 hover:bg-blue-700 focus:ring-4 focus:outline-none focus:ring-blue-300 font-medium rounded-lg text-sm px-5 py-2.5 w[100px]"
                    onClick={() => setShowSuccessScheduleModal(false)}
                  >
                    Close
                  </button>
                </div>
              </div>
            </div>
          </div>
        </>
      ) : (
        <></>
      )}
      {showScheduleFinalStep ? (
        <>
          <div className="fixed inset-0 bg-black/30 z-[70] flex items-center justify-center p-3">
            <div className="bg-white w-full max-w-[420px] rounded-2xl shadow-2xl overflow-hidden animate-scale-in">
              {/* Header */}
              <div className="bg-gradient-to-r from-blue-500 to-blue-600 px-5 py-6">
                <div className="flex items-center gap-3 text-white">
                  <div className="w-12 h-12 bg-white/20 rounded-xl flex items-center justify-center backdrop-blur-sm">
                    <Sparkles size={24} className="text-white" />
                  </div>
                  <div>
                    <h2 className="text-xl font-bold">Almost there!</h2>
                    <p className="text-blue-100 text-xs mt-0.5">
                      One final step to schedule your post
                    </p>
                  </div>
                </div>
              </div>

              {/* Body */}
              <div className="p-4 space-y-3">
                {/* Success Message */}
                <div className="bg-green-50 border border-green-200 rounded-xl p-3 flex items-start gap-2">
                  <PartyPopper
                    size={20}
                    className="text-green-600 flex-shrink-0 mt-0.5"
                  />
                  <p className="text-green-800 font-medium text-sm">
                    Great job! You've set up your schedule.
                  </p>
                </div>

                {/* Next Steps */}
                <div className="bg-blue-50 rounded-xl p-4 space-y-3">
                  <h3 className="font-semibold text-blue-900 text-sm">
                    Next steps:
                  </h3>

                  <div className="space-y-2">
                    <div className="flex gap-2.5">
                      <div className="w-6 h-6 bg-blue-600 text-white rounded-full flex items-center justify-center flex-shrink-0 font-semibold text-xs">
                        1
                      </div>
                      <p className="text-blue-900 font-medium text-xs pt-0.5">
                        Click 'Continue' below
                      </p>
                    </div>

                    <div className="flex gap-2.5">
                      <div className="w-6 h-6 bg-blue-600 text-white rounded-full flex items-center justify-center flex-shrink-0 font-semibold text-xs">
                        2
                      </div>
                      <p className="text-blue-900 font-medium text-xs pt-0.5">
                        Click the 'Schedule Post' button to save your post
                      </p>
                    </div>
                  </div>
                </div>

                {/* Warning */}
                <div className="bg-amber-50 border-2 border-amber-200 rounded-xl p-3 flex items-start gap-2">
                  <AlertTriangle
                    size={18}
                    className="text-amber-600 flex-shrink-0 mt-0.5"
                  />
                  <div>
                    <p className="text-amber-900 font-semibold text-xs">
                      Important:{" "}
                      <span className="font-normal">
                        Keep this browser tab open until the post is scheduled.
                      </span>
                    </p>
                  </div>
                </div>
              </div>

              {/* Footer */}
              <div className="px-4 pb-4">
                <button
                  onClick={() => setShowScheduleFinalStep(false)}
                  className="w-full bg-blue-600 text-white rounded-xl px-5 py-3 font-semibold text-sm
              hover:bg-blue-700 active:bg-blue-800 transition-colors
              flex items-center justify-center gap-2 group"
                >
                  Continue
                  <ArrowRight
                    size={18}
                    className="group-hover:translate-x-1 transition-transform"
                  />
                </button>
              </div>
            </div>
          </div>
        </>
      ) : (
        <></>
      )}
    </div>
  );
}
