import React from 'react';
import { CheckCircle2, XCircle, Clock, AlertCircle } from 'lucide-react';
import { motion } from 'framer-motion';
import type { GroupPostStatus } from './types';

interface PostProgressListProps {
  groups: GroupPostStatus[];
  currentIndex: number;
}

export function PostProgressList({ groups, currentIndex }: PostProgressListProps) {
  return (
    <div className="space-y-2 max-h-[240px] overflow-y-auto pr-2">
      {groups.map((group, index) => (
        <motion.div
          key={group.url}
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: index * 0.1 }}
          className={`
            flex items-center justify-between p-3 rounded-xl border
            ${index === currentIndex && group.status === 'pending'
              ? 'bg-blue-50 border-blue-200'
              : group.status === 'success'
              ? 'bg-green-50 border-green-100'
              : group.status === 'error'
              ? 'bg-red-50 border-red-100'
              : 'bg-gray-50 border-gray-200'
            }
          `}
        >
          <div className="flex items-center space-x-3 min-w-0">
            <div className={`
              w-8 h-8 rounded-lg flex items-center justify-center
              ${index === currentIndex && group.status === 'pending'
                ? 'bg-blue-100'
                : group.status === 'success'
                ? 'bg-green-100'
                : group.status === 'error'
                ? 'bg-red-100'
                : 'bg-gray-100'
              }
            `}>
              {group.status === 'success' && (
                <CheckCircle2 size={16} className="text-green-600" />
              )}
              {group.status === 'error' && (
                <XCircle size={16} className="text-red-600" />
              )}
              {group.status === 'pending' && index === currentIndex && (
                <Clock size={16} className="text-blue-600 animate-pulse" />
              )}
              {group.status === 'pending' && index !== currentIndex && (
                <Clock size={16} className="text-gray-400" />
              )}
            </div>
            <div className="min-w-0">
              <p className="text-sm font-medium truncate">
                {group.name}
              </p>
              {group.error && (
                <p className="text-xs text-red-600 mt-0.5 flex items-center space-x-1">
                  <AlertCircle size={12} />
                  <span>{group.error}</span>
                </p>
              )}
            </div>
          </div>

          <div className="ml-3 flex-shrink-0">
            {group.status === 'pending' && index === currentIndex && (
              <span className="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded-full font-medium animate-pulse">
                Posting...
              </span>
            )}
          </div>
        </motion.div>
      ))}
    </div>
  );
}