/**
 * Serializes a Date object to a string
 * @param {Date|string} date - The date to serialize
 * @returns {string} - The serialized date string
 */
export const serializeDate = (date) => {
  if (typeof date === 'string') return date;
  return date.toISOString();
};

/**
 * Deserializes a date string to a Date object
 * @param {string} dateStr - The date string to deserialize
 * @returns {Date} - The deserialized Date object
 */
export const deserializeDate = (dateStr) => new Date(dateStr);

/**
 * Formats a Date object to a time string
 * @param {Date} date - The date to format
 * @returns {string} - The formatted time string
 */
export const formatTime = (date) => {
  return date.toLocaleTimeString('en-US', { 
    hour12: false, 
    hour: '2-digit', 
    minute: '2-digit' 
  });
};

/**
 * Formats a Date object to a schedule date string
 * @param {Date} date - The date to format
 * @returns {string} - The formatted date string
 */
export const formatScheduleDate = (date) => {
  return date.toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });
};

/**
 * Calculate the next scheduled time based on schedule configuration
 * @param {any} schedule - The schedule configuration object
 * @returns {Date|null} - The next scheduled Date or null if schedule is invalid
 */
export const getNextScheduledTime = (schedule) => {
  if (!schedule || !schedule.startDate || !schedule.time) {
    return null;
  }

  const now = new Date();
  const [hours, minutes] = schedule.time.split(':').map(Number);
  
  // Parse start date
  const startDate = new Date(schedule.startDate);
  
  // Create a date with the scheduled time today
  const todayScheduled = new Date(now);
  todayScheduled.setHours(hours, minutes, 0, 0);
  
  // If start date is in the future, return start date with time
  if (startDate > now) {
    const nextDate = new Date(startDate);
    nextDate.setHours(hours, minutes, 0, 0);
    return nextDate;
  }
  
  // Handle different frequencies
  switch (schedule.frequency) {
    case 'once':
      // For one-time schedules, check if it's already passed
      const onceDate = new Date(startDate);
      onceDate.setHours(hours, minutes, 0, 0);
      return onceDate > now ? onceDate : onceDate;
      
    case 'daily':
      // If today's scheduled time hasn't passed, return it
      if (todayScheduled > now) {
        return todayScheduled;
      }
      // Otherwise, return tomorrow
      const tomorrow = new Date(todayScheduled);
      tomorrow.setDate(tomorrow.getDate() + 1);
      return tomorrow;
      
    case 'weekly':
      if (schedule.recurring?.weekDays && schedule.recurring.weekDays.length > 0) {
        const currentDay = now.getDay();
        const sortedDays = [...schedule.recurring.weekDays].sort((a, b) => a - b);
        
        // Check if today is a scheduled day and time hasn't passed
        if (sortedDays.includes(currentDay) && todayScheduled > now) {
          return todayScheduled;
        }
        
        // Find next scheduled day
        let daysToAdd = null;
        for (const day of sortedDays) {
          if (day > currentDay || (day === currentDay && todayScheduled <= now)) {
            daysToAdd = day - currentDay;
            if (daysToAdd === 0) daysToAdd = 7;
            break;
          }
        }
        
        // If no day found after current day, use first day of next week
        if (daysToAdd === null) {
          daysToAdd = 7 - currentDay + sortedDays[0];
        }
        
        const nextDate = new Date(todayScheduled);
        nextDate.setDate(nextDate.getDate() + daysToAdd);
        return nextDate;
      }
      break;
      
    case 'monthly':
      if (schedule.recurring?.monthDays && schedule.recurring.monthDays.length > 0) {
        const currentDate = now.getDate();
        const sortedDays = [...schedule.recurring.monthDays].sort((a, b) => a - b);
        
        // Check if today is a scheduled day and time hasn't passed
        if (sortedDays.includes(currentDate) && todayScheduled > now) {
          return todayScheduled;
        }
        
        // Find next scheduled day in current month
        for (const day of sortedDays) {
          if (day > currentDate) {
            const nextDate = new Date(now.getFullYear(), now.getMonth(), day, hours, minutes, 0, 0);
            return nextDate;
          }
        }
        
        // If no day found in current month, use first day of next month
        const nextMonth = new Date(now.getFullYear(), now.getMonth() + 1, sortedDays[0], hours, minutes, 0, 0);
        return nextMonth;
      }
      break;
  }
  
  // Fallback to start date
  const fallbackDate = new Date(startDate);
  fallbackDate.setHours(hours, minutes, 0, 0);
  return fallbackDate;
};

/**
 * Format next scheduled time for display
 * @param {any} schedule - The schedule configuration object
 * @returns {string} - Formatted string showing next scheduled date and time
 */
export const formatNextScheduledTime = (schedule) => {
  const nextTime = getNextScheduledTime(schedule);
  
  if (!nextTime) {
    return 'No schedule';
  }
  
  return `${nextTime.toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  })} at ${nextTime.toLocaleTimeString('en-US', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: true
  })}`;
};