import React, { useState } from 'react';
import { ChevronDown, Users, Plus, MoreVertical, Edit2, Trash2 } from 'lucide-react';
import { useGroupStore } from '../../stores/groupStore';
import { DeleteGroupDialog } from './Groups/DeleteGroupDialog';

export function GroupSelector({ onSelect, selectedId, onManageGroups, onEditGroup }) {
  const [isOpen, setIsOpen] = useState(false);
  const [openMenuId, setOpenMenuId] = useState(null);
  const [menuPosition, setMenuPosition] = useState(null);
  const [deleteDialog, setDeleteDialog] = useState({ isOpen: false, groupId: '', groupName: '' });
  const { groupLists, removeGroupList } = useGroupStore();

  // Auto-select if only one group exists, or restore from localStorage
  React.useEffect(() => {
    if (groupLists.length === 1 && !selectedId) {
      onSelect(groupLists[0].id);
      localStorage.setItem('selectedGroupId', groupLists[0].id);
    } else if (groupLists.length > 0 && !selectedId) {
      // Try to restore from localStorage
      const savedGroupId = localStorage.getItem('selectedGroupId');
      if (savedGroupId && groupLists.find(g => g.id === savedGroupId)) {
        onSelect(savedGroupId);
      }
    }
  }, [groupLists, selectedId, onSelect]);

  const hasNoLists = groupLists.length === 0;
  const hasOnlyOneList = groupLists.length === 1;
  const isClickable = groupLists.length > 1;

  const selectedGroup = groupLists.find(g => g.id === selectedId);

  let displayText = 'Select group';
  let textColor = 'text-gray-400';

  if (hasNoLists) {
    displayText = 'No lists created';
    textColor = 'text-gray-400';
  } else if (hasOnlyOneList) {
    displayText = groupLists[0].name;
    textColor = 'text-gray-700';
  } else if (selectedGroup) {
    displayText = selectedGroup.name;
    textColor = 'text-gray-700';
  }

  return (
    <div className="relative">
      <div className="flex items-center justify-between gap-4">
        <div className="flex-1 flex items-center gap-2 bg-white border border-gray-300 rounded-lg">
          <button
            onClick={() => isClickable && setIsOpen(!isOpen)}
            disabled={!isClickable}
            className={`
              flex-1 flex items-center justify-between px-3 py-2 transition-all
              text-sm font-medium
              ${!isClickable ? 'cursor-not-allowed' : ''} ${textColor}
            `}
          >
            <div className="flex items-center space-x-2">
              <Users size={18} className={!isClickable || !selectedGroup ? 'text-gray-400' : 'text-gray-500'} />
              <span>{displayText}</span>
            </div>
            {isClickable && <ChevronDown size={16} className="text-gray-400" />}
          </button>

          {hasOnlyOneList && groupLists[0] && (
            <div className="relative border-l border-gray-200">
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  setOpenMenuId(openMenuId === 'main' ? null : 'main');
                }}
                className="p-2.5 hover:bg-gray-50 transition-colors"
              >
                <MoreVertical size={16} className="text-gray-500" />
              </button>

              {openMenuId === 'main' && (
                <>
                  <div
                    className="fixed inset-0 z-40"
                    onClick={() => setOpenMenuId(null)}
                  />
                  <div className="absolute right-0 top-full mt-2 w-52 bg-white border border-gray-200 rounded-xl shadow-2xl z-50 py-2">
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        setOpenMenuId(null);
                        onEditGroup?.(groupLists[0].id);
                      }}
                      className="w-full px-4 py-3 text-left hover:bg-blue-50 flex items-center gap-3.5 text-gray-800 transition-all group"
                    >
                      <div className="w-8 h-8 rounded-lg bg-blue-100 flex items-center justify-center group-hover:bg-blue-200 transition-colors">
                        <Edit2 size={16} className="text-blue-600" />
                      </div>
                      <span className="font-medium text-sm">Edit URLs</span>
                    </button>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        setDeleteDialog({ isOpen: true, groupId: groupLists[0].id, groupName: groupLists[0].name });
                        setOpenMenuId(null);
                      }}
                      className="w-full px-4 py-3 text-left hover:bg-red-50 flex items-center gap-3.5 text-gray-800 transition-all group"
                    >
                      <div className="w-8 h-8 rounded-lg bg-red-100 flex items-center justify-center group-hover:bg-red-200 transition-colors">
                        <Trash2 size={16} className="text-red-600" />
                      </div>
                      <span className="font-medium text-sm">Delete List</span>
                    </button>
                  </div>
                </>
              )}
            </div>
          )}
        </div>

        <button
          onClick={onManageGroups}
          className={`py-3 px-4 rounded-full text-sm font-semibold uppercase tracking-wide flex items-center justify-center gap-1.5 transition-all ${
            hasNoLists
              ? 'bg-gradient-to-r from-blue-600 to-blue-500 text-white hover:from-blue-700 hover:to-blue-600 shadow-md hover:shadow-lg'
              : 'bg-blue-50 text-blue-700 border border-blue-200 hover:bg-blue-100'
          }`}
        >
          <Plus size={18} />
          ADD LIST
        </button>
      </div>

      {isOpen && isClickable && (
        <>
          <div
            className="fixed inset-0 z-40"
            onClick={() => setIsOpen(false)}
          />
          <div className="absolute top-full left-0 mt-2 w-full bg-white border border-gray-200 rounded-xl shadow-2xl z-50">
            <div className="max-h-[200px] overflow-y-auto">
              {groupLists.map((group, index) => (
                <div
                  key={group.id}
                  className={`
                    flex items-center justify-between transition-colors
                    ${selectedId === group.id ? 'bg-blue-50' : 'hover:bg-gray-50'}
                    ${index !== 0 ? 'border-t border-gray-100' : ''}
                  `}
                >
                  <button
                    onClick={() => {
                      onSelect(group.id);
                      localStorage.setItem('selectedGroupId', group.id);
                      setIsOpen(false);
                    }}
                    className={`
                      flex-1 px-4 py-3 text-left text-sm flex items-center gap-3
                      ${selectedId === group.id
                        ? 'text-blue-600 font-medium'
                        : 'text-gray-700'
                      }
                    `}
                  >
                    <Users size={18} className={selectedId === group.id ? 'text-blue-600' : 'text-gray-400'} />
                    <span className="flex-1">{group.name}</span>
                    {selectedId === group.id && (
                      <div className="w-2 h-2 rounded-full bg-blue-600"></div>
                    )}
                  </button>

                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      const rect = e.currentTarget.getBoundingClientRect();
                      setMenuPosition({
                        top: rect.bottom + 8,
                        left: rect.right - 208
                      });
                      setOpenMenuId(openMenuId === group.id ? null : group.id);
                    }}
                    className="p-2 mr-3 hover:bg-gray-200/60 rounded-md transition-all z-10"
                  >
                    <MoreVertical size={16} className="text-gray-500" />
                  </button>
                </div>
              ))}
            </div>
          </div>

          {openMenuId && menuPosition && (
            <>
              <div
                className="fixed inset-0 z-[60]"
                onClick={() => {
                  setOpenMenuId(null);
                  setMenuPosition(null);
                }}
              />
              <div
                className="fixed z-[70] w-52 bg-white border border-gray-200 rounded-xl shadow-2xl py-2"
                style={{
                  top: `${menuPosition.top}px`,
                  left: `${menuPosition.left}px`
                }}
              >
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    const group = groupLists.find(g => g.id === openMenuId);
                    setOpenMenuId(null);
                    setMenuPosition(null);
                    setIsOpen(false);
                    if (group) {
                      onEditGroup?.(group.id);
                    }
                  }}
                  className="w-full px-4 py-3 text-left hover:bg-blue-50 flex items-center gap-3.5 text-gray-800 transition-all group"
                >
                  <div className="w-8 h-8 rounded-lg bg-blue-100 flex items-center justify-center group-hover:bg-blue-200 transition-colors">
                    <Edit2 size={16} className="text-blue-600" />
                  </div>
                  <span className="font-medium text-sm">Edit URLs</span>
                </button>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    const group = groupLists.find(g => g.id === openMenuId);
                    if (group) {
                      setDeleteDialog({ isOpen: true, groupId: group.id, groupName: group.name });
                    }
                    setOpenMenuId(null);
                    setMenuPosition(null);
                  }}
                  className="w-full px-4 py-3 text-left hover:bg-red-50 flex items-center gap-3.5 text-gray-800 transition-all group"
                >
                  <div className="w-8 h-8 rounded-lg bg-red-100 flex items-center justify-center group-hover:bg-red-200 transition-colors">
                    <Trash2 size={16} className="text-red-600" />
                  </div>
                  <span className="font-medium text-sm">Delete List</span>
                </button>
              </div>
            </>
          )}
        </>
      )}

      <DeleteGroupDialog
        isOpen={deleteDialog.isOpen}
        onClose={() => setDeleteDialog({ isOpen: false, groupId: '', groupName: '' })}
        onConfirm={() => {
          removeGroupList(deleteDialog.groupId);
          if (selectedId === deleteDialog.groupId) {
            onSelect(groupLists.filter(g => g.id !== deleteDialog.groupId)[0]?.id || '');
          }
        }}
        groupName={deleteDialog.groupName}
      />
    </div>
  );
}
