import React from 'react';
import { AlertCircle, Users, FileText } from 'lucide-react';

export function ValidationDialog({ isOpen, onClose, missingGroup, missingContent, message }) {
  if (!isOpen) return null;

  const hasMissing = missingGroup || missingContent;
  const subtitle = hasMissing
    ? 'Please complete the following:'
    : message || 'Please review your post details before continuing.';

  return (
    <div className="fixed inset-0 bg-black/30 z-[60] flex items-center justify-center">
      <div className="bg-white w-full max-w-md mx-4 rounded-full shadow-xl animate-scale-in">
        <div className="p-6">
          {/* Header */}
          <div className="flex items-center justify-center mb-4">
            <div className="w-14 h-14 rounded-full bg-amber-50 flex items-center justify-center">
              <AlertCircle className="w-7 h-7 text-amber-600" />
            </div>
          </div>
          
          <h3 className="text-xl font-bold text-gray-900 text-center mb-2">
            Wait! Before you continue...
          </h3>
          
          <p className="text-gray-600 text-center mb-6 text-sm">
            {subtitle}
          </p>

          {/* Missing Items List */}
          {hasMissing && (
            <div className="space-y-3 mb-6">
              {missingGroup && (
                <div className="flex items-center gap-3 p-3 bg-blue-50 rounded-full border border-blue-100">
                  <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center flex-shrink-0">
                    <Users className="w-4 h-4 text-blue-600" />
                  </div>
                  <div className="flex-1">
                    <p className="text-sm font-medium text-gray-900">Select a group list</p>
                    <p className="text-xs text-gray-600">Choose where to send your post</p>
                  </div>
                </div>
              )}
              
              {missingContent && (
                <div className="flex items-center gap-3 p-3 bg-purple-50 rounded-full border border-purple-100">
                  <div className="w-8 h-8 rounded-full bg-purple-100 flex items-center justify-center flex-shrink-0">
                    <FileText className="w-4 h-4 text-purple-600" />
                  </div>
                  <div className="flex-1">
                    <p className="text-sm font-medium text-gray-900">Write your post</p>
                    <p className="text-xs text-gray-600">Add some content to share</p>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Action Button */}
          <button
            onClick={onClose}
            className="w-full px-4 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-full font-semibold transition-colors"
          >
            Got it!
          </button>
        </div>
      </div>
    </div>
  );
}