import { create } from "zustand";
import { persist } from "zustand/middleware";

export interface GroupList {
  id: string;
  name: string;
  count: number;
  urls: string[];
  createdAt?: Date;
}

// ============================================================
// IndexedDB Helper Functions for Triple Redundancy
// ============================================================

const DB_NAME = "GroupStoreDB";
const DB_VERSION = 1;
const STORE_NAME = "groupData";

async function openGroupStoreDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => {
      reject(new Error("Failed to open IndexedDB"));
    };

    request.onsuccess = () => {
      resolve(request.result);
    };

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "key" });
      }
    };
  });
}

async function saveToIndexedDB(key: string, data: any): Promise<void> {
  try {
    const db = await openGroupStoreDB();
    const transaction = db.transaction(STORE_NAME, "readwrite");
    const store = transaction.objectStore(STORE_NAME);

    return new Promise((resolve, reject) => {
      const request = store.put({ key, data, timestamp: Date.now() });

      request.onerror = () => {
        reject(new Error("Failed to save to IndexedDB"));
      };

      request.onsuccess = () => {
        resolve();
      };
    });
  } catch (error) {
    console.warn("IndexedDB save failed:", error);
  }
}

async function loadFromIndexedDB(key: string): Promise<any | null> {
  try {
    const db = await openGroupStoreDB();
    const transaction = db.transaction(STORE_NAME, "readonly");
    const store = transaction.objectStore(STORE_NAME);

    return new Promise((resolve, reject) => {
      const request = store.get(key);

      request.onerror = () => {
        reject(new Error("Failed to read from IndexedDB"));
      };

      request.onsuccess = () => {
        resolve(request.result?.data || null);
      };
    });
  } catch (error) {
    console.warn("IndexedDB load failed:", error);
    return null;
  }
}

async function removeFromIndexedDB(key: string): Promise<void> {
  try {
    const db = await openGroupStoreDB();
    const transaction = db.transaction(STORE_NAME, "readwrite");
    const store = transaction.objectStore(STORE_NAME);

    return new Promise((resolve, reject) => {
      const request = store.delete(key);

      request.onerror = () => {
        reject(new Error("Failed to remove from IndexedDB"));
      };

      request.onsuccess = () => {
        resolve();
      };
    });
  } catch (error) {
    console.warn("IndexedDB remove failed:", error);
  }
}

// ============================================================
// Multi-Storage Save/Load Helper
// ============================================================

async function saveToAllStorages(key: string, payload: any): Promise<void> {
  const promises: Promise<void>[] = [];

  // 1. Save to chrome.storage
  const isChrome = typeof chrome !== "undefined" && chrome.storage && chrome.storage.local;
  if (isChrome) {
    promises.push(
      new Promise<void>((resolve) => {
        chrome.storage.local.set({ [key]: payload }, () => {
          if ((chrome as any).runtime?.lastError) {
            console.warn("Chrome storage save failed:", (chrome as any).runtime.lastError);
          }
          resolve();
        });
      })
    );
  }

  // 2. Save to localStorage
  if (typeof localStorage !== "undefined") {
    try {
      localStorage.setItem(key, JSON.stringify(payload));
    } catch (error) {
      console.warn("localStorage save failed:", error);
    }
  }

  // 3. Save to IndexedDB
  promises.push(saveToIndexedDB(key, payload));

  // Execute all saves in parallel (don't wait for them to complete)
  Promise.all(promises).catch((error) => {
    console.warn("One or more storage backends failed:", error);
  });
}

async function loadFromAllStorages(key: string): Promise<any | null> {
  const isChrome = typeof chrome !== "undefined" && chrome.storage && chrome.storage.local;

  // 1. Try chrome.storage first
  if (isChrome) {
    try {
      const result = await new Promise<any>((resolve) => {
        chrome.storage.local.get([key], (result) => resolve(result));
      });
      const data = result?.[key];
      if (data) {
        return data;
      }
    } catch (error) {
      console.warn("Chrome storage load failed:", error);
    }
  }

  // 2. If empty, try localStorage
  if (typeof localStorage !== "undefined") {
    try {
      const stored = localStorage.getItem(key);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (parsed) {
          // Restore to chrome.storage
          if (isChrome) {
            await new Promise<void>((resolve) => {
              chrome.storage.local.set({ [key]: parsed }, () => resolve());
            });
          }
          return parsed;
        }
      }
    } catch (error) {
      console.warn("localStorage load failed:", error);
    }
  }

  // 3. If still empty, try IndexedDB
  try {
    const data = await loadFromIndexedDB(key);
    if (data) {
      // Restore to chrome.storage
      if (isChrome) {
        await new Promise<void>((resolve) => {
          chrome.storage.local.set({ [key]: data }, () => resolve());
        });
      }
      return data;
    }
  } catch (error) {
    console.warn("IndexedDB load failed:", error);
  }

  return null;
}

interface GroupStoreState {
  groupLists: GroupList[];
  selectedGroupListId: string | null;
}

interface GroupStoreActions {
  addGroupList: (groupList: GroupList) => void;
  removeGroupList: (id: string) => void;
  updateGroupList: (id: string, updates: Partial<GroupList>) => void;
  setSelectedGroupList: (id: string | null) => void;
}

type GroupStore = GroupStoreState & GroupStoreActions;

export const useGroupStore = create<GroupStore>()(
  persist(
    (set) => ({
      // State
      groupLists: [],
      selectedGroupListId: null,

      // Actions
      addGroupList: (groupList) => {
        const newGroupList = {
          ...groupList,
          createdAt: new Date(),
        };

        set((state) => {
          // Check if we're updating an existing list
          const existingIndex = state.groupLists.findIndex(
            (list) => list.id === groupList.id
          );

          if (existingIndex >= 0) {
            // Update existing list
            const updatedLists = [...state.groupLists];
            updatedLists[existingIndex] = newGroupList;
            return { groupLists: updatedLists };
          } else {
            // Add new list
            return { groupLists: [...state.groupLists, newGroupList] };
          }
        });
      },

      removeGroupList: (id) => {
        set((state) => ({
          groupLists: state.groupLists.filter((list) => list.id !== id),
          selectedGroupListId:
            state.selectedGroupListId === id ? null : state.selectedGroupListId,
        }));
      },

      updateGroupList: (id, updates) => {
        set((state) => ({
          groupLists: state.groupLists.map((list) =>
            list.id === id ? { ...list, ...updates } : list
          ),
        }));
      },

      setSelectedGroupList: (id) => {
        set({ selectedGroupListId: id });
      },
    }),
    {
      name: "fb-group-lists",
      storage: {
        getItem: async (name) => {
          const safeParse = (str: string | null) => {
            if (!str) return null;
            try { return JSON.parse(str); } catch (e) { console.error('Failed to parse GroupStore, preserving:', e); return null; }
          };

          // Use the multi-storage load function
          const data = await loadFromAllStorages(name);

          if (!data) return null;

          return {
            ...data,
            state: {
              ...data.state,
              groupLists: data.state?.groupLists?.map((list: any) => ({
                ...list,
                createdAt: list.createdAt ? new Date(list.createdAt) : new Date(),
              })) || [],
              selectedGroupListId: typeof data.state?.selectedGroupListId === 'string' ? data.state.selectedGroupListId : null,
            },
          };
        },
        setItem: async (name, value) => {
          const payload = {
            ...value,
            state: {
              ...value.state,
              selectedGroupListId: typeof value.state.selectedGroupListId === 'string' ? value.state.selectedGroupListId : null,
              groupLists: value.state.groupLists.map((list: GroupList) => ({
                id: String(list.id),
                name: String(list.name),
                count: Number(list.count),
                urls: Array.isArray(list.urls) ? list.urls.map((u) => String(u)) : [],
                createdAt: list.createdAt?.toISOString() || new Date().toISOString(),
              })),
            },
          };

          // Use the multi-storage save function (saves to all 3 places simultaneously)
          await saveToAllStorages(name, payload);
        },
        removeItem: async (name) => {
          const isChrome = typeof chrome !== "undefined" && chrome.storage && chrome.storage.local;

          // Remove from chrome.storage
          if (isChrome) {
            await new Promise<void>((resolve) => {
              chrome.storage.local.remove([name], () => resolve());
            });
          }

          // Remove from localStorage
          if (typeof localStorage !== "undefined") {
            try {
              localStorage.removeItem(name);
            } catch (error) {
              console.warn("localStorage remove failed:", error);
            }
          }

          // Remove from IndexedDB
          try {
            await removeFromIndexedDB(name);
          } catch (error) {
            console.warn("IndexedDB remove failed:", error);
          }
        },
      },
    }
  )
);

