import React, { memo } from 'react';

export const FrequencyButton = memo(function FrequencyButton({ 
  frequency, 
  isSelected, 
  onClick,
  showMultiSelect 
}) {
  const label = frequency.charAt(0).toUpperCase() + frequency.slice(1);
  
  return (
    <button
      type="button"
      onClick={onClick}
      className={`
        px-4 py-2.5 text-sm font-medium rounded-lg transition-all relative
        ${isSelected
          ? 'bg-blue-50 text-blue-600 ring-1 ring-blue-600'
          : 'bg-gray-50 text-gray-700 hover:bg-gray-100'
        }
      `}
    >
      {label}
      {showMultiSelect && (
        <span className="absolute -top-1 -right-1 bg-blue-100 text-blue-600 text-[10px] px-1.5 py-0.5 rounded-full">
          Multi-select
        </span>
      )}
    </button>
  );
});