import React from 'react';
import { Check, X } from 'lucide-react';

interface PasswordStrength {
  hasMinLength: boolean;
  hasUppercase: boolean;
  hasLowercase: boolean;
  hasNumber: boolean;
  hasSpecial: boolean;
}

interface PasswordRequirementsProps {
  password: string;
  strength: PasswordStrength;
}

const PasswordRequirements: React.FC<PasswordRequirementsProps> = ({ password, strength }) => {
  // Calculate overall strength (0-5)
  const strengthCount = Object.values(strength).filter(Boolean).length;
  
  // Get strength level and color
  const getStrengthInfo = () => {
    if (strengthCount <= 1) return { level: 'Very Weak', color: 'bg-red-500' };
    if (strengthCount === 2) return { level: 'Weak', color: 'bg-orange-500' };
    if (strengthCount === 3) return { level: 'Fair', color: 'bg-yellow-500' };
    if (strengthCount === 4) return { level: 'Good', color: 'bg-blue-500' };
    return { level: 'Strong', color: 'bg-green-500' };
  };
  
  const { level, color } = getStrengthInfo();
  
  // Calculate progress bar width
  const progressWidth = `${(strengthCount / 5) * 100}%`;
  
  const RequirementItem = ({ met, text }: { met: boolean; text: string }) => (
    <li className="flex items-center space-x-2 text-sm">
      {met ? (
        <Check className="h-4 w-4 text-green-500" />
      ) : (
        <X className="h-4 w-4 text-gray-400" />
      )}
      <span className={met ? 'text-gray-700' : 'text-gray-500'}>
        {text}
      </span>
    </li>
  );
  
  return (
    <div className="mt-3 bg-gray-50 p-3 rounded-md border border-gray-100 text-sm">
      <div className="mb-2">
        <div className="flex justify-between mb-1">
          <span className="text-xs font-medium text-gray-700">Password strength</span>
          <span className={`text-xs font-medium ${strengthCount > 3 ? 'text-green-600' : 'text-gray-600'}`}>
            {level}
          </span>
        </div>
        <div className="w-full bg-gray-200 rounded-full h-1.5">
          <div 
            className={`h-1.5 rounded-full transition-all duration-300 ${color}`} 
            style={{ width: progressWidth }}
          />
        </div>
      </div>
      
      <h4 className="font-medium text-sm text-gray-700 mb-1">Requirements:</h4>
      <ul className="space-y-1">
        <RequirementItem met={strength.hasMinLength} text="At least 8 characters" />
        <RequirementItem met={strength.hasUppercase} text="At least 1 uppercase letter (A-Z)" />
        <RequirementItem met={strength.hasLowercase} text="At least 1 lowercase letter (a-z)" />
        <RequirementItem met={strength.hasNumber} text="At least 1 number (0-9)" />
        <RequirementItem met={strength.hasSpecial} text="At least 1 special character (!@#$...)" />
      </ul>
    </div>
  );
};

export default PasswordRequirements;