import React, { useEffect, useRef, useState } from "react";
import { CheckCircle2, XCircle, X, Zap, Loader } from "lucide-react";

/**
 * Kept your original data shapes from the older UI
 */
interface Post {
  title?: string;
  text?: string;
  images?: string[];
  links?: string[];
  link?: string;
  response?: string;
}
interface Group {
  title: string;
  links: string[];
}
interface Payload {
  action: string;
  post: Post;
  group: Group;
  timeInSeconds: number;
  activeIndex: string;
  activeIndexProducts: string;
  avoidNightTimePosting: boolean;
}

/**
 * PostingResultsModal
 * - preserves original storage + background messaging logic
 * - uses the new UI
 * - fixes the hide/show race so behavior matches the older component
 */
export default function PostingResultsModal() {
  const [isPostingInProgress, setIsPostingInProgress] = useState<boolean>(false);
  const [postingStatus, setPostingStatus] = useState<string>("");
  const [postsCompleted, setPostsCompleted] = useState<Post[]>([]);
  const [showModal, setShowModal] = useState<boolean>(false);
  const [modalHiddenByUser, setModalHiddenByUser] = useState<boolean>(false);

  // keep a ref for synchronous checks (used by some legacy branches)
  const modalHiddenRef = useRef<boolean>(modalHiddenByUser);
  // keep ref in sync whenever state changes
  useEffect(() => {
    modalHiddenRef.current = modalHiddenByUser;
  }, [modalHiddenByUser]);

  // avoid writing storage during initial restore
  const initializedRef = useRef(false);

  useEffect(() => {
    // Restore persisted state on mount
    chrome.storage.local.get(
      ["showModal", "modalHiddenByUser", "isPostingInProgress", "postingStatus", "postsCompleted"],
      (result) => {
        const hidden = !!result.modalHiddenByUser;
        setModalHiddenByUser(hidden);

        if (result.postsCompleted) {
          setPostsCompleted(result.postsCompleted);
        }

        if (result.postingStatus) setPostingStatus(result.postingStatus);
        if (result.isPostingInProgress) {
          setIsPostingInProgress(result.isPostingInProgress === "started");
        }

        // Decide initial showModal:
        // 1) If showModal explicitly present, respect it (but still hide if user hid it).
        // 2) Else if postsCompleted exists and user hasn't hidden modal -> show it.
        // 3) Else if isPostingInProgress -> show it.
        if (typeof result.showModal !== "undefined") {
          setShowModal(Boolean(result.showModal) && !hidden ? true : Boolean(result.showModal));
        } else if (result.postsCompleted && result.postsCompleted.length > 0 && !hidden) {
          setShowModal(true);
        } else if (result.isPostingInProgress) {
          setShowModal(true);
        }

        initializedRef.current = true;
      }
    );

    // double-check background worker
    chrome.runtime.sendMessage({ action: "isPostInPRogress" }, (response) => {
      if (response?.working) {
        chrome.storage.local.set({ showModal: true, modalHiddenByUser: false });
        setModalHiddenByUser(false);
        setShowModal(true);
        setIsPostingInProgress(true);
      }
    });

    // storage change handler (fixed to prefer incoming modalHiddenByUser when present)
    const handleStorageChange = (changes: any) => {
      if (changes.postingStatus) {
        setPostingStatus(changes.postingStatus.newValue || "");
      }

      if (changes.postsCompleted) {
        setPostsCompleted(changes.postsCompleted.newValue || []);
      }

      if (changes.isPostingInProgress) {
        const val = changes.isPostingInProgress.newValue;
        if (val === "started") {
          chrome.storage.local.set({ modalHiddenByUser: false, showModal: true });
          setModalHiddenByUser(false);
          setShowModal(true);
          setIsPostingInProgress(true);
        } else if (val === "done") {
          setIsPostingInProgress(false);
        }
      }

      // Update modalHiddenByUser first if present
      if (changes.modalHiddenByUser) {
        const newHidden = !!changes.modalHiddenByUser.newValue;
        setModalHiddenByUser(newHidden);
        if (newHidden) setShowModal(false);
      }

      // Handle showModal; use incoming modalHidden value if available, otherwise fall back to the current ref
      if (changes.showModal) {
        const newVal = changes.showModal.newValue;
        const incomingHidden =
          typeof changes.modalHiddenByUser !== "undefined"
            ? !!changes.modalHiddenByUser.newValue
            : modalHiddenRef.current;

        if (newVal) {
          // external open -> honor and clear any "hidden by user" flag
          setShowModal(true);
          setModalHiddenByUser(false);
          chrome.storage.local.set({ modalHiddenByUser: false });
        } else {
          // external close -> only close if the user actually wanted it hidden
          if (incomingHidden) {
            setShowModal(false);
          } else {
            // silent external close: restore showModal to true to avoid accidental hide
            chrome.storage.local.set({ showModal: true });
            setShowModal(true);
          }
        }
      }
    };

    chrome.storage.onChanged.addListener(handleStorageChange);
    return () => {
      chrome.storage.onChanged.removeListener(handleStorageChange);
    };
  }, []);

  // persist core state after initialization
  useEffect(() => {
    if (!initializedRef.current) return;
    chrome.storage.local.set({
      showModal,
      modalHiddenByUser,
      postingStatus,
      isPostingInProgress: isPostingInProgress ? "started" : "done",
      postsCompleted,
    });
  }, [showModal, modalHiddenByUser, postingStatus, isPostingInProgress, postsCompleted]);

  // Stop Posting: keep postsCompleted and ensure modal stays visible (unless user explicitly hid before)
  const handleStopPosting = () => {
    const doShow = !modalHiddenRef.current;
    chrome.storage.local.set(
      {
        isPostingInProgress: "done",
        postingStatus: "Posting stopped",
        showModal: doShow,
        modalHiddenByUser: doShow ? false : modalHiddenRef.current,
      },
      () => {
        setIsPostingInProgress(false);
        setPostingStatus("Posting stopped");
        setShowModal(doShow);
        setModalHiddenByUser(!doShow ? modalHiddenRef.current : false);
        chrome.runtime.sendMessage({ action: "stopPosting" });
      }
    );
  };

  // User closes modal: update UI immediately then persist intent
  const handleCloseModal = () => {
    setModalHiddenByUser(true);
    setShowModal(false);

    chrome.storage.local.set({ showModal: false, modalHiddenByUser: true }, () => {
      // persisted; nothing else required
    });
  };

  const clearCompleted = () => {
    setPostsCompleted([]);
    chrome.storage.local.remove(["postsCompleted"]);
  };

  // map postsCompleted -> results for the new UI
  const totalGroups = postsCompleted.length;
  const successCount = postsCompleted.filter((p) => p.response === "successful").length;
  const failedCount = totalGroups - successCount;
  const successRate = totalGroups > 0 ? (successCount / totalGroups) * 100 : 0;

  const results = postsCompleted.map((post, idx) => {
    const link = post.link || "";
    const parts = link.split("/").filter(Boolean);
    const last = parts.length > 0 ? parts[parts.length - 1] : link || `item-${idx + 1}`;
    return {
      groupId: link || `item-${idx + 1}`,
      groupName: last,
      status: post.response === "successful" ? "success" : "failed",
      raw: post,
    };
  });

  // render guard: use React state (not ref) so rendering matches state updates
  if (!showModal || modalHiddenByUser) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center overflow-y-auto overflow-x-hidden bg-black/50 p-4">
      <div className="relative w-[360px] h-[500px] bg-gradient-to-b from-white to-[#f8f9fa] flex flex-col overflow-hidden shadow-2xl rounded-lg">
        <div className="flex flex-col h-full">
          {/* Header */}
          <div className="bg-gradient-to-r from-[#1877f2] to-[#0a5dd6] p-4 flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <div className="w-8 h-8 bg-white/20 rounded-lg flex items-center justify-center backdrop-blur-sm">
                <Zap className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-lg font-bold text-white">Posting Results</h1>
            </div>
            <button
              onClick={handleCloseModal}
              className="text-white/80 hover:bg-white/20 p-1.5 rounded-full transition-all"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Stats / In-progress area */}
          {(isPostingInProgress && (!postingStatus.toLowerCase().includes("stopped")&&!postingStatus.toLowerCase().includes("successfully"))) ? (
            <div className="p-6 bg-white flex-1 flex flex-col items-center justify-center text-center">
              <Loader className="w-10 h-10 animate-spin mb-4 text-gray-700" />
              <p className="text-gray-700 text-base mb-4">{postingStatus || "Start posting"}</p>
              <div className="flex gap-3">
                <button
                  type="button"
                  className="rounded-md bg-red-600 px-4 py-2 text-white hover:bg-red-700 transition"
                  onClick={handleStopPosting}
                >
                  Stop Posting
                </button>
              </div>
            </div>
          ) : (
            <>
              {/* Stats Summary */}
              <div className="p-4 bg-white">
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center space-x-2">
                    <div className="w-10 h-10 bg-gradient-to-br from-[#42b72a] to-[#36a420] rounded-xl flex items-center justify-center shadow-lg">
                      <CheckCircle2 className="w-6 h-6 text-white" />
                    </div>
                    <div>
                      <div className="text-2xl font-bold text-[#42b72a]">{successCount}</div>
                      <div className="text-xs text-[#65676b]">Successful</div>
                    </div>
                  </div>
                  <div className="flex items-center space-x-2">
                    <div className="w-10 h-10 bg-gradient-to-br from-[#fa383e] to-[#d32f2f] rounded-xl flex items-center justify-center shadow-lg">
                      <XCircle className="w-6 h-6 text-white" />
                    </div>
                    <div>
                      <div className="text-2xl font-bold text-[#fa383e]">{failedCount}</div>
                      <div className="text-xs text-[#65676b]">Failed</div>
                    </div>
                  </div>
                </div>
                <div className="text-center pt-2 border-t border-[#e4e6eb]">
                  <div className="text-sm text-[#65676b]">
                    <span className="font-semibold text-[#050505]">{Math.round(successRate)}%</span> success rate from{" "}
                    <span className="font-semibold text-[#050505]">{totalGroups}</span> groups
                  </div>
                </div>
              </div>

              {/* Progress Bar */}
              <div className="px-4 pb-3 bg-white">
                <div className="relative w-full bg-[#e4e6eb] rounded-full h-2 overflow-hidden shadow-inner">
                  <div className="flex h-full">
                    <div
                      className="bg-gradient-to-r from-[#42b72a] to-[#36a420] transition-all duration-700 ease-out"
                      style={{ width: `${(successCount / Math.max(1, totalGroups)) * 100}%` }}
                    />
                    <div
                      className="bg-gradient-to-r from-[#fa383e] to-[#d32f2f] transition-all duration-700 ease-out"
                      style={{ width: `${(failedCount / Math.max(1, totalGroups)) * 100}%` }}
                    />
                  </div>
                </div>
              </div>

              {/* Results List */}
              <div className="flex-1 overflow-y-auto bg-[#f8f9fa] px-4 py-2">
                <div className="text-xs font-semibold text-[#65676b] uppercase tracking-wide mb-2">Groups</div>
                <div className="space-y-1.5">
                  {results.length > 0 ? (
                    results.map((result, index) => (
                      <div
                        key={index}
                        className="flex items-center justify-between bg-white px-3 py-2 rounded-lg hover:shadow-md transition-all duration-200 group"
                      >
                        <div className="flex items-center space-x-2.5 flex-1 min-w-0">
                          <div className="min-w-0 flex-1">
                            <div className="text-sm text-[#050505] truncate group-hover:text-[#1877f2] transition-colors">
                              {result.groupName || result.groupId}
                            </div>
                          </div>
                        </div>
                        <div className="flex-shrink-0 ml-2">
                          {result.status === "success" ? (
                            <div className="w-6 h-6 bg-[#42b72a]/10 rounded-full flex items-center justify-center">
                              <CheckCircle2 className="w-4 h-4 text-[#42b72a]" />
                            </div>
                          ) : (
                            <div className="w-6 h-6 bg-[#fa383e]/10 rounded-full flex items-center justify-center">
                              <XCircle className="w-4 h-4 text-[#fa383e]" />
                            </div>
                          )}
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="text-center text-gray-500">No completed posts</div>
                  )}
                </div>
              </div>

              {/* Action Bar */}
              <div className="p-3 bg-white border-t border-[#e4e6eb] flex items-center gap-3">
                <button
                  onClick={() => {
                    clearCompleted();
                  }}
                  className="flex-1 bg-white border border-gray-200 text-gray-700 font-medium py-2.5 rounded-lg transition-all hover:shadow-sm"
                >
                  Clear
                </button>
                <button
                  onClick={handleCloseModal}
                  className="flex-1 bg-gradient-to-r from-[#1877f2] to-[#0a5dd6] hover:from-[#166fe5] hover:to-[#0952c4] text-white font-semibold py-2.5 rounded-lg transition-all duration-200 shadow-lg hover:shadow-xl transform hover:scale-[1.02]"
                >
                  Done
                </button>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
