import React, { useEffect, useState } from "react";
import * as Icons from "lucide-react";
import { usePostStore } from "../../stores/postStore";

interface Tab {
  id: string;
  label: string;
  icon: keyof typeof Icons;
  badge?: boolean;
}

interface TabsProps {
  tabs: Tab[];
  activeTab: string;
  onChange: (tabId: string) => void;
}

export function Tabs({ tabs, activeTab, onChange }: TabsProps) {
  const { scheduledPosts } = usePostStore();
  const [scheduledPostCount, setScheduledPostCount] = useState(0);

  async function getScheduledPostCount() {
    return new Promise<number>((resolve) => {
      chrome.runtime.sendMessage(
        { action: "getScheduledPosts" },
        (response) => {
          if (chrome.runtime.lastError) {
            console.error("Message failed:", chrome.runtime.lastError.message);
            return resolve(0);
          }

          if (!response?.success || !Array.isArray(response.snapshots)) {
            console.warn("⚠️ Could not get snapshots:", response?.error);
            return resolve(0);
          }

          const now = new Date();

          const pendingCount = response.snapshots.filter((snapshot: any) => {
            const { metadata, status } = snapshot;
            const schedule = metadata?.schedule;

            if (!schedule || status === "success") return false;

            const { frequency, startDate, time, recurring } = schedule;
            const [hours, minutes] = time.split(":").map(Number);
            const baseDate = new Date(startDate);

            const scheduledDateTime = new Date(
              baseDate.getFullYear(),
              baseDate.getMonth(),
              baseDate.getDate(),
              hours,
              minutes,
              0,
              0
            );

            const deadline = new Date(
              scheduledDateTime.getTime() + 60 * 60 * 1000
            );

            switch (frequency) {
              case "once": {
                // Scheduled in future OR within 1-hour window
                return now < deadline;
              }

              case "daily": {
                const futureTime = new Date(
                  now.getFullYear(),
                  now.getMonth(),
                  now.getDate(),
                  hours,
                  minutes,
                  0,
                  0
                );
                const deadlineDaily = new Date(
                  futureTime.getTime() + 60 * 60 * 1000
                );
                return now < deadlineDaily;
              }

              case "weekly": {
                const currentDayId = now.getDay(); // 0-6, where 0 is Sunday
                if (recurring?.weekDays?.includes(currentDayId)) {
                  const weeklyTime = new Date(
                    now.getFullYear(),
                    now.getMonth(),
                    now.getDate(),
                    hours,
                    minutes,
                    0,
                    0
                  );
                  const deadlineWeekly = new Date(
                    weeklyTime.getTime() + 60 * 60 * 1000
                  );
                  return now < deadlineWeekly;
                }

                // If not today, check for any *upcoming* days
                if (Array.isArray(recurring?.weekDays)) {
                  return true; // pending in the future
                }

                return false;
              }

              case "monthly": {
                const todayDate = now.getDate();
                if (recurring?.monthDays?.includes(todayDate)) {
                  const monthlyTime = new Date(
                    now.getFullYear(),
                    now.getMonth(),
                    now.getDate(),
                    hours,
                    minutes,
                    0,
                    0
                  );
                  const deadlineMonthly = new Date(
                    monthlyTime.getTime() + 60 * 60 * 1000
                  );
                  return now < deadlineMonthly;
                }

                // If today not matched, check if any day in the future
                if (Array.isArray(recurring?.monthDays)) {
                  return recurring.monthDays.some((day) => day > todayDate);
                }

                return false;
              }

              default:
                return false;
            }
          }).length;

          resolve(pendingCount);
        }
      );
    });
  }

  useEffect(() => {
    (async () => {
      const count = await getScheduledPostCount();
      setScheduledPostCount(count);
    })();

    // Set up interval to check every 1 second
    const interval = setInterval(async () => {
      const count = await getScheduledPostCount();
      setScheduledPostCount(count);
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="bg-white border-b border-gray-200">
      <div className="flex">
        {tabs.map((tab) => {
          const Icon = Icons[tab.icon] as React.ComponentType<{ size: number }> | undefined;
          const isActive = activeTab === tab.id;
          const badgeCount = tab.id === "scheduled" ? scheduledPostCount : undefined;

          return (
            <button
              key={tab.id}
              onClick={() => onChange(tab.id)}
              className={`
                flex-1 flex items-center justify-center space-x-2 px-3 py-2 text-sm transition-colors
                ${isActive 
                  ? 'text-blue-600 border-b-2 border-blue-600 font-semibold' 
                  : 'text-neutral-700 hover:text-gray-800 font-medium'
                }
              `}
            >
              {Icon && <Icon size={16} />}
              <span>{tab.label}</span>
              {badgeCount !== undefined && badgeCount > 0 && (
                <span className="ml-2 inline-flex items-center h-5 px-2 text-xs bg-blue-50 text-blue-700 rounded-full font-medium border border-blue-200">
                  {badgeCount}
                </span>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}
