import React, { useEffect, useLayoutEffect, useState } from "react";
import { onAuthStateChanged, getAuth } from "firebase/auth/web-extension";
import { auth } from "./lib/firebase";

import { Tabs } from "./components/Common/Tabs.tsx";
import { PostScheduler } from "./components/PostScheduler/PostScheduler.tsx";
import { ScheduledPostsManager } from "./components/ScheduledPosts/ScheduledPostsManager.tsx";
import { TrialBanner } from "./components/Header/TrialBanner.tsx";
import { ErrorBoundary } from "./components/ErrorBoundary.tsx";
import { usePostStore } from "./stores/postStore.ts";
import AuthPage from "./components/AuthPage";

export default function App() {
  const [activeTab, setActiveTab] = useState("create");
  const { error, setError, postsRemaining, setPostsRemaining, height, width, isPremium, setIsPremium, fetchSubscription, subscriptionLoading, subscriptionLastFetched, clearSubscriptionCache } = usePostStore();
  const [previousState, setPreviousState] = useState(false);
  const [email, setEmail] = useState(null);
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const [isFetchingInitial, setIsFetchingInitial] = useState(false);

  // Listen for storage changes (event-driven, more efficient than polling)
  useEffect(() => {
    const onStorageChange = (changes, areaName) => {
      try {
        if (changes.postsRemaining) {
          const newVal = changes.postsRemaining.newValue;
          setPostsRemaining(typeof newVal === 'number' ? newVal : undefined);
        }
        if (changes.isPremium) {
          setIsPremium(Boolean(changes.isPremium.newValue));
        }
      } catch (e) {
        // ignore
      }
    };

    try {
      chrome.storage.onChanged.addListener(onStorageChange);
    } catch (e) {
      // not in extension env
    }

    // Initial read to populate store/state
    (async () => {
      try {
        const localRes = await chrome.storage.local.get(["postsRemaining", "isPremium"]);
        const currentPr = usePostStore.getState().postsRemaining;
        const currentPremium = usePostStore.getState().isPremium;
        
        if (typeof localRes?.postsRemaining !== 'undefined' && currentPr !== localRes.postsRemaining) {
          setPostsRemaining(localRes.postsRemaining);
        }
        if (typeof localRes?.isPremium !== 'undefined' && currentPremium !== Boolean(localRes.isPremium)) {
          setIsPremium(Boolean(localRes.isPremium));
        } else if (typeof localRes?.postsRemaining === 'undefined' || typeof localRes?.isPremium === 'undefined') {
          const syncRes = await chrome.storage.sync.get(["postsRemaining", "isPremium"]);
          if (typeof syncRes?.postsRemaining !== 'undefined' && currentPr !== syncRes.postsRemaining) {
            setPostsRemaining(syncRes.postsRemaining);
          }
          if (typeof syncRes?.isPremium !== 'undefined' && currentPremium !== Boolean(syncRes.isPremium)) {
            setIsPremium(Boolean(syncRes.isPremium));
          }
        }
      } catch (e) {}
    })();

    return () => {
      try {
        chrome.storage.onChanged.removeListener(onStorageChange);
      } catch (e) {}
    };
  }, [setPostsRemaining]);

  // Re-check storage shortly after mount (works around persisted store rehydration
  // which may overwrite values). This ensures the store reflects the latest
  // chrome.storage values without requiring a manual refresh.
  useEffect(() => {
    const recheck = async () => {
      try {
        const localRes = await chrome.storage.local.get(["postsRemaining", "isPremium"]);
        const pr = localRes?.postsRemaining;
        const premium = localRes?.isPremium;
        
        // Only update if values actually changed
        const currentPr = usePostStore.getState().postsRemaining;
        const currentPremium = usePostStore.getState().isPremium;
        
        if (typeof pr !== "undefined" && currentPr !== pr) {
          setPostsRemaining(pr);
        } else if (typeof pr === "undefined") {
          const syncRes = await chrome.storage.sync.get(["postsRemaining", "isPremium"]);
          if (typeof syncRes?.postsRemaining !== "undefined" && currentPr !== syncRes.postsRemaining) {
            setPostsRemaining(syncRes.postsRemaining);
          }
        }
        
        if (typeof premium !== "undefined" && currentPremium !== Boolean(premium)) {
          setIsPremium(Boolean(premium));
        } else if (typeof premium === "undefined") {
          const syncRes = await chrome.storage.sync.get(["isPremium"]);
          if (typeof syncRes?.isPremium !== "undefined" && currentPremium !== Boolean(syncRes.isPremium)) {
            setIsPremium(Boolean(syncRes.isPremium));
          }
        }
      } catch (e) {}
    };

    const timer = setTimeout(recheck, 700);
    return () => clearTimeout(timer);
  }, [setPostsRemaining, setIsPremium]);

  // Short-polling fallback: read storage every 1 second and update the store.
  // This guarantees the UI will reflect changes made elsewhere even if
  // `chrome.storage.onChanged` events are missed or the environment is flaky.
  useEffect(() => {
    let intervalId = null;

    const pollStorage = async () => {
      try {
        const localRes = await chrome.storage.local.get(["postsRemaining", "isPremium"]);
        let pr = localRes?.postsRemaining;
        let premium = localRes?.isPremium;

        if (typeof pr === "undefined" && typeof premium === "undefined") {
          const syncRes = await chrome.storage.sync.get(["postsRemaining", "isPremium"]);
          pr = syncRes?.postsRemaining;
          premium = syncRes?.isPremium;
        }

        // CRITICAL FIX: Only update if values actually changed to prevent infinite saves
        const currentPr = usePostStore.getState().postsRemaining;
        const currentPremium = usePostStore.getState().isPremium;
        
        if (typeof pr !== "undefined" && currentPr !== pr) setPostsRemaining(pr);
        if (typeof premium !== "undefined" && currentPremium !== Boolean(premium)) setIsPremium(Boolean(premium));
      } catch (e) {
        // ignore
      }
    };

    pollStorage();
    intervalId = setInterval(pollStorage, 1000);

    return () => {
      if (intervalId) clearInterval(intervalId);
    };
  }, [setPostsRemaining, setIsPremium]);

  chrome.storage.local.get("editListState").then((appState) => {
    if (appState.editListState) {
      setPreviousState(true);
    }
  });

  // <-- Remove the TypeScript type here
  const [authState, setAuthState] = useState("loading");

  // Function to force refresh premium status from server
  const refreshPremiumStatus = async (userEmail) => {
    if (!userEmail) return;
    try {
      const credits = await new Promise((resolve, reject) => {
        chrome.runtime.sendMessage(
          {
            action: "checkCredits",
            email: userEmail,
          },
          (response) => {
            if (chrome.runtime.lastError) {
              reject(chrome.runtime.lastError.message);
            } else {
              resolve(response);
            }
          }
        );
      });

      // CRITICAL FIX: background.js returns boolean isPremium, not "active" string
      // Only update if we got valid values back (not undefined)
      if (typeof credits?.subscription !== 'undefined') {
        const newIsPremium = Boolean(credits.subscription);
        const currentIsPremium = usePostStore.getState().isPremium;
        
        if (currentIsPremium !== newIsPremium) {
          // Update chrome storage
          await chrome.storage.sync.set({ isPremium: newIsPremium });
          // Update local state
          setIsPremium(newIsPremium);
          console.log("Premium status updated:", newIsPremium);
        }
      }
      
      if (typeof credits?.postsRemaining !== 'undefined') {
        const newPostsRemaining = credits.postsRemaining;
        const currentPostsRemaining = usePostStore.getState().postsRemaining;
        
        if (currentPostsRemaining !== newPostsRemaining) {
          // Update chrome storage
          await chrome.storage.sync.set({ postsRemaining: newPostsRemaining });
          // Update local state
          setPostsRemaining(newPostsRemaining);
          console.log("Posts remaining updated:", newPostsRemaining);
        }
      }
    } catch (error) {
      console.error("Failed to refresh premium status:", error);
      // Don't update state on error - keep existing values
    }
  };

  useEffect(() => {
    let isMounted = true;
    
    (async () => {
      try {
        // CRITICAL FIX: Get user from storage and show UI immediately
        let user = await chrome.storage.sync.get(["user"]);
        user = user?.user || null;
        
        async function waitForEmail() {
          return new Promise((resolve) => {
            setTimeout(() => {
              resolve();
            }, 1500);
          });
        }
        
        if (!user?.email) {
          chrome.storage.sync.remove(["isPremium"]);
          chrome.storage.sync.remove(["user"]);
          await waitForEmail();
          user = await chrome.storage.sync.get(["user"]);
          user = user?.user || null;
        }
        console.log("Now got it ", user);
        
        // CRITICAL FIX: Hide loader immediately after getting user (show cached UI)
        if (isMounted) {
          setIsInitialLoad(false);
          setIsFetchingInitial(false);
          console.log("[App] Mount: Showing UI with cached data");
        }
        
        // Fetch subscription in background (non-blocking) - updates happen silently
        if (user?.email && isMounted) {
          setEmail(user.email);
          console.log("[App] Mount: Starting background subscription fetch for:", user.email);
          // Clear cache and fetch fresh data in background without blocking UI
          clearSubscriptionCache();
          fetchSubscription(user.email, true).catch((error) => {
            console.error("[App] Mount: Background subscription fetch error:", error);
          });
        }
      } catch (error) {
        console.error("[App] Mount: Error during initialization:", error);
        // Even on error, hide loader to show UI
        if (isMounted) {
          setIsInitialLoad(false);
          setIsFetchingInitial(false);
        }
      }
    })();
    
    return () => {
      isMounted = false;
    };
  }, [fetchSubscription, clearSubscriptionCache]);

  // Listen for Firebase auth changes
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        setEmail(user.email);
        // Fetch subscription when auth state changes
        await fetchSubscription(user.email, true);
        setAuthState("authenticated");
      } else {
        // If not authenticated via Firebase, check extension-level login
        await chrome.runtime.sendMessage(
          { action: "checkLoginState" },
          (response) => {
            if (response?.loggedIn) {
              setAuthState("authenticated");
            } else {
              setAuthState("unauthenticated");
            }
          }
        );
      }
    });

    return () => unsubscribe();
  }, [fetchSubscription]);

  // Refresh premium status when popup becomes visible
  useEffect(() => {
    const handleVisibilityChange = async () => {
      if (!document.hidden) {
        try {
          const user = await chrome.storage.sync.get(["user"]);
          const userEmail = user?.user?.email || email;
          if (userEmail) {
            console.log("Popup became visible, refreshing premium status...");
            await refreshPremiumStatus(userEmail);
          }
        } catch (error) {
          console.error("Error refreshing on visibility change:", error);
        }
      }
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);
    return () => document.removeEventListener("visibilitychange", handleVisibilityChange);
  }, [email]);

  // Listen for messages from background script (e.g., webhook notifications)
  useEffect(() => {
    const messageListener = async (message, sender, sendResponse) => {
      if (message.action === "updatePopup" || message.action === "premiumStatusChanged") {
        console.log("Received update notification, refreshing premium status...");
        try {
          const user = await chrome.storage.sync.get(["user"]);
          const userEmail = user?.user?.email || email;
          if (userEmail) {
            await refreshPremiumStatus(userEmail);
          }
        } catch (error) {
          console.error("Error refreshing on message:", error);
        }
      }
    };

    chrome.runtime.onMessage.addListener(messageListener);
    return () => chrome.runtime.onMessage.removeListener(messageListener);
  }, [email]);

  const tabs = [
    { id: "create", label: "Create", icon: "PenSquare" },
    { id: "scheduled", label: "Scheduled", icon: "Calendar", badge: true },
  ];

  const handleTabChange = (tabId) => {
    setError(null);
    setActiveTab(tabId);
  };

  if (authState === "loading" && !previousState) {
    return (
      <div className="flex items-center justify-center h-screen bg-gray-100" style={{height:height}}>
        <div className="text-gray-600 animate-pulse text-xl font-medium">
          Checking login status...
        </div>
      </div>
    );
  }

  if (authState === "unauthenticated") {
    return <div style={{height:height}}><AuthPage /></div>;
  }

  // Show loading while fetching subscription (on initial load or when actively loading)
  // Use isFetchingInitial to ensure loader shows even if subscriptionLoading updates are missed
  // if (isFetchingInitial || (subscriptionLoading && isInitialLoad)) {
  //   return (
  //     <div className="flex flex-col items-center justify-center h-screen bg-gray-100" style={{height:height}}>
  //       <div className="flex flex-col items-center space-y-4">
  //         <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-blue-600"></div>
  //         {/* UI text hidden but logic still runs */}
  //       </div>
  //     </div>
  //   );
  // }

  return (
    <ErrorBoundary>
      <div className="w-full h-screen max-w-[390px] mx-auto bg-gray-50 flex flex-col" style={{height:"auto"}}>
        <TrialBanner
          setAuthState={setAuthState}
          postsLeft={postsRemaining}
          isPremium={isPremium}
          setIsPremium={setIsPremium}
          setPostsLeft={setPostsRemaining}
        />
        <Tabs tabs={tabs} activeTab={activeTab} onChange={handleTabChange} />

        <div className="flex-1 overflow-auto">
          {error && (
            <div className="p-3 bg-red-50 border-l-4 border-red-500 m-3">
              <p className="text-sm text-red-700">{error}</p>
            </div>
          )}

          {activeTab === "create" ? (
            <PostScheduler />
          ) : (
            <ScheduledPostsManager />
          )}
        </div>
      </div>
    </ErrorBoundary>
  );
}
