import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { X, Calendar, Clock, Repeat, Info } from 'lucide-react';
import { FrequencyButton } from './FrequencyButton';
import { DayButton } from './DayButton';
import { SelectedDayTag } from './SelectedDayTag';
import type { ScheduleConfig, WeekDay, MonthDay } from '../../types/scheduling';

interface CompactScheduleModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSchedule: (schedule: ScheduleConfig) => void;
  initialSchedule?: ScheduleConfig | null;
  group: any
}

export function CompactScheduleModal({
  isOpen,
  onClose,
  onSchedule,
  initialSchedule
}: CompactScheduleModalProps) {
  const [schedule, setSchedule] = useState<ScheduleConfig>(() => {
    const now = new Date();
    return initialSchedule || {
      startDate: now,
      time: now.toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit' }),
      frequency: 'once'
    };
  });

  const [selectedWeekDays, setSelectedWeekDays] = useState<WeekDay[]>([]);
  const [selectedMonthDays, setSelectedMonthDays] = useState<MonthDay[]>([]);

  const weekDays = useMemo(() => [
    { id: 0 as WeekDay, label: 'S', fullName: 'Sunday' },
    { id: 1 as WeekDay, label: 'M', fullName: 'Monday' },
    { id: 2 as WeekDay, label: 'T', fullName: 'Tuesday' },
    { id: 3 as WeekDay, label: 'W', fullName: 'Wednesday' },
    { id: 4 as WeekDay, label: 'T', fullName: 'Thursday' },
    { id: 5 as WeekDay, label: 'F', fullName: 'Friday' },
    { id: 6 as WeekDay, label: 'S', fullName: 'Saturday' }
  ], []);

  const monthDays = useMemo(() => 
    Array.from({ length: 31 }, (_, i) => ({
      day: (i + 1) as MonthDay,
      label: (i + 1).toString()
    })),
    []
  );

  const frequencies = useMemo(() => [
    { id: 'once', label: 'Once', showMultiSelect: false },
    { id: 'daily', label: 'Daily', showMultiSelect: false },
    { id: 'weekly', label: 'Weekly', showMultiSelect: true },
    { id: 'monthly', label: 'Monthly', showMultiSelect: true }
  ], []);

  const handleSubmit = useCallback((e: React.FormEvent) => {
    e.preventDefault();
    const recurring = schedule.frequency === 'weekly'
      ? { weekDays: selectedWeekDays }
      : schedule.frequency === 'monthly'
      ? { monthDays: selectedMonthDays }
      : undefined;

    // If weekly, compute a sensible startDate: the next occurrence of any selected weekday.
    const buildSchedule = { ...schedule, recurring } as ScheduleConfig;
    if (schedule.frequency === 'weekly' && Array.isArray(selectedWeekDays) && selectedWeekDays.length > 0) {
      const now = new Date();
      const [hour, minute] = (schedule.time || '').split(':').map(Number);

      const today = now.getDay(); // 0-6
      let minDays = Infinity;
      for (const wd of selectedWeekDays) {
        const dayIndex = Number(wd);
        if (Number.isNaN(dayIndex)) continue;
        let daysUntil = (dayIndex - today + 7) % 7;
        if (daysUntil === 0) {
          // If selected day is today, only keep today if scheduled time is still in the future
          if (typeof hour === 'number' && typeof minute === 'number') {
            const scheduledToday = new Date(now.getFullYear(), now.getMonth(), now.getDate(), hour, minute, 0, 0);
            if (scheduledToday.getTime() <= now.getTime()) {
              daysUntil = 7; // next week
            }
          }
        }
        if (daysUntil < minDays) minDays = daysUntil;
      }

      const nextDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() + (minDays === Infinity ? 0 : minDays), 0, 0, 0, 0);
      buildSchedule.startDate = nextDate;
    }

    onSchedule(buildSchedule);
    onClose();
  }, [schedule, selectedWeekDays, selectedMonthDays, onSchedule, onClose]);

  useEffect(() => {
    if (initialSchedule) {
      setSchedule(initialSchedule);
      setSelectedWeekDays(initialSchedule.recurring?.weekDays || []);
      setSelectedMonthDays(initialSchedule.recurring?.monthDays || []);
    }
  }, [initialSchedule]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/30 z-50 flex items-center justify-center">
      <div className="bg-white w-full max-w-[380px] rounded-2xl shadow-xl mx-4 overflow-hidden animate-scale-in">
        {/* Header */}
        <div className="relative h-14 bg-gradient-to-br from-blue-500 via-blue-600 to-blue-700 px-4 flex items-center justify-between">
          <div>
            <h2 className="text-lg font-semibold text-white">Schedule Post</h2>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 hover:bg-white/10 rounded-full transition-colors text-white"
          >
            <X size={16} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-3">
          {/* Basic Schedule Section */}
          <div className="flex gap-2 mb-3">
            <div className="flex-1">
              <label className="block text-xs font-medium text-gray-500 mb-1">Date</label>
              <div className="relative">
                <Calendar className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <input
                  type="date"
                  value={(() => {
                    const d = new Date(schedule.startDate);
                    const year = d.getFullYear();
                    const month = String(d.getMonth() + 1).padStart(2, '0');
                    const date = String(d.getDate()).padStart(2, '0');
                    return `${year}-${month}-${date}`;
                  })()}
                  onChange={(e) => {
                    const [year, month, day] = e.target.value.split('-').map(Number);
                    const newDate = new Date(year, month - 1, day, 0, 0, 0, 0);
                    setSchedule({ ...schedule, startDate: newDate });
                  }}
                  min={(() => {
                    const today = new Date();
                    const year = today.getFullYear();
                    const month = String(today.getMonth() + 1).padStart(2, '0');
                    const date = String(today.getDate()).padStart(2, '0');
                    return `${year}-${month}-${date}`;
                  })()}
                  className="w-full pl-8 pr-2 py-1.5 bg-gray-50 border border-gray-200 rounded-lg text-sm transition-all hover:border-gray-300 focus:ring-1 focus:ring-blue-500"
                />
              </div>
            </div>
            <div className="w-32">
              <label className="block text-xs font-medium text-gray-500 mb-1">Time</label>
              <div className="relative">
                <Clock className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <input
                  type="time"
                  value={schedule.time}
                  onChange={(e) => setSchedule({ ...schedule, time: e.target.value })}
                  className="w-full pl-8 pr-2 py-1.5 bg-gray-50 border border-gray-200 rounded-lg text-sm transition-all hover:border-gray-300 focus:ring-1 focus:ring-blue-500"
                />
              </div>
            </div>
          </div>

          {/* Frequency Selection */}
          <div className="mb-3">
            <label className="block text-xs font-medium text-gray-500 mb-1">Repeat</label>
            <div className="grid grid-cols-2 gap-2">
              {frequencies.map((freq) => (
                <FrequencyButton
                  key={freq.id}
                  frequency={freq.id}
                  isSelected={schedule.frequency === freq.id}
                  onClick={() => setSchedule({ ...schedule, frequency: freq.id as any })}
                  showMultiSelect={freq.showMultiSelect}
                />
              ))}
            </div>
          </div>

          {/* Weekly Selection */}
          {schedule.frequency === 'weekly' && (
            <div className="mb-3">
              <label className="block text-xs font-medium text-gray-500 mb-1">Select Days</label>
              <div className="grid grid-cols-7 gap-1">
                {weekDays.map((day) => (
                  <DayButton
                    key={day.id}
                    label={day.label}
                    isSelected={selectedWeekDays.includes(day.id as WeekDay)}
                    onClick={() => {
                      setSelectedWeekDays(prev =>
                        prev.includes(day.id as WeekDay)
                          ? prev.filter(d => d !== day.id as WeekDay)
                          : [...prev, day.id as WeekDay]
                      );
                    }}
                  />
                ))}
              </div>
              {selectedWeekDays.length > 0 && (
                <div className="mt-2 flex flex-wrap gap-1">
                  {selectedWeekDays
                    .sort((a, b) => {
                      const dayOrder = weekDays.findIndex(d => d.id === a) - weekDays.findIndex(d => d.id === b);
                      return dayOrder;
                    })
                    .map(day => {
                      const dayInfo = weekDays.find(d => d.id === day);
                      return (
                        <SelectedDayTag
                          key={day}
                          label={dayInfo?.fullName || day}
                          onRemove={() => {
                            setSelectedWeekDays(prev => prev.filter(d => d !== day));
                          }}
                        />
                      );
                    })}
                </div>
              )}
            </div>
          )}

          {/* Monthly Selection */}
          {schedule.frequency === 'monthly' && (
            <div className="mb-3">
              <label className="block text-xs font-medium text-gray-500 mb-1">Select Dates</label>
              <div className="grid grid-cols-8 gap-0.5">
                {monthDays.map(({ day, label }) => (
                  <button
                    key={day}
                    type="button"
                    onClick={() => {
                      setSelectedMonthDays(prev =>
                        prev.includes(day)
                          ? prev.filter(d => d !== day)
                          : [...prev, day]
                      );
                    }}
                    className={`
                      h-8 text-xs font-medium rounded transition-all
                      ${selectedMonthDays.includes(day)
                        ? 'bg-blue-600 text-white'
                        : 'bg-gray-50 text-gray-700 hover:bg-gray-100 border border-gray-200'
                      }
                    `}
                  >
                    {label}
                  </button>
                ))}
              </div>
              {selectedMonthDays.length > 0 && (
                <div className="mt-1.5 flex flex-wrap gap-1">
                  {[...selectedMonthDays]
                    .sort((a, b) => a - b)
                    .map(day => (
                      <span 
                        key={day}
                        className="inline-flex items-center px-1.5 py-0.5 rounded bg-blue-50 text-blue-700 text-xs"
                      >
                        {day}
                        <button
                          onClick={() => {
                            setSelectedMonthDays(prev => prev.filter(d => d !== day));
                          }}
                          className="ml-1 text-blue-400 hover:text-blue-600"
                        >
                          ×
                        </button>
                      </span>
                    ))}
                </div>
              )}
            </div>
          )}

          {/* Submit Button */}
          <button
            type="submit"
            disabled={
              (schedule.frequency === 'weekly' && selectedWeekDays.length === 0) ||
              (schedule.frequency === 'monthly' && selectedMonthDays.length === 0)
            }
            className="w-full px-4 py-2 bg-gradient-to-r from-blue-600 to-blue-700 text-white rounded-lg font-medium transition-all hover:from-blue-700 hover:to-blue-800 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Schedule Post
          </button>
        </form>
      </div>
    </div>
  );
}

function getOrdinalSuffix(day: number): string {
  if (day > 3 && day < 21) return 'th';
  switch (day % 10) {
    case 1: return 'st';
    case 2: return 'nd';
    case 3: return 'rd';
    default: return 'th';
  }
}