import React from 'react';
import { X, Bold, Italic, Underline, Heading1, Heading2, List, ListOrdered } from 'lucide-react';

interface FormattingHelpDialogProps {
  isOpen: boolean;
  onClose: () => void;
}

export function FormattingHelpDialog({ isOpen, onClose }: FormattingHelpDialogProps) {
  if (!isOpen) return null;

  const formatExamples = [
    {
      id: 'bold',
      icon: Bold,
      name: 'Bold',
      shortcut: 'Ctrl+B',
      description: 'Makes text bold'
    },
    {
      id: 'italic',
      icon: Italic,
      name: 'Italic',
      shortcut: 'Ctrl+I',
      description: 'Makes text italic'
    },
    {
      id: 'underline',
      icon: Underline,
      name: 'Underline',
      shortcut: 'Ctrl+U',
      description: 'Underlines text'
    },
    {
      id: 'h1',
      icon: Heading1,
      name: 'Heading 1',
      shortcut: '',
      description: 'Large heading'
    },
    {
      id: 'h2',
      icon: Heading2,
      name: 'Heading 2',
      shortcut: '',
      description: 'Medium heading'
    },
    {
      id: 'ul',
      icon: List,
      name: 'Bulleted List',
      shortcut: '',
      description: 'Creates a bulleted list'
    },
    {
      id: 'ol',
      icon: ListOrdered,
      name: 'Numbered List',
      shortcut: '',
      description: 'Creates a numbered list'
    }
  ];

  return (
    <div className="fixed inset-0 bg-black/30 z-[60] flex items-center justify-center">
      <div className="bg-white w-full max-w-md rounded-xl shadow-xl mx-4 animate-scale-in">
        <div className="flex items-center justify-between px-4 py-3 border-b">
          <h2 className="text-lg font-semibold text-gray-900">Text Formatting Guide</h2>
          <button
            onClick={onClose}
            className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-full transition-colors"
          >
            <X size={18} />
          </button>
        </div>
        
        <div className="p-4 max-h-[70vh] overflow-y-auto">
          <p className="text-sm text-gray-600 mb-4">
            Select text and click a formatting button to format your text.
          </p>
          
          <div className="space-y-4">
            {formatExamples.map((format) => {
              const Icon = format.icon;
              
              return (
                <div key={format.id} className="border rounded-lg p-3 hover:border-blue-200 transition-colors">
                  <div className="flex items-center space-x-2 mb-2">
                    <div className="p-1.5 bg-blue-50 rounded-md">
                      <Icon size={16} className="text-blue-600" />
                    </div>
                    <div className="flex-1">
                      <h3 className="text-sm font-medium text-gray-900">{format.name}</h3>
                      <p className="text-xs text-gray-500">{format.description}</p>
                    </div>
                    {format.shortcut && (
                      <div className="text-xs bg-gray-100 px-2 py-1 rounded font-mono text-gray-600">
                        {format.shortcut}
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
        
        <div className="border-t p-4">
          <button
            onClick={onClose}
            className="w-full px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium transition-colors"
          >
            Got it
          </button>
        </div>
      </div>
    </div>
  );
}