import React from 'react';
import { AlertTriangle } from 'lucide-react';

interface DeleteGroupDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  groupName: string;
}

export function DeleteGroupDialog({ isOpen, onClose, onConfirm, groupName }: DeleteGroupDialogProps) {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-md w-full p-6 space-y-5">
        <div className="flex items-start gap-4">
          <div className="flex-shrink-0 w-12 h-12 bg-red-100 rounded-full flex items-center justify-center">
            <AlertTriangle size={24} className="text-red-600" />
          </div>
          <div className="flex-1">
            <h2 className="text-lg font-semibold text-gray-900 mb-2">
              Delete List
            </h2>
            <p className="text-gray-600 text-sm leading-relaxed">
              Are you sure you want to delete "<span className="font-semibold text-gray-900">{groupName}</span>"?
            </p>
            <p className="text-gray-500 text-xs mt-2">
              This action cannot be undone.
            </p>
          </div>
        </div>

        <div className="flex items-center gap-3 pt-2">
          <button
            onClick={onClose}
            className="flex-1 px-4 py-2.5 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-lg font-medium transition-all text-sm"
          >
            Cancel
          </button>
          <button
            onClick={() => {
              onConfirm();
              onClose();
            }}
            className="flex-1 px-4 py-2.5 bg-red-600 hover:bg-red-700 text-white rounded-lg font-medium transition-all text-sm shadow-sm hover:shadow"
          >
            Delete
          </button>
        </div>
      </div>
    </div>
  );
}
