import React, { useState } from 'react';
import { ChevronRight } from 'lucide-react';
import { useDeliveryOptions } from './Spintax/hooks/useDeliveryOptions';
import type { DeliveryOptions } from './Spintax/hooks/useDeliveryOptions';
import { DeliveryOptionsDialog } from './DeliveryOptionsDialog';

interface DeliveryOptionsProps {
  targetCount: number;
  context: 'schedule' | 'composer';
  onApply?: (options: DeliveryOptions) => void;
  isEnabled?: boolean;
}

export function DeliveryOptions({ targetCount, context, onApply, isEnabled = true }: DeliveryOptionsProps) {
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const options = useDeliveryOptions((state) => state.options);

  const getModeLabel = () => {
    if (options.mode === 'throttled') {
      return 'Throttled';
    }
    return 'Continuous';
  };

  return (
    <>
      <button
        onClick={() => setIsDialogOpen(true)}
        disabled={!isEnabled}
        className="w-full flex items-center justify-between py-3 px-4 bg-white border-b border-neutral-200 hover:bg-neutral-50 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
      >
        {/* Left: Label */}
        <span className="text-sm text-neutral-600">
          Delivery pacing
        </span>

        {/* Right: Mode indicator + Chevron */}
        <div className="flex items-center gap-2">
          <div className={`
            flex items-center justify-center h-8 px-3 rounded-full text-sm font-medium transition-all
            ${true 
              ? 'bg-blue-600 text-white' 
              : 'bg-neutral-200 text-neutral-600'
            }
          `}>
            {getModeLabel().toUpperCase()}
          </div>
          <ChevronRight size={20} className="text-neutral-400" />
        </div>
      </button>

      {isDialogOpen && (
        <DeliveryOptionsDialog
          targetCount={targetCount}
          context={context}
          onClose={() => setIsDialogOpen(false)}
          onApply={onApply}
        />
      )}
    </>
  );
}
